window.AULAS["farma-gilmar-01"] = {"subtitulo": "Introdução: vocabulário, formas farmacêuticas, áreas e nomenclatura", "pdf": "pdf/gilmar/aula-01.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 1 · Fármaco (Prof. Dr. Gilmar S. Erzinger)", "Brunton e Knollmann (Goodman & Gilman); Katzung (Farmacologia Básica e Clínica); OMS (Guide to Good Prescribing), citados nos slides", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Radicais da DCB: o nome revela a classe (slide 9)", "colunas": ["Radical", "Classe", "Exemplos"], "linhas": [["-olol", "Betabloqueadores", "propranolol, atenolol, metoprolol"], ["-pril", "Inibidores da ECA", "captopril, enalapril, ramipril"], ["-sartana", "Bloqueadores do receptor AT1", "losartana, valsartana, olmesartana"], ["-statina", "Inibidores da HMG-CoA redutase", "sinvastatina, atorvastatina, rosuvastatina"], ["-prazol", "Inibidores da bomba de prótons", "omeprazol, pantoprazol, esomeprazol"], ["-azepam / -azolam", "Benzodiazepínicos", "diazepam, clonazepam, midazolam"], ["-gliflozina", "Inibidores do SGLT2", "dapagliflozina, empagliflozina"], ["-mabe", "Anticorpos monoclonais", "rituximabe, adalimumabe, pembrolizumabe"]]}, "resumo": [{"titulo": "1. Vocabulário básico", "pontos": [{"t": "Fármaco × medicamento × droga × remédio", "sub": ["Fármaco é a substância química de estrutura definida que tem efeito farmacológico. É o princípio ativo; a amoxicilina é o exemplo da aula (slide 2).", "Medicamento é o produto farmacêutico tecnicamente elaborado, com finalidade profilática, curativa, paliativa ou diagnóstica. Ele reúne fármaco, excipientes e forma farmacêutica (slide 2).", "Droga é um termo amplo para qualquer substância que altera funções do organismo. No uso leigo, a palavra fica associada a substâncias de abuso (slide 2).", "Remédio é tudo o que alivia ou cura, inclusive medidas não farmacológicas, como repouso, fisioterapia e dieta (slide 2). Por isso, nem todo remédio é fármaco."]}, {"t": "Placebo e nocebo", "sub": ["Placebo é uma preparação sem ativo farmacológico específico. O efeito placebo é real e interfere nos resultados de ensaios clínicos (slide 2).", "Nocebo é o efeito negativo que ocorre sem ação do princípio ativo. Também precisa ser controlado no desenho dos ensaios (slide 2; complementa Goodman & Gilman)."]}]}, {"titulo": "2. Formas farmacêuticas", "pontos": [{"t": "Por que existem", "sub": ["A forma farmacêutica é a apresentação física que facilita a administração, garante segurança e otimiza o efeito do princípio ativo (slide 3).", "Ela garante precisão de dose, estabilidade e facilidade de transporte (slide 4)."]}, {"t": "Sólidas", "sub": ["Comprimidos são pós comprimidos por pressão. Podem ser efervescentes, sublinguais ou revestidos (slide 4).", "Cápsulas são invólucros, geralmente de gelatina, que encerram o ativo sólido ou líquido (slide 4).", "Drágeas são comprimidos com revestimento de açúcar e outras substâncias. Servem para mascarar sabor ou proteger o ativo no estômago (slide 4).", "Supositórios e óvulos derretem à temperatura corporal, para uso retal ou vaginal (slide 4)."]}, {"t": "Semissólidas", "sub": ["São de consistência intermediária e aplicadas na pele ou mucosas, para efeito local ou regional (slide 5).", "Pomadas são as mais gordurosas e oclusivas. Cremes são emulsões de óleo e água, de fácil espalhamento e menos oleosos. Géis têm base aquosa com agente que confere consistência firme (slide 5)."]}, {"t": "Líquidas e gasosas", "sub": ["Soluções têm o fármaco totalmente dissolvido. Suspensões têm partículas sólidas dispersas e exigem agitação antes do uso. Xaropes e elixires têm alta concentração de açúcar ou adoçantes (slide 6).", "As formas líquidas são boas para rápida absorção e para pacientes com dificuldade de deglutição, como crianças e idosos (slide 6).", "Aerossóis e sprays dispersam o medicamento em gotículas. Inalantes são gases ou vapores que vão diretamente aos pulmões (slide 7)."]}]}, {"titulo": "3. Áreas da farmacologia", "pontos": [{"t": "Farmacocinética (ADME)", "sub": ["Descreve o que o organismo faz com o fármaco: absorção, distribuição, metabolismo e excreção (slide 8). É a base para entender dose e intervalo, tema da aula 2."]}, {"t": "Farmacodinâmica", "sub": ["Descreve o que o fármaco faz com o organismo: alvos, mecanismos de ação e relação dose-efeito (slide 8)."]}, {"t": "Farmacoterapia e farmacovigilância", "sub": ["Farmacoterapia é o uso clínico: escolha do fármaco, dose, via, duração e monitoramento (slide 8).", "Farmacovigilância detecta, avalia e previne reações adversas após a comercialização (slide 8). A aula 3 mostra essa fase em detalhe."]}, {"t": "Áreas transversais", "sub": ["Toxicologia, farmacogenética e farmacoepidemiologia atravessam todas as áreas acima (slide 8)."]}]}, {"titulo": "4. Nomenclatura: a DCB e os radicais", "pontos": [{"t": "Denominação Comum Brasileira", "sub": ["A DCB segue a lógica dos radicais da DCI, da OMS. O sufixo do nome revela a classe do fármaco (slide 9).", "Radicais citados na aula: -olol (betabloqueadores), -pril (inibidores da ECA), -sartana (bloqueadores do receptor AT1), -statina (inibidores da HMG-CoA redutase), -prazol (inibidores da bomba de prótons), -azepam e -azolam (benzodiazepínicos), -gliflozina (inibidores do SGLT2) e -mabe (anticorpos monoclonais) (slide 9)."]}, {"t": "Cuidado com as exceções", "sub": ["Nem todo nome parecido indica a mesma classe. A aula manda confirmar sempre (slide 9). Por isso, o radical orienta, mas não substitui a checagem na bula ou na base de dados."]}]}, {"titulo": "5. Como descrever um medicamento", "pontos": [{"t": "Estrutura em cinco itens", "sub": ["1. Classe e mecanismo: alvo molecular e efeito fisiológico resultante.", "2. Farmacocinética: via, biodisponibilidade, meia-vida (t½), metabolismo pelo CYP e eliminação renal.", "3. Usos clínicos: indicações principais e de escolha em diretrizes.", "4. Segurança: RAM frequentes e graves, contraindicações e gestação.", "5. Interações e monitoramento: níveis, exames e sinais clínicos a acompanhar (slide 10)."]}]}, {"titulo": "6. Fontes confiáveis e raciocínio terapêutico", "pontos": [{"t": "Fontes por nível", "sub": ["Livros-texto: Goodman & Gilman, Katzung (Farmacologia Básica e Clínica), Rang & Dale e Golan (slide 11).", "Bulário e registros: Bulário Eletrônico da ANVISA, RENAME e Formulário Terapêutico Nacional (slide 11).", "Diretrizes: PCDT do Ministério da Saúde e CONITEC, além de diretrizes de sociedades médicas (slide 11).", "Bases clínicas: UpToDate, Micromedex e DynaMed, para dose, ajuste renal e interações (slide 11).", "Literatura primária: ensaios clínicos e revisões sistemáticas, como as da Cochrane, via PubMed (slide 11)."]}, {"t": "Os seis passos da OMS", "sub": ["Guia para a Boa Prescrição da OMS: 1) definir o problema; 2) objetivo terapêutico; 3) escolher o tratamento; 4) prescrever; 5) informar o paciente; 6) monitorar resposta, RAM e decisão de manter ou parar (slide 12; OMS, 1994)."]}]}, {"titulo": "7. Boas práticas de estudo e caso clínico", "pontos": [{"t": "Erros comuns × boas práticas", "sub": ["Evitar: decorar listas sem mecanismo, estudar só nomes comerciais, reler resumos no lugar de resolver questões (slide 13).", "Preferir: mecanismo → efeitos → RAM → interações; DCB sempre; revisões curtas e espaçadas; questões e casos desde o início (slide 13).", "Referência de método: Dunlosky et al. (2013), sobre técnicas de aprendizagem com evidência (slide 15)."]}, {"t": "Caso do enalapril", "sub": ["Mulher de 58 anos, hipertensa e diabética, com tosse seca em uso de enalapril (slide 14).", "O radical -pril identifica o inibidor da ECA. A tosse é explicada pelo acúmulo de bradicinina (pista do slide 14).", "Uma classe alternativa que mantém o benefício renal e não causa tosse é o bloqueador AT1 (-sartana), como a losartana (slide 14).", "Complemento não citado no slide: monitorar função renal e potássio nessas classes, conforme diretrizes."]}]}, {"titulo": "8. Conceitos fundamentais e o que o professor cobra", "pontos": [{"t": "O que o professor cobra", "sub": ["\"Não decorem fármacos\": cai o receptor, o que ele faz quando estimulado ou bloqueado, e os conceitos de agonista, antagonista, seletivo e não seletivo.", "Formato anunciado: enunciado descritivo que descreve a ação de um fármaco e pergunta em qual receptor ele atua, ou o contrário."]}, {"t": "Termos", "sub": ["Fármaco: princípio ativo, a molécula responsável pelo efeito.", "Medicamento: fármaco formulado (comprimido, cápsula), testado nas fases clínicas, registrado e com bula aprovada por órgão regulador.", "Remédio: qualquer coisa que faça bem, sem comprovação científica (um chá, uma terapia).", "Droga: fármaco ou medicamento em dose ou uso fora do projetado, quando a toxicidade supera o benefício.", "Placebo: formulação idêntica sem o princípio ativo, usada para separar efeito farmacológico de efeito psicológico."]}, {"t": "Atenção para a prova: desenho do estudo", "sub": ["Randomização: alocação aleatória dos participantes aos grupos, com perfis equivalentes de sexo e faixa etária, para que diferenças observadas não decorram de diferenças entre os grupos.", "Duplo-cego: nem o participante nem o pesquisador sabem quem recebeu o ativo.", "Controle: grupo de comparação, que recebe placebo, tratamento padrão ou outra dose.", "O professor disse que cobraria o conceito, não os exemplos numéricos dos slides."]}]}], "glossario": [{"termo": "Fármaco", "tecnica": "Vocabulário", "definicao": "Substância química de estrutura definida, com efeito farmacológico; o princípio ativo.", "slide": 2}, {"termo": "Medicamento", "tecnica": "Vocabulário", "definicao": "Produto farmacêutico elaborado, com fármaco, excipientes e forma farmacêutica.", "slide": 2}, {"termo": "Nocebo", "tecnica": "Vocabulário", "definicao": "Efeito negativo que ocorre sem ação do princípio ativo, real e que interfere nos ensaios.", "slide": 2}, {"termo": "Drágea", "tecnica": "Forma sólida", "definicao": "Comprimido com revestimento de açúcar e outras substâncias, para mascarar sabor ou proteger o ativo no estômago.", "slide": 4}, {"termo": "DCB", "tecnica": "Nomenclatura", "definicao": "Denominação Comum Brasileira, baseada nos radicais da DCI/OMS.", "slide": 9}, {"termo": "Farmacovigilância", "tecnica": "Área da farmacologia", "definicao": "Detecção, avaliação e prevenção de reações adversas após a comercialização.", "slide": 8}, {"termo": "Droga", "tecnica": "Vocabulário", "definicao": "Termo amplo para qualquer substância que altera funções do organismo. No uso leigo, associa-se a substâncias de abuso.", "slide": 2}, {"termo": "Remédio", "tecnica": "Vocabulário", "definicao": "Tudo o que alivia ou cura, inclusive medidas não farmacológicas, como repouso, fisioterapia e dieta.", "slide": 2}, {"termo": "Excipiente", "tecnica": "Vocabulário", "definicao": "Componente do medicamento que não é o princípio ativo. Junto com o fármaco e a forma farmacêutica, compõe o medicamento.", "slide": 2}, {"termo": "Comprimido efervescente, sublingual e revestido", "tecnica": "Forma sólida", "definicao": "Variações do comprimido: efervescente se dissolve em água; sublingual é absorvido sob a língua; revestido tem camada externa.", "slide": 4}, {"termo": "Cápsula", "tecnica": "Forma sólida", "definicao": "Invólucro, geralmente de gelatina, que encerra o princípio ativo sólido ou líquido.", "slide": 4}, {"termo": "Supositório e óvulo", "tecnica": "Forma sólida", "definicao": "Formas que derretem à temperatura corporal, para uso retal (supositório) ou vaginal (óvulo).", "slide": 4}, {"termo": "Pomada", "tecnica": "Forma semissólida", "definicao": "Formulação mais gordurosa e oclusiva, de uso na pele ou em mucosas.", "slide": 5}, {"termo": "Creme", "tecnica": "Forma semissólida", "definicao": "Emulsão de óleo e água, de fácil espalhamento e menos oleosa que a pomada.", "slide": 5}, {"termo": "Gel", "tecnica": "Forma semissólida", "definicao": "Preparação de base aquosa, com agente que confere consistência firme.", "slide": 5}, {"termo": "Solução", "tecnica": "Forma líquida", "definicao": "Mistura homogênea em que o fármaco está totalmente dissolvido.", "slide": 6}, {"termo": "Suspensão", "tecnica": "Forma líquida", "definicao": "Líquido com partículas sólidas dispersas. Exige agitação antes do uso.", "slide": 6}, {"termo": "Xarope e elixir", "tecnica": "Forma líquida", "definicao": "Preparações de alta concentração de açúcar ou adoçantes, aquosas ou hidroalcoólicas.", "slide": 6}, {"termo": "Aerossol e spray", "tecnica": "Forma gasosa", "definicao": "Sistema que dispersa o medicamento em gotículas ou partículas no ar.", "slide": 7}, {"termo": "Inalante", "tecnica": "Forma gasosa", "definicao": "Gás ou vapor direcionado aos pulmões.", "slide": 7}, {"termo": "Farmacocinética (ADME)", "tecnica": "Área da farmacologia", "definicao": "Descreve o que o organismo faz com o fármaco: absorção, distribuição, metabolismo e excreção.", "slide": 8}, {"termo": "Farmacodinâmica", "tecnica": "Área da farmacologia", "definicao": "Descreve o que o fármaco faz com o organismo: alvos, mecanismos de ação e relação dose-efeito.", "slide": 8}, {"termo": "Farmacoterapia", "tecnica": "Área da farmacologia", "definicao": "Uso clínico do fármaco: escolha, dose, via, duração e monitoramento.", "slide": 8}, {"termo": "Toxicologia, farmacogenética e farmacoepidemiologia", "tecnica": "Áreas transversais", "definicao": "Áreas que atravessam as outras: efeitos tóxicos, genética da resposta e uso de medicamentos em populações.", "slide": 8}, {"termo": "Sufixo -olol", "tecnica": "Radical", "definicao": "Betabloqueadores. Ex.: propranolol, atenolol, metoprolol.", "slide": 9}, {"termo": "Sufixo -pril", "tecnica": "Radical", "definicao": "Inibidores da enzima conversora de angiotensina (ECA). Ex.: captopril, enalapril.", "slide": 9}, {"termo": "Sufixo -sartana", "tecnica": "Radical", "definicao": "Bloqueadores do receptor AT1 da angiotensina II. Ex.: losartana, valsartana.", "slide": 9}, {"termo": "Sufixo -statina", "tecnica": "Radical", "definicao": "Inibidores da HMG-CoA redutase, usados para reduzir o colesterol. Ex.: sinvastatina.", "slide": 9}, {"termo": "Sufixo -prazol", "tecnica": "Radical", "definicao": "Inibidores da bomba de prótons (H⁺/K⁺ ATPase). Ex.: omeprazol.", "slide": 9}, {"termo": "Sufixo -azepam e -azolam", "tecnica": "Radical", "definicao": "Benzodiazepínicos, que potencializam o GABA. Ex.: diazepam, midazolam.", "slide": 9}, {"termo": "Sufixo -gliflozina", "tecnica": "Radical", "definicao": "Inibidores do cotransportador SGLT2, que aumentam a glicosúria. Ex.: dapagliflozina.", "slide": 9}, {"termo": "Sufixo -mabe", "tecnica": "Radical", "definicao": "Anticorpos monoclonais. Ex.: rituximabe, adalimumabe.", "slide": 9}, {"termo": "Goodman & Gilman", "tecnica": "Fonte", "definicao": "Principal livro-texto de farmacologia, citado como referência da aula.", "slide": 11}, {"termo": "Katzung (Farmacologia Básica e Clínica)", "tecnica": "Fonte", "definicao": "Livro-texto de farmacologia clínica, citado como referência.", "slide": 11}, {"termo": "Rang & Dale", "tecnica": "Fonte", "definicao": "Livro-texto de farmacologia, citado como referência.", "slide": 11}, {"termo": "RENAME", "tecnica": "Fonte", "definicao": "Relação Nacional de Medicamentos Essenciais, do Ministério da Saúde.", "slide": 11}, {"termo": "Bulário Eletrônico da Anvisa", "tecnica": "Fonte", "definicao": "Base oficial de bulas para o profissional de saúde.", "slide": 11}, {"termo": "PCDT e CONITEC", "tecnica": "Fonte", "definicao": "Protocolos Clínicos e Diretrizes Terapêuticas do Ministério da Saúde, com avaliação da CONITEC.", "slide": 11}, {"termo": "Guia para a Boa Prescrição (OMS)", "tecnica": "Raciocínio terapêutico", "definicao": "Guia com seis passos: definir o problema, objetivo, escolher tratamento, prescrever, informar e monitorar.", "slide": 12}, {"termo": "Dunlosky et al. (2013)", "tecnica": "Método de estudo", "definicao": "Revisão sobre técnicas de aprendizagem com evidência, como revisão espaçada e prática de questões.", "slide": 15}, {"termo": "Bradicinina", "tecnica": "Mecanismo", "definicao": "Peptídeo vasoativo que se acumula quando a ECA é inibida, e causa a tosse dos inibidores da ECA.", "slide": 14}], "caso": {"titulo": "Caso: tosse após início de enalapril", "perfil": "Radical do nome, mecanismo da tosse e classe alternativa.", "etapas": [{"titulo": "Etapa 1: classe e mecanismo", "texto": "Mulher de 58 anos, hipertensa e diabética, em uso de enalapril 20 mg a cada 12 h. Refere tosse seca persistente há dois meses, sem febre; a radiografia de tórax é normal.", "perguntas": [{"pergunta": "Qual é a classe do fármaco, pelo radical do nome?", "alts": ["Inibidor da enzima conversora de angiotensina (ECA)", "Bloqueador do receptor AT1 da angiotensina", "Betabloqueador não seletivo", "Inibidor da HMG-CoA redutase", "Inibidor da bomba de prótons"], "erradas": ["Bloqueador AT1 tem radical -sartana, como losartana.", "Betabloqueadores têm radical -olol.", "Estatinas têm radical -statina.", "Inibidores da bomba de prótons têm radical -prazol."], "justificativa": "O radical -pril identifica os inibidores da ECA, como captopril, enalapril e ramipril (slide 9)."}]}, {"titulo": "Etapa 2: alternativa sem tosse", "texto": "A tosse é atribuída ao acúmulo de bradicinina. O médico quer manter o benefício renal e cardiovascular, sem a tosse.", "perguntas": [{"pergunta": "Qual classe alternativa mantém o benefício e não causa tosse, segundo a aula?", "alts": ["Bloqueador do receptor AT1, de radical -sartana", "Betabloqueador de radical -olol, sem efeito renal", "Inibidor da bomba de prótons, de radical -prazol", "Benzodiazepínico, de radical -azepam", "Inibidor do SGLT2, de radical -gliflozina"], "erradas": ["Betabloqueadores não são alternativa renal a IECA neste caso.", "Inibidor da bomba de prótons não trata a pressão arterial.", "Benzodiazepínicos não têm efeito renal ou anti-hipertensivo.", "Inibidores do SGLT2 não são a alternativa citada na aula."], "justificativa": "Bloqueadores AT1 (-sartana) atuam na mesma via sem acumular bradicinina, e a aula cita a tosse como efeito da classe anterior (slide 14)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um produto natural é vendido como 'remédio para dormir', sem qualquer ensaio clínico. Pela terminologia de aula, como ele deve ser classificado?", "alternativas": ["Medicamento, porque é registrado e tem bula com indicação e posologia", "Fármaco, porque contém uma molécula com efeito sobre o sistema nervoso", "Remédio, sem comprovação científica de eficácia nem de segurança", "Placebo, porque não tem princípio ativo comprovado por estudo controlado", "Droga, porque o uso está fora da dose e do propósito originalmente projetados"], "gabarito": "C", "justificativa": "Remédio é qualquer coisa que faça bem sem comprovação científica. Medicamento exige ensaio clínico, registro e bula; fármaco é o princípio ativo (resumo: Introdução, conceitos fundamentais).", "tecnica": "Remédio × medicamento", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um cientista afirma que um fármaco de uso prolongado deixou de ser medicamento e passou a ser droga. Qual critério de aula sustenta essa classificação?", "alternativas": ["Ausência de princípio ativo, o que o transforma em placebo ao longo do tempo", "Mudança de nome comercial, que o desvincula da bula aprovada pelo órgão regulador", "Aumento do preço em relação ao medicamento de referência, que o torna genérico", "Uso fora do projetado, em que a toxicidade supera o benefício", "Substituição do princípio ativo por um excipiente, sem nenhuma alteração de efeito"], "gabarito": "D", "justificativa": "Droga é fármaco ou medicamento usado em dose ou uso fora do projetado, quando a toxicidade supera o benefício. A definição depende do uso, não só da molécula (resumo: Introdução, conceitos).", "tecnica": "Droga", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Em um ensaio clínico, o pesquisador não sabe quem recebeu o ativo e o participante também não. Qual é o nome desse desenho e o que ele evita?", "alternativas": ["Randomizado; evita apenas o viés de seleção, sem controlar a expectativa dos envolvidos", "Controlado sem placebo; evita apenas a diferença de dose entre os grupos do estudo", "Duplo-cego; evita viés de expectativa de participante e de pesquisador", "Aberto e prospectivo; evita o viés de perda de seguimento, sem controlar as expectativas", "Retrospectivo e caso-controle; evita o viés de memória, sem considerar a alocação dos grupos"], "gabarito": "C", "justificativa": "Duplo-cego: nem participante nem pesquisador sabem quem recebeu o ativo. Isso evita que expectativas influenciem o resultado (resumo: Introdução, atenção para a prova).", "tecnica": "Duplo-cego", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Por que a randomização é necessária em um ensaio clínico, mesmo quando os grupos são grandes?", "alternativas": ["Para aumentar o número de participantes que recebem placebo, o que reduz o custo do estudo", "Para que diferenças observadas não decorram de diferenças entre grupos", "Para que o pesquisador escolha os participantes mais saudáveis, o que aumenta a eficácia observada", "Para que os grupos tenham o mesmo número de homens e mulheres, sem considerar a idade", "Para eliminar a necessidade de grupo controle, já que a alocação aleatória substitui a comparação"], "gabarito": "B", "justificativa": "Randomização aloca participantes aleatoriamente, com perfis equivalentes de sexo e idade, para que diferenças observadas não decorram de diferenças entre os grupos (resumo: Introdução, randomização).", "tecnica": "Randomização", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um estudo compara um fármaco novo com um tratamento padrão, sem placebo. Pela definição de aula, qual é o papel do grupo que recebe o tratamento padrão?", "alternativas": ["É o grupo de placebo, que recebe formulação sem princípio ativo", "É o grupo de randomização, que decide a alocação dos demais participantes", "É o grupo de farmacovigilância, que monitora reações após a aprovação", "É o grupo controle, de comparação com o fármaco novo", "É o grupo de pré-clínica, que testa o fármaco em modelo animal antes do ensaio"], "gabarito": "D", "justificativa": "Controle é o grupo de comparação. Pode receber placebo, tratamento padrão ou outra dose; aqui, o tratamento padrão (resumo: Introdução, atenção para a prova).", "tecnica": "Grupo controle", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Por que um placebo é usado em estudos, mesmo quando o fármaco já tem efeito conhecido?", "alternativas": ["Para separar o efeito farmacológico do efeito psicológico", "Para testar a dose máxima tolerada, já que o placebo contém a dose máxima do fármaco em estudo", "Para avaliar a biodisponibilidade oral, porque o placebo é absorvido igualmente em todas as vias", "Para medir a meia-vida do fármaco, comparando a concentração plasmática com a do placebo ao longo do tempo", "Para substituir o grupo controle, que é dispensável quando há um placebo idêntico ao medicamento"], "gabarito": "A", "justificativa": "Placebo é formulação idêntica sem princípio ativo. Serve para separar o efeito farmacológico do efeito psicológico (resumo: Introdução, conceitos fundamentais).", "tecnica": "Placebo", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um medicamento de referência foi registrado com eficácia comprovada. Qual exigência define um genérico em relação a ele?", "alternativas": ["Eficácia superior ao referência, comprovada em ensaio de fase IV com mais de dez mil pacientes", "Ausência de princípio ativo, substituído por excipiente que tenha a mesma cor e forma do referência", "Bioequivalência, com parâmetros dentro de 80 a 125% do medicamento de referência", "Preço inferior de pelo menos metade do valor do referência, sem nenhuma comprovação de equivalência", "Marca própria com nova indicação terapêutica, aprovada sem ensaio clínico de bioequivalência"], "gabarito": "C", "justificativa": "O genérico é identificado pelo princípio ativo e precisa comprovar bioequivalência, com parâmetros dentro de 80 a 125% do referência (resumo: Desenvolvimento de fármacos, referência × genérico × similar).", "tecnica": "Genérico e bioequivalência", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente recebe fármaco com boa eficácia em ensaio controlado, mas tem resultado ruim na prática. Qual conceito de aula explica essa diferença?", "alternativas": ["Efetividade, o desempenho em condições reais de uso, afetado por adesão, interações e custo", "Biodisponibilidade, a fração da dose que chega inalterada à circulação sistêmica em condições controladas", "Meia-vida, o tempo para a concentração cair 50%, que varia conforme o peso corporal do paciente", "Clearance, o volume de plasma depurado por unidade de tempo, que é constante em todos os pacientes", "Ordem zero, a cinética saturável que faz o fármaco se acumular quando a dose aumenta pouco"], "gabarito": "A", "justificativa": "Eficácia é o desempenho em condições controladas; efetividade é o desempenho em condições reais, afetado por adesão, interações e custo (resumo: Desenvolvimento de fármacos, eficácia × efetividade).", "tecnica": "Eficácia × efetividade", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um professor pede que os alunos relacionem cada fase de ensaio clínico ao objetivo principal. Qual associação está correta?", "alternativas": ["Fase I: eficácia em milhares de pacientes; fase II: vigilância de reações raras após o registro", "Fase I: segurança e farmacocinética; fase II: eficácia inicial", "Fase I: randomização com placebo; fase II: testes em modelos animais de doença crônica", "Fase I: registro e bula; fase II: determinação da meia-vida em voluntários sadios", "Fase I: bioequivalência com genérico; fase II: comparação com a dose padrão em crianças"], "gabarito": "B", "justificativa": "Fase I (20 a 100 voluntários sadios) avalia segurança e farmacocinética. Fase II (100 a 300 pacientes) dá a primeira evidência de eficácia e de relação dose-resposta (resumo: Desenvolvimento de fármacos).", "tecnica": "Fases de ensaio", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Por que a fase II é a etapa em que a maioria dos candidatos a fármaco fracassa?", "alternativas": ["Porque é a fase em que o registro é negado pelo órgão regulador, por falta de bula completa", "Porque é a fase de farmacovigilância, em que reações raras surgem após a aprovação do medicamento", "Porque é a fase em que se produzem os genéricos, que têm menor biodisponibilidade que o referência", "Porque a eficácia é testada em pacientes pela primeira vez", "Porque é a fase de pré-clínica, em que os modelos animais não reproduzem a doença humana"], "gabarito": "D", "justificativa": "Na fase II o candidato é testado em pacientes pela primeira vez, com prova de conceito e dose-resposta. É onde a maioria dos candidatos cai (resumo: Desenvolvimento de fármacos).", "tecnica": "Fase II", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um fármaco foi retirado do mercado anos após a aprovação por risco cardiovascular em uso prolongado. Qual fase de desenvolvimento detectou esse risco?", "alternativas": ["Fase I, de segurança em voluntários sadios, com doses únicas e crescentes", "Fase II, de prova de conceito, com relação dose-resposta em pacientes", "Pré-clínica, de toxicologia em duas espécies animais e modelagem in silico", "Fase III, de comparação randomizada e duplo-cego, com população ampla e controle", "Fase IV, de farmacovigilância em uso real, com reações raras ou tardias"], "gabarito": "E", "justificativa": "A fase IV, em uso real, detecta reações raras ou tardias e efeitos de uso prolongado. Exemplo clássico: retirada do rofecoxibe em 2004 por risco cardiovascular (resumo: Desenvolvimento de fármacos, fase IV).", "tecnica": "Fase IV", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Por que o custo para lançar um fármaco é tão elevado, mesmo com a aprovação de apenas um entre milhares de compostos?", "alternativas": ["Porque a fase I é realizada apenas em hospitais de alta complexidade, com equipe e equipamentos de alto custo", "Porque o custo inclui os fracassos de centenas de compostos, o que explica patente e preço", "Porque a bioequivalência exige que o genérico seja produzido com o mesmo excipiente do referência", "Porque o placebo é mais caro que o princípio ativo, e cada participante recebe dose dupla do estudo", "Porque a fase IV exige registro em todos os países do mundo, com taxas de inscrição muito elevadas"], "gabarito": "B", "justificativa": "O funil tem 5.000 a 10.000 compostos, cerca de 250 em pré-clínica, 5 em ensaios clínicos e 1 aprovado. O custo estimado de US$ 1 a 2,6 bilhões inclui os fracassos (resumo: Desenvolvimento de fármacos, funil).", "tecnica": "Funil e custo", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um estudante afirma que medicamento, fármaco e droga são sinônimos. Qual correção é a mais precisa?", "alternativas": ["Fármaco é o princípio ativo; medicamento é formulado e registrado; droga depende do uso", "Fármaco e medicamento são sinônimos; droga é apenas o nome técnico do placebo nos ensaios clínicos", "Medicamento é o princípio ativo; fármaco é o comprimido registrado; droga é o excipiente da formulação", "Droga é sempre ilegal; medicamento é sempre seguro; fármaco é o nome dado ao genérico registrado", "Todos são termos de bula, sem diferença conceitual, e a distinção existe apenas nos livros de farmacologia"], "gabarito": "A", "justificativa": "Fármaco é o princípio ativo. Medicamento é o fármaco formulado, testado, registrado e com bula. Droga é fármaco ou medicamento em uso fora do projetado (resumo: Introdução, vocabulário).", "tecnica": "Vocabulário", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que a fase III é a base do registro de um fármaco, e não a fase I?", "alternativas": ["Porque é a única fase em que se mede a meia-vida, o que define a dose de manutenção do fármaco", "Porque é a fase em que se testa a dose máxima tolerada em voluntários sadios, com doses únicas", "Porque é a fase de farmacovigilância, que registra reações raras após a aprovação do fármaco", "Porque é a fase de pré-clínica, em que o fármaco é testado em duas espécies de animais de laboratório", "Porque é randomizada e duplo-cega, em população ampla"], "gabarito": "E", "justificativa": "A fase III tem 300 a 3.000 ou mais pacientes, randomizados e duplo-cegos, e confirma eficácia e segurança. A fase I, com voluntários sadios, avalia segurança e farmacocinética (resumo: Desenvolvimento de fármacos, fase III).", "tecnica": "Fase III", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um professor diz que 'o estudante precisa decorar a lista de fármacos para a prova'. Qual é a orientação mais coerente com a aula?", "alternativas": ["Decorar nomes comerciais e fabricantes, que são cobrados em enunciados descritivos de farmacologia", "Decorar doses de todos os fármacos, incluindo posologia veterinária, que é o foco da prova", "Decorar a sequência de fases do ensaio clínico, sem considerar os conceitos de receptor e de ação", "Decorar apenas os fármacos de uso veterinário, que aparecem em todas as questões de farmacologia", "Priorizar receptores e a ação do fármaco quando estimulado ou bloqueado"], "gabarito": "E", "justificativa": "O professor disse que não cobra decoreba de fármacos. Cobra o receptor, a ação quando estimulado ou bloqueado e os conceitos de agonista, antagonista, seletivo e não seletivo (resumo: Introdução, ênfase do professor).", "tecnica": "Estudo dirigido", "slide": null}], "id": "farma-gilmar-01", "titulo": "Aula 1", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-02"] = {"subtitulo": "Farmacocinética: ADME, biodisponibilidade, metabolismo e doses", "pdf": "pdf/gilmar/aula-02.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 2 · Farmacocinética (Prof. Dr. Gilmar S. Erzinger)", "Katzung, Farmacologia Básica e Clínica; Goodman & Gilman; Rowland e Tozer; Lei 9.787/1999 (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Vias de administração e biodisponibilidade (slide 7)", "colunas": ["Via", "Biodisponibilidade", "Característica principal"], "linhas": [["Intravenosa", "100% (referência)", "Início imediato; controle preciso da dose"], ["Intramuscular", "75 a ≤100%", "Rápida em solução aquosa; veículo oleoso forma depósito"], ["Subcutânea", "75 a ≤100%", "Absorção mais lenta que a IM (ex.: insulina, heparina)"], ["Oral", "5 a <100%", "Mais conveniente; sujeita à primeira passagem"], ["Retal", "30 a <100%", "Primeira passagem parcial; útil com vômitos"], ["Transdérmica", "80 a ≤100%", "Absorção lenta e sustentada (ex.: adesivos)"]]}, "resumo": [{"titulo": "1. Visão geral: o ADME", "pontos": [{"t": "Liberação, absorção, distribuição, metabolismo e excreção", "sub": ["A farmacocinética descreve o caminho do fármaco do momento em que é administrado até a eliminação. Cada etapa pode limitar o efeito (slide 3).", "Liberação: a forma farmacêutica se desintegra e dissolve. Absorção: o fármaco passa do local de administração para a circulação sistêmica. Distribuição: passa do sangue para os tecidos e se liga a proteínas. Metabolismo: biotransformação, sobretudo hepática, em metabólitos mais polares. Excreção: eliminação por rim, bile e pulmões (slide 3).", "Referências citadas: Goodman & Gilman (capítulos de farmacocinética e metabolismo), Katzung (caps. 3 e 4) e Rowland & Tozer (slide 22)."]}]}, {"titulo": "2. Absorção: como o fármaco atravessa a membrana", "pontos": [{"t": "Mecanismos", "sub": ["Difusão passiva é o mecanismo principal, a favor do gradiente, e depende da lipossolubilidade. Difusão facilitada usa carreadores, sem gasto de energia. Transporte ativo inclui transportadores SLC e o efluxo por glicoproteína-P. Endocitose serve para macromoléculas (slide 4)."]}, {"t": "Ionização e pH", "sub": ["Só a forma não ionizada atravessa bem as membranas. Ácidos fracos, como o AAS, ficam mais não ionizados em pH ácido. Bases fracas ficam mais não ionizadas em pH alcalino (slide 4).", "A relação entre pH, pKa e as formas ionizada e não ionizada é descrita pela equação de Henderson-Hasselbalch (epônimo: Henderson-Hasselbalch). Ela explica o aprisionamento iônico, que concentra fármacos em compartimentos de pH diferente (slide 4)."]}]}, {"titulo": "3. A curva concentração × tempo", "pontos": [{"t": "Parâmetros que se leem na curva", "sub": ["Cmáx é o pico de concentração. Tmáx é o tempo até o pico e indica a velocidade de absorção. AUC é a área sob a curva e representa a exposição total (slide 5).", "Janela terapêutica é o intervalo entre a concentração mínima efetiva e a concentração mínima tóxica. A duração do efeito é o tempo em que a concentração fica acima da mínima efetiva (slide 5)."]}]}, {"titulo": "4. Biodisponibilidade, vias e primeira passagem", "pontos": [{"t": "Biodisponibilidade (F)", "sub": ["F é a fração da dose que chega inalterada à circulação sistêmica. Calcula-se como F = AUC oral ÷ AUC IV, corrigido pela dose. Por definição, a via IV tem 100% (slide 8).", "Biodisponibilidade e bioequivalência são conceitos diferentes, embora relacionados. A biodisponibilidade mede velocidade e quantidade de absorção de uma versão do fármaco (slide 6)."]}, {"t": "Faixas por via de administração", "sub": ["Intravenosa: 100%, referência. Intramuscular e subcutânea: 75 a 100%. Oral: 5 a menos de 100%. Retal: 30 a menos de 100%. Transdérmica: 80 a 100% (slide 7; adaptado de Katzung).", "Via oral tem conveniência, mas sofre efeito de primeira passagem. Transdérmica dá absorção lenta e sustentada, como nos adesivos (slide 7)."]}, {"t": "Primeira passagem", "sub": ["É o metabolismo intestinal e hepático antes de o fármaco chegar à circulação sistêmica (slide 8).", "Exemplos de alta extração: nitroglicerina (por isso usa-se a via sublingual), propranolol, morfina e lidocaína. Vias que evitam a primeira passagem: IV, sublingual, transdérmica e inalatória. A retal a evita parcialmente (slide 8).", "Em cirrose ou em shunts portossistêmicos, a primeira passagem cai e a exposição aumenta. Por isso a dose oral de um fármaco de alta extração costuma ser muito maior que a dose IV (slide 8)."]}]}, {"titulo": "5. Bioequivalência, genéricos e similares", "pontos": [{"t": "Bioequivalência", "sub": ["Comprova que dois medicamentos com a mesma fórmula e quantidade de princípio ativo têm biodisponibilidade equivalente. Serve de base para a intercambiabilidade (slide 9).", "O critério é que os parâmetros de velocidade (Tmáx) e extensão (AUC) da cópia fiquem entre 80% e 125% do produto de referência. Os testes são geralmente feitos em voluntários sadios (slide 9). A Lei nº 9.787/1999 regulamenta genéricos (slide 8 e referências)."]}, {"t": "Referência, genérico e similar", "sub": ["Referência (marca): produto inovador, com eficácia, segurança e qualidade comprovadas à Anvisa no registro (slide 10).", "Genérico: cópia da referência, identificada pela DCB, com mesma concentração, forma, via, posologia e indicação. É legalmente intercambiável (slide 10).", "Similar: mesmo princípio ativo, concentração, forma e indicação, mas com marca própria. Hoje também precisa comprovar equivalência por testes (slide 10)."]}]}, {"titulo": "6. Distribuição", "pontos": [{"t": "Volume de distribuição (Vd)", "sub": ["Vd = Dose ÷ C0. É um volume aparente, não anatômico. Vd baixo indica fármaco retido no plasma, como a varfarina. Vd alto indica acúmulo tecidual, como a amiodarona e a digoxina (slide 11)."]}, {"t": "Ligação a proteínas", "sub": ["Albumina liga principalmente ácidos fracos. Alfa-1-glicoproteína ácida liga bases. Só a fração livre é ativa e eliminada (slide 11).", "Hipoalbuminemia aumenta a fração livre, como na fenitoína, e pode elevar o efeito. O deslocamento por competição pela albumina costuma ser transitório, porque a eliminação também aumenta (slide 11)."]}, {"t": "Barreiras e redistribuição", "sub": ["Barreira hematoencefálica tem junções firmes e glicoproteína-P. A inflamação meníngea aumenta a passagem. A placenta deixa passar fármacos lipossolúveis, o que é relevante na gestação (slide 11).", "Redistribuição: o efeito de tiopental e propofol termina pela saída do SNC para músculo e gordura, e não pela eliminação (slide 11)."]}]}, {"titulo": "7. Metabolismo: fases I e II e CYP450", "pontos": [{"t": "Objetivo e fases", "sub": ["O objetivo é tornar o fármaco mais polar e facilmente excretável. O principal órgão é o fígado (slide 12).", "Fase I (funcionalização): oxidação pelo CYP450, redução e hidrólise. Introduz ou expõe grupos polares. Pode ativar pró-fármacos ou gerar metabólitos tóxicos, como o NAPQI do paracetamol (slide 12).", "Fase II (conjugação): glicuronidação, sulfatação, acetilação, metilação e conjugação com glutationa. Gera compostos inativos e hidrossolúveis (slide 12)."]}, {"t": "CYP450 na prática", "sub": ["Seis enzimas do CYP450 processam cerca de 90% dos medicamentos. As mais importantes são CYP3A4 e CYP2D6 (slide 13). Os CYP mais relevantes citados são 3A4, 2D6, 2C9, 2C19 e 1A2 (slides 12 e 21).", "Acetiladores lentos têm maior toxicidade com isoniazida e hidralazina. Neonatos têm glicuronidação imatura, e isso causa a síndrome cinzenta com cloranfenicol (slide 12)."]}]}, {"titulo": "8. Indução e inibição enzimática", "pontos": [{"t": "Indutores e inibidores", "sub": ["Indutores: rifampicina, carbamazepina, fenitoína, fenobarbital, erva-de-são-joão e tabagismo (CYP1A2). Efeito: queda da concentração do fármaco-alvo e falha terapêutica (slide 14).", "Inibidores: claritromicina, cetoconazol e itraconazol, fluconazol, ritonavir, amiodarona, fluoxetina e paroxetina (2D6) e suco de toranja (3A4). Efeito: aumento da concentração e risco de toxicidade (slide 14)."]}, {"t": "Tempo de início e exemplos", "sub": ["Indução é lenta, de dias a semanas, porque depende da síntese de enzimas. Inibição é rápida, de horas a poucos dias (slide 14).", "Exemplos citados: rifampicina com contraceptivo oral, levando a gestação não planejada; sinvastatina com claritromicina, levando a miopatia e rabdomiólise (slide 14)."]}]}, {"titulo": "9. Excreção", "pontos": [{"t": "Vias de eliminação", "sub": ["Filtração glomerular: só a fração livre é filtrada. Depende da TFG e é a base do ajuste de dose na doença renal (slide 15).", "Secreção tubular: transporte ativo (OAT e OCT). A probenecida inibe a secreção de penicilinas e há competição com o metotrexato (slide 15).", "Reabsorção passiva: depende do pH urinário. Alcalinizar a urina acelera a eliminação de ácidos fracos, como salicilatos e fenobarbital (slide 15).", "Biliar e fecal: metabólitos conjugados na bile. A circulação êntero-hepática prolonga a ação, como nos estrogênios. Pulmonar: anestésicos inalatórios e etanol, base do etilômetro. Leite materno: bases fracas podem se concentrar nele (slide 15)."]}]}, {"titulo": "10. Parâmetros que orientam a dose", "pontos": [{"t": "CL, t½ e Vd", "sub": ["Clearance (CL) é o volume de plasma depurado por unidade de tempo. Define a dose de manutenção: CL × Css ÷ F, por intervalo (slide 16).", "Meia-vida (t½) é o tempo para a concentração cair 50%. Calcula-se como t½ = 0,693 × Vd ÷ CL. Define o intervalo entre doses e o tempo até o equilíbrio (slide 16).", "Volume de distribuição (Vd) define a dose de ataque: Vd × C alvo ÷ F (slide 16). A meia-vida muda quando Vd ou CL mudam."]}, {"t": "Doses repetidas", "sub": ["Após 1 t½ se atinge 50% da concentração de equilíbrio (Css). Após 2 t½, 75%; após 3 t½, 87,5%. Com 4 a 5 t½, 94 a 97%, o equilíbrio clínico. O mesmo vale para a eliminação após suspender (slide 17)."]}]}, {"titulo": "11. Cinética de primeira ordem e ordem zero", "pontos": [{"t": "Dois padrões de eliminação", "sub": ["Primeira ordem (linear): elimina-se uma fração constante por unidade de tempo. A meia-vida é constante, e a concentração é proporcional à dose. Vale para a maioria dos fármacos em doses terapêuticas (slide 18).", "Ordem zero (saturável): elimina-se uma quantidade constante por unidade de tempo. Com enzimas saturadas, um pequeno aumento de dose gera grande aumento de concentração. Exemplos: etanol, fenitoína e salicilatos em doses altas. Exige ajustes pequenos e monitoramento de nível sérico (slide 18)."]}]}, {"titulo": "12. Populações especiais", "pontos": [{"t": "Quem muda a farmacocinética", "sub": ["Idosos têm TFG reduzida, menos massa magra, mais gordura e menos albumina. A regra é estimar a função renal e comece baixo e vá devagar (slide 19).", "Neonatos e crianças têm imaturidade renal e hepática. A dose é calculada por peso ou superfície corporal (slide 19).", "Gestação aumenta o Vd, a TFG e a atividade de algumas CYP. A aula cita a lamotrigina como exemplo de reavaliação de dose (slide 19).", "Doença renal exige ajuste em fármacos de eliminação renal, como aminoglicosídeos, vancomicina, metformina e enoxaparina. Doença hepática reduz o metabolismo e a albumina, e não tem marcador simples; use Child-Pugh com cautela (slide 19)."]}]}, {"titulo": "13. Absorção, ionização e biodisponibilidade por via", "pontos": [{"t": "Difusão passiva e ionização", "sub": ["Mecanismo principal: difusão passiva, dependente de lipossolubilidade; só a forma não ionizada atravessa bem as membranas.", "Ácido fraco fica não ionizado em meio ácido (absorve melhor no estômago); base fraca fica não ionizada em meio alcalino.", "Esse princípio explica o aprisionamento iônico e justifica alcalinizar a urina para acelerar a eliminação de ácidos fracos."]}, {"t": "Biodisponibilidade (F) por via", "sub": ["Biodisponibilidade é a fração da dose que chega inalterada à circulação sistêmica; a via intravenosa tem F = 100%.", "Intravenosa: 100% (referência); início imediato e dose precisa, mas efeito adverso também imediato, sem tempo para intervir.", "Intramuscular e subcutânea: 75 a ≤100%. IM rápida em solução aquosa; veículo oleoso forma depósito. SC mais lenta que IM (insulina, heparina).", "Oral: 5 a <100%; conveniente, mas sujeita à absorção incompleta e à primeira passagem.", "Retal: 30 a <100%; evita parcialmente a primeira passagem (drenagem hemorroidária inferior); útil em vômitos e pediatria.", "Sublingual, transdérmica e inalatória: alta biodisponibilidade, pois evitam a primeira passagem."]}, {"t": "Primeira passagem", "sub": ["Metabolismo intestinal e hepático antes de o fármaco alcançar a circulação: a absorção intestinal drena para o sistema porta, e o fígado degrada parte do fármaco."]}]}, {"titulo": "14. Correlação clínica: via, cirrose e comprimidos", "pontos": [{"t": "Aplicação", "sub": ["Fármacos de alta extração hepática (nitroglicerina, propranolol, morfina, lidocaína) exigem dose oral muito maior que a intravenosa, ou outra via.", "Na cirrose ou em shunts portossistêmicos, a primeira passagem diminui e a exposição aumenta: reduzir a dose.", "Não se parte comprimido de liberação controlada: o revestimento dosa a liberação; quebrá-lo altera a biodisponibilidade."]}]}, {"titulo": "15. Distribuição: volume de distribuição e ligação proteica", "pontos": [{"t": "Vd", "sub": ["Vd = Dose ÷ C₀. É um volume aparente, não anatômico: relaciona a dose administrada à concentração plasmática resultante.", "Vd baixo: fármaco retido no plasma (varfarina). Vd alto: acúmulo tecidual (amiodarona, digoxina)."]}, {"t": "Ligação proteica e barreiras", "sub": ["Só a fração livre é ativa e eliminada. Albumina liga ácidos fracos; α1-glicoproteína ácida liga bases.", "Na hipoalbuminemia, a fração livre aumenta.", "Barreiras hematoencefálica e placentária são atravessadas por fármacos lipossolúveis: ponto decisivo na gestação."]}]}, {"titulo": "16. Metabolismo: fases I e II, CYP450 e interações", "pontos": [{"t": "Fases", "sub": ["Objetivo: tornar o fármaco mais polar e excretável; o órgão principal é o fígado.", "Fase I (funcionalização): oxidação (CYP450), redução, hidrólise; introduz ou expõe grupos polares. Pode ativar pró-fármaco ou gerar metabólito tóxico (NAPQI, do paracetamol).", "Fase II (conjugação): glicuronidação, sulfatação, acetilação, conjugação com glutationa; gera compostos em geral inativos e hidrossolúveis. Neonatos têm glicuronidação imatura."]}, {"t": "CYP450", "sub": ["É superfamília de enzimas. As mais relevantes: CYP3A4 (maior número de fármacos), 2D6, 2C9, 2C19 e 1A2."]}, {"t": "Indução × inibição", "sub": ["Indutores: rifampicina, carbamazepina, fenitoína, fenobarbital, erva-de-são-joão, tabagismo (1A2). Início lento (dias a semanas, exige síntese enzimática); efeito: ↓ concentração → falha terapêutica. Exemplo: rifampicina + contraceptivo oral → gestação não planejada.", "Inibidores: claritromicina, azólicos, ritonavir, amiodarona, fluoxetina e paroxetina (2D6), suco de toranja (3A4). Início rápido (horas a poucos dias, competição direta); efeito: ↑ concentração → toxicidade. Exemplo: sinvastatina + claritromicina → miopatia e rabdomiólise.", "Ao suspender: após indução, os níveis caem e há perda de efeito; após inibição, os níveis sobem gradualmente e há risco de toxicidade."]}, {"t": "Caso do slide: varfarina + fluconazol", "sub": ["Homem de 67 anos em varfarina com INR estável recebe fluconazol para candidíase esofágica; em cinco dias surgem equimoses e gengivorragia, com INR de 6,8.", "Mecanismo: fluconazol inibe o CYP2C9, que metaboliza a varfarina → acúmulo → anticoagulação excessiva.", "Por que em poucos dias? Inibição enzimática é competitiva e imediata; a indução exige síntese de enzimas. É o exemplo canônico de interação farmacocinética."]}]}, {"titulo": "17. Parâmetros que orientam a dose e cinética", "pontos": [{"t": "Parâmetros", "sub": ["Clearance (CL): volume de plasma depurado por unidade de tempo; define a dose de manutenção.", "Vd: relaciona dose e concentração; define a dose de ataque.", "Meia-vida: t½ = 0,693 × Vd ÷ CL. Define o intervalo entre doses. É parâmetro dependente: muda se Vd ou CL mudarem."]}, {"t": "Acúmulo em doses repetidas", "sub": ["1 meia-vida: 50% da concentração de equilíbrio; 2: 75%; 3: 87,5%; 4 a 5: 94–97%, o equilíbrio clínico. O mesmo raciocínio vale para a eliminação após suspender.", "Fármacos de meia-vida longa justificam dose de ataque."]}, {"t": "Primeira ordem × ordem zero", "sub": ["Primeira ordem (linear): fração constante por unidade de tempo; meia-vida constante; concentração proporcional à dose; risco previsível.", "Ordem zero (saturável): quantidade constante por unidade de tempo; enzimas saturadas; pequeno aumento de dose → grande aumento de concentração. Exemplos: etanol, fenitoína, salicilatos em dose alta."]}]}, {"titulo": "18. Para a prova", "pontos": [{"t": "Pontos-chave da aula", "sub": ["ADME define quanto fármaco chega ao alvo e por quanto tempo. A biodisponibilidade oral cai com absorção incompleta e primeira passagem (slide 21).", "Só a fração livre age e é eliminada. Indutores reduzem e inibidores aumentam a concentração. Vd define a dose de ataque e CL define a manutenção (slide 21).", "O equilíbrio ocorre após 4 a 5 meias-vidas. A ordem zero exige cautela (slide 21)."]}]}], "glossario": [{"termo": "Biodisponibilidade (F)", "tecnica": "Farmacocinética", "definicao": "Fração da dose que chega inalterada à circulação sistêmica.", "slide": 8}, {"termo": "Primeira passagem", "tecnica": "Metabolismo", "definicao": "Metabolismo intestinal e hepático antes de a droga atingir a circulação sistêmica.", "slide": 8}, {"termo": "Clearance (CL)", "tecnica": "Parâmetro", "definicao": "Volume de plasma depurado por unidade de tempo; define a dose de manutenção.", "slide": 16}, {"termo": "Volume de distribuição (Vd)", "tecnica": "Parâmetro", "definicao": "Volume aparente que relaciona dose e concentração; define a dose de ataque.", "slide": 11}, {"termo": "Indutor enzimático", "tecnica": "Interação", "definicao": "Fármaco que acelera o metabolismo, como rifampicina e carbamazepina, reduzindo níveis.", "slide": 14}, {"termo": "Ordem zero", "tecnica": "Cinética", "definicao": "Eliminação de quantidade constante por tempo, com enzimas saturadas, como etanol e fenitoína em doses altas.", "slide": 18}, {"termo": "Equação de Henderson-Hasselbalch (epônimo: Henderson-Hasselbalch)", "tecnica": "Absorção e pH", "definicao": "Relaciona pKa, pH e as formas ionizada e não ionizada de ácidos e bases fracas; explica a absorção conforme o pH.", "slide": 4}, {"termo": "Bioequivalência", "tecnica": "Farmacocinética", "definicao": "Comprova que duas versões do mesmo fármaco têm biodisponibilidade equivalente. Base dos genéricos.", "slide": 6}, {"termo": "Lei nº 9.787/1999", "tecnica": "Legislação", "definicao": "Lei que regulamenta os medicamentos genéricos no Brasil.", "slide": 8}, {"termo": "Nitroglicerina (via sublingual)", "tecnica": "Exemplo", "definicao": "Alta extração hepática. Usada por via sublingual para evitar a primeira passagem.", "slide": 8}, {"termo": "Meia-vida (t½)", "tecnica": "Parâmetro", "definicao": "Tempo para a concentração cair 50%. t½ = 0,693 × Vd ÷ CL.", "slide": 16}, {"termo": "Cmáx, Tmáx e AUC", "tecnica": "Curva", "definicao": "Cmáx é o pico; Tmáx é o tempo até o pico e indica a velocidade de absorção; AUC é a exposição total.", "slide": 5}, {"termo": "Janela terapêutica", "tecnica": "Curva", "definicao": "Intervalo entre a concentração mínima efetiva e a concentração mínima tóxica.", "slide": 5}, {"termo": "Ionização e pH", "tecnica": "Absorção", "definicao": "Só a forma não ionizada atravessa bem a membrana. Ácidos fracos absorvem em pH ácido; bases fracas, em pH alcalino.", "slide": 4}, {"termo": "Glicoproteína-P", "tecnica": "Transporte", "definicao": "Transportador de efluxo que expulsa fármacos das células. Presente na barreira hematoencefálica.", "slide": 4}, {"termo": "Transportadores SLC", "tecnica": "Transporte", "definicao": "Família de transportadores ativos que levam fármacos para dentro das células.", "slide": 4}, {"termo": "Difusão passiva", "tecnica": "Absorção", "definicao": "Mecanismo principal de absorção, a favor do gradiente, dependente da lipossolubilidade.", "slide": 4}, {"termo": "Albumina", "tecnica": "Distribuição", "definicao": "Proteína plasmática que liga principalmente os ácidos fracos. Só a fração livre é ativa.", "slide": 11}, {"termo": "Alfa-1-glicoproteína ácida", "tecnica": "Distribuição", "definicao": "Proteína plasmática que liga principalmente as bases fracas.", "slide": 11}, {"termo": "Redistribuição (tiopental e propofol)", "tecnica": "Distribuição", "definicao": "Saída do fármaco do SNC para músculo e gordura, que termina o efeito sem eliminação.", "slide": 11}, {"termo": "Barreira hematoencefálica", "tecnica": "Distribuição", "definicao": "Barreira de junções firmes e glicoproteína-P. A inflamação meníngea aumenta a passagem.", "slide": 11}, {"termo": "Placenta e lipossolubilidade", "tecnica": "Distribuição", "definicao": "Fármacos lipossolúveis atravessam a placenta, o que é relevante na gestação.", "slide": 11}, {"termo": "Fase I (funcionalização)", "tecnica": "Metabolismo", "definicao": "Oxidação, redução e hidrólise, sobretudo pelo CYP450. Pode gerar metabólitos tóxicos.", "slide": 12}, {"termo": "Fase II (conjugação)", "tecnica": "Metabolismo", "definicao": "Glicuronidação, sulfatação, acetilação e conjugação com glutationa. Gera compostos inativos e hidrossolúveis.", "slide": 12}, {"termo": "CYP450 (citocromo P450)", "tecnica": "Metabolismo", "definicao": "Superfamília de enzimas hepáticas. Seis enzimas processam cerca de 90% dos medicamentos.", "slide": 13}, {"termo": "CYP3A4", "tecnica": "Enzima", "definicao": "Maior número de fármacos metabolizados. Inibida por suco de toranja e claritromicina.", "slide": 13}, {"termo": "CYP2D6", "tecnica": "Enzima", "definicao": "Metaboliza muitos antidepressivos e betabloqueadores. Inibida por fluoxetina e paroxetina.", "slide": 13}, {"termo": "CYP2C9, CYP2C19 e CYP1A2", "tecnica": "Enzima", "definicao": "Enzimas citadas como relevantes para interações. CYP1A2 é induzido pelo tabagismo.", "slide": 13}, {"termo": "NAPQI", "tecnica": "Metabólito", "definicao": "Metabólito tóxico do paracetamol, gerado pelo CYP.", "slide": 12}, {"termo": "Acetiladores lentos", "tecnica": "Metabolismo", "definicao": "Maior toxicidade de isoniazida e hidralazina.", "slide": 12}, {"termo": "Síndrome cinzenta", "tecnica": "Toxicidade neonatal", "definicao": "Toxicidade por cloranfenicol em neonatos, pela glicuronidação imatura.", "slide": 12}, {"termo": "Indutores enzimáticos", "tecnica": "Interação", "definicao": "Rifampicina, carbamazepina, fenitoína, fenobarbital e erva-de-são-joão. Reduzem a concentração do fármaco-alvo.", "slide": 14}, {"termo": "Inibidores enzimáticos", "tecnica": "Interação", "definicao": "Claritromicina, cetoconazol, itraconazol, fluconazol, ritonavir, amiodarona, fluoxetina, paroxetina e suco de toranja. Aumentam a concentração.", "slide": 14}, {"termo": "Probenecida", "tecnica": "Excreção", "definicao": "Inibe a secreção tubular de penicilinas e aumenta o nível sérico delas.", "slide": 15}, {"termo": "OAT e OCT", "tecnica": "Excreção", "definicao": "Transportadores de secreção tubular de ácidos e bases orgânicos no rim.", "slide": 15}, {"termo": "Filtração glomerular (TFG)", "tecnica": "Excreção", "definicao": "Taxa que filtra fármacos livres. Base do ajuste de dose na doença renal.", "slide": 15}, {"termo": "Circulação êntero-hepática", "tecnica": "Excreção", "definicao": "Metabólitos conjugados são excretados na bile e reabsorvidos, prolongando a ação. Ex.: estrogênios.", "slide": 15}, {"termo": "Dose de ataque e dose de manutenção", "tecnica": "Parâmetros de dose", "definicao": "Ataque = Vd × C alvo ÷ F. Manutenção = CL × Css ÷ F, por intervalo.", "slide": 16}, {"termo": "Cinética de ordem zero", "tecnica": "Cinética", "definicao": "Eliminação de quantidade constante por tempo, com enzimas saturadas. Ex.: fenitoína, etanol, salicilatos em doses altas.", "slide": 18}, {"termo": "Cinética de primeira ordem", "tecnica": "Cinética", "definicao": "Eliminação de fração constante por tempo. A meia-vida é constante.", "slide": 18}, {"termo": "Equilíbrio em doses repetidas", "tecnica": "Cinética", "definicao": "Após 4 a 5 meias-vidas, o equilíbrio clínico é atingido (94 a 97%).", "slide": 17}, {"termo": "Child-Pugh (epônimo: Child-Pugh)", "tecnica": "Insuficiência hepática", "definicao": "Escala de gravidade da doença hepática, citada como referência para dose em hepatopatas.", "slide": 19}], "caso": {"titulo": "Caso: sangramento com varfarina e fluconazol", "perfil": "Interação por inibição do metabolismo e risco de sangramento.", "etapas": [{"titulo": "Etapa 1: mecanismo", "texto": "Homem de 67 anos com fibrilação atrial, em varfarina com INR estável em 2,5. Recebe fluconazol por candidíase esofágica. Após cinco dias, apresenta equimoses e gengivorragia, com INR de 6,8.", "perguntas": [{"pergunta": "Qual é o mecanismo mais provável da interação?", "alts": ["Inibição enzimática pelo fluconazol, que eleva a concentração da varfarina", "Indução enzimática pelo fluconazol, que reduz a concentração da varfarina", "Competição pela albumina, que reduz o Vd da varfarina", "Alcalinização urinária, que acelera a excreção renal da varfarina", "Redução da filtração glomerular, que retém a varfarina no plasma"], "erradas": ["Fluconazol é inibidor, e não indutor, por essa via.", "Competição pela albumina tem efeito transitório, e não explica o quadro.", "Alcalinização urinária acelera a eliminação de ácidos fracos, e não o efeito descrito.", "A filtração reduzida não é o mecanismo citado para essa interação."], "justificativa": "Inibidores como fluconazol reduzem o metabolismo pelo CYP e elevam os níveis do fármaco (slide 14). A varfarina é metabolizada principalmente pelo CYP2C9 (slide 12)."}]}, {"titulo": "Etapa 2: conduta", "texto": "A equipe avalia o risco de sangramento. A aula destaca que o efeito de uma interação pode aparecer em dias, conforme a meia-vida e a mudança de níveis.", "perguntas": [{"pergunta": "Qual é a conduta mais adequada diante de INR de 6,8 com sangramento, segundo a lógica da aula?", "alts": ["Suspender a varfarina e avaliar o risco de sangramento com monitoramento", "Manter a dose e aumentar o fluconazol para corrigir o INR", "Dobrar a dose de varfarina para compensar a interação", "Trocar o fluconazol por rifampicina, que é indutora", "Ignorar o INR e reavaliar apenas após duas semanas"], "erradas": ["Manter a dose com fluconazol agrava a interação.", "Aumentar o fluconazol eleva ainda mais a concentração da varfarina.", "Dobrar a dose aumenta o risco de sangramento.", "Adiar a reavaliação expõe o paciente a sangramento grave."], "justificativa": "Com a interação, os níveis sobem gradualmente após o início e caem ao suspender; a conduta é suspender e monitorar, pois o risco é de toxicidade (slide 14)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um ácido fraco é administrado por via oral. Em que região do trato digestivo sua absorção por difusão passiva tende a ser maior, e por quê?", "alternativas": ["Intestino grosso, porque o meio alcalino converte o ácido fraco em forma não ionizada e lipossolúvel", "Estômago, porque o meio ácido ioniza o ácido fraco e aumenta sua passagem pela membrana celular", "Reto, porque o meio neutro ionizado do reto aumenta a difusão passiva de qualquer ácido orgânico", "Estômago, porque o meio ácido mantém o ácido fraco não ionizado e lipossolúvel", "Intestino delgado, porque o meio básico protonará o ácido e facilitará a sua passagem pelo epitélio"], "gabarito": "D", "justificativa": "Ácido fraco fica não ionizado em meio ácido e atravessa melhor a membrana. Só a forma não ionizada é lipossolúvel e difunde passivamente (resumo: Farmacocinética, absorção e ionização).", "tecnica": "Absorção e pH", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Para acelerar a eliminação de um ácido fraco em intoxicação, qual medida é coerente com o princípio de ionização?", "alternativas": ["Alcalinizar a urina, para manter o ácido ionizado e preso na urina", "Acidificar a urina, para manter o ácido não ionizado e reabsorvível no túbulo", "Administrar o fármaco por via retal, para que ele seja absorvido pelo sistema porta", "Aumentar a ligação do fármaco à albumina, para que ele seja filtrado no glomérulo", "Administrar por via sublingual, para evitar a primeira passagem hepática do fármaco"], "gabarito": "A", "justificativa": "Alcalinizar a urina mantém o ácido ionizado, que não atravessa a membrana tubular e é eliminado. Esse é o princípio do aprisionamento iônico (resumo: Farmacocinética, absorção).", "tecnica": "Aprisionamento iônico", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um fármaco tem biodisponibilidade oral de 40%. Qual é a interpretação correta desse valor e o que explica a diferença em relação à via intravenosa?", "alternativas": ["60% da dose é ligada à albumina, que impede a absorção no intestino delgado de qualquer forma", "40% da dose é metabolizada no rim antes da absorção, por ação direta da enzima CYP3A4", "40% da dose é eliminada pelo pulmão, que filtra o fármaco antes de chegar à circulação sistêmica", "40% da dose atravessa a barreira hematoencefálica, por ser lipossolúvel, e não chega ao sangue", "60% da dose oral não chega à circulação sistêmica, por absorção incompleta e primeira passagem"], "gabarito": "E", "justificativa": "Biodisponibilidade é a fração que chega inalterada à circulação. Por via oral há absorção incompleta e primeira passagem hepática. A via intravenosa tem F = 100% (resumo: Farmacocinética, biodisponibilidade).", "tecnica": "Biodisponibilidade", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Por que a nitroglicerina, o propranolol e a morfina exigem dose oral muito maior que a intravenosa?", "alternativas": ["São ácidos fracos que se ionizam no estômago, o que impede a absorção intestinal em qualquer dose", "São proteínas, que são digeridas no intestino e não chegam ao sangue em nenhuma forma ativa", "Têm alta extração hepática, e a primeira passagem reduz a fração que chega à circulação", "São fármacos que se ligam à hemoglobina e são sequestrados no baço antes de atingir os tecidos", "São pró-fármacos que só são ativados pela microbiota intestinal, o que reduz a dose efetiva oral"], "gabarito": "C", "justificativa": "Fármacos de alta extração hepática sofrem primeira passagem intensa. Por isso a dose oral precisa ser bem maior que a intravenosa, ou usa-se outra via (resumo: Farmacocinética, primeira passagem).", "tecnica": "Primeira passagem", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um comprimido de liberação controlada é partido ao meio para facilitar a deglutição. Qual é a consequência farmacocinética e por que isso é um erro?", "alternativas": ["Não há consequência, porque o revestimento é inerte e serve apenas para proteger o comprimido da umidade", "Altera a liberação e a biodisponibilidade, porque o revestimento é que dosa a liberação do fármaco", "Aumenta a meia-vida do fármaco, porque a metade do comprimido é absorvida mais lentamente pelo intestino", "Reduz o volume de distribuição, porque o fármaco se concentra no plasma em vez de nos tecidos", "Aumenta a ligação às proteínas plasmáticas, o que torna o fármaco mais ativo e mais tóxico ao paciente"], "gabarito": "B", "justificativa": "O revestimento de liberação controlada dosa a liberação do fármaco. Quebrá-lo altera a biodisponibilidade e pode causar toxicidade ou perda de efeito (resumo: Farmacocinética, correlação clínica).", "tecnica": "Formas de liberação", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um fármaco tem volume de distribuição baixo, e outro tem volume alto. Qual é a interpretação correta, segundo o conceito de Vd?", "alternativas": ["Vd baixo indica fármaco eliminado pelo fígado; Vd alto indica eliminação pelo rim e pelo intestino", "Vd baixo indica fármaco lipossolúvel; Vd alto indica fármaco ligado à albumina plasmática", "Vd baixo indica meia-vida curta; Vd alto indica meia-vida longa, sem relação com o tecido", "Vd baixo indica fármaco retido no plasma; Vd alto indica acúmulo tecidual", "Vd é um volume anatômico real, medido na urina, e não tem relação com a concentração plasmática"], "gabarito": "D", "justificativa": "Vd = Dose ÷ C₀ é volume aparente. Vd baixo indica fármaco retido no plasma (varfarina); Vd alto indica acúmulo tecidual (amiodarona, digoxina) (resumo: Farmacocinética, distribuição).", "tecnica": "Volume de distribuição", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Por que a hipoalbuminemia aumenta o efeito de um fármaco que se liga fortemente à albumina?", "alternativas": ["Aumenta a ligação do fármaco à α1-glicoproteína ácida, o que impede a eliminação pelo fígado", "Aumenta a fração livre, que é a única ativa e eliminada, elevando a concentração efetiva", "Reduz o volume de distribuição, porque o fármaco fica preso no plasma e não se distribui aos tecidos", "Aumenta a meia-vida, porque a albumina impede a ação das enzimas hepáticas sobre o fármaco", "Reduz a absorção oral, porque a albumina é necessária para o transporte do fármaco pela mucosa"], "gabarito": "B", "justificativa": "Só a fração livre é ativa e eliminada. Na hipoalbuminemia a fração livre aumenta, e o efeito pode ficar maior que o esperado (resumo: Farmacocinética, ligação proteica).", "tecnica": "Ligação proteica", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Por que um fármaco lipossolúvel atravessa a barreira placentária e a barreira hematoencefálica, enquanto um fármaco muito ionizado não atravessa?", "alternativas": ["Porque a placenta e o cérebro têm transportadores específicos para ácidos fortes, que bloqueiam bases fracas", "Porque a ionização aumenta a ligação à albumina, e a albumina é o principal carreador pelas barreiras", "Porque a lipossolubilidade reduz o volume de distribuição, e o fármaco fica confinado ao sangue materno", "Porque a lipossolubilidade permite difusão passiva pelas membranas, e a ionização impede essa passagem", "Porque a barreira placentária só é atravessada por fármacos com peso molecular acima de 1.000 Da"], "gabarito": "D", "justificativa": "Só a forma não ionizada e lipossolúvel atravessa bem as membranas. Por isso fármacos lipossolúveis atravessam a placenta e a barreira hematoencefálica, o que é decisivo na gestação (resumo: Farmacocinética, distribuição).", "tecnica": "Barreiras e lipossolubilidade", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um fármaco é metabolizado por CYP2C9. Qual inibidor de CYP2C9 pode elevar o efeito desse fármaco e causar sangramento, como no caso da varfarina?", "alternativas": ["Rifampicina, que induz o CYP2C9 e reduz o efeito da varfarina de forma lenta, em semanas", "Carbamazepina, que induz o CYP3A4 e aumenta a depuração da varfarina no fígado", "Fluconazol, que inibe o CYP2C9 e eleva o INR da varfarina de forma rápida", "Suco de toranja, que induz o CYP2C9 e aumenta a concentração plasmática de varfarina no sangue", "Erva-de-são-joão, que induz o CYP1A2 e reduz a concentração da varfarina no plasma"], "gabarito": "C", "justificativa": "Fluconazol inibe o CYP2C9, que metaboliza a varfarina. Com a inibição, o fármaco acumula e o INR sobe; em cinco dias o paciente tem equimoses e gengivorragia (resumo: Farmacocinética, CYP450, caso do slide).", "tecnica": "Interação farmacocinética", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Por que a inibição enzimática por claritromicina causa toxicidade em poucos dias, enquanto a indução por rifampicina demora semanas?", "alternativas": ["Inibição depende de síntese de enzimas, que é lenta; indução é competitiva e atua em poucas horas", "Inibição é competitiva e imediata; indução exige síntese de enzimas, que é mais lenta", "Ambas são imediatas, mas a inibição afeta o rim, e a indução afeta apenas o fígado e o intestino", "Inibição ocorre apenas após semanas de uso, porque depende da eliminação do metabólito tóxico", "Indução ocorre em horas, porque o fármaco é liberado da albumina; a inibição depende do peso corporal"], "gabarito": "B", "justificativa": "Inibição é competitiva e acontece em horas a dias. Indução exige síntese de enzimas, o que leva dias a semanas. Ao suspender, o efeito se inverte com a mesma lógica temporal (resumo: Farmacocinética, indução e inibição).", "tecnica": "Inibição × indução", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "O paracetamol em dose tóxica gera um metabólito de fase I que causa lesão hepática. Qual é o nome desse metabólito e por que ele é produzido em excesso em dose alta?", "alternativas": ["Glicuronídeo; a via de glicuronidação aumenta e o conjugado se acumula no fígado", "Sulfato de paracetamol; a sulfatação é ativada pelo CYP2C9 e forma um produto tóxico", "Glutationa; a conjugação com glutationa libera o fármaco ativo na circulação sistêmica", "Acetilcolina; a fase I libera acetilcolina no fígado, que se acumula e danifica os hepatócitos", "NAPQI; a via de conjugação se satura e o metabólito de fase I se acumula"], "gabarito": "E", "justificativa": "Em dose tóxica, o paracetamol gera NAPQI na fase I. Quando a conjugação com glutationa se satura, o NAPQI se acumula e causa lesão hepática em 24–48 horas (resumo: Farmacocinética, metabolismo, e Autacoides).", "tecnica": "Metabolismo e NAPQI", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um recém-nascido recebe um fármaco eliminado por glicuronidação. Por que a dose deve ser ajustada, mesmo que a dose seja a mesma de um adulto?", "alternativas": ["A glicuronidação é mais intensa no neonato, e o fármaco é eliminado em excesso e rapidamente", "O neonato tem volume de distribuição maior, e isso reduz a meia-vida do fármaco de forma importante", "A glicuronidação é imatura no neonato, e a eliminação é mais lenta", "O neonato tem CYP3A4 hiperativo, o que converte o fármaco em metabólito inativo sem risco", "O neonato não tem fígado funcional, e o fármaco é eliminado somente pelo pulmão no primeiro mês"], "gabarito": "C", "justificativa": "Fase II (conjugação, como a glicuronidação) é imatura no neonato. A eliminação é mais lenta e o fármaco pode se acumular; por isso a dose é ajustada (resumo: Farmacocinética, populações especiais).", "tecnica": "Neonato e glicuronidação", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um fármaco tem meia-vida de 6 horas. Após quantas horas de dosagem contínua a concentração atinge cerca de 94% do equilíbrio clínico?", "alternativas": ["24 horas, equivalente a quatro meias-vidas", "6 horas, porque a primeira meia-vida já atinge o equilíbrio clínico completo", "12 horas, equivalente a duas meias-vidas, com 75% da concentração de equilíbrio", "18 horas, equivalente a três meias-vidas, com 87,5% da concentração de equilíbrio", "36 horas, equivalente a seis meias-vidas, com 100% da concentração de equilíbrio"], "gabarito": "A", "justificativa": "Uma meia-vida = 50%; duas = 75%; três = 87,5%; quatro a cinco = 94–97%, o equilíbrio clínico. Com meia-vida de 6 h, quatro meias-vidas equivalem a 24 h (resumo: Farmacocinética, acúmulo).", "tecnica": "Acúmulo e meia-vida", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Em um paciente, a meia-vida de um fármaco dobrou após queda do clearance renal, sem alteração do Vd. Qual é a relação correta entre meia-vida, Vd e clearance?", "alternativas": ["t½ = 0,693 × CL ÷ Vd; com Vd constante, reduzir CL reduz a meia-vida pela metade", "t½ = Vd × CL; a meia-vida só depende do clearance e não do volume de distribuição", "t½ = Dose ÷ C₀; reduzir o clearance não altera a meia-vida, que depende apenas da dose", "t½ = 0,693 ÷ Vd; a meia-vida é independente do clearance em qualquer situação clínica", "t½ = 0,693 × Vd ÷ CL; com Vd constante, reduzir CL dobra a meia-vida"], "gabarito": "E", "justificativa": "t½ = 0,693 × Vd ÷ CL. Com Vd constante, reduzir o clearance aumenta a meia-vida; por isso o intervalo entre doses deve ser revisado (resumo: Farmacocinética, parâmetros que orientam a dose).", "tecnica": "Meia-vida", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Por que fenitoína e etanol têm comportamento de cinética de ordem zero em doses altas?", "alternativas": ["Porque as enzimas hepáticas se saturam, e a quantidade eliminada por tempo fica constante", "Porque a eliminação é sempre proporcional à concentração, o que mantém a meia-vida constante em qualquer dose", "Porque esses fármacos se ligam totalmente à albumina, que os libera de forma constante ao fígado", "Porque são eliminados pelo pulmão, que tem capacidade fixa e independente da concentração plasmática", "Porque têm volume de distribuição muito baixo, o que impede a eliminação renal de forma proporcional"], "gabarito": "A", "justificativa": "Na ordem zero, as enzimas estão saturadas e a quantidade eliminada por tempo é constante. Pequeno aumento de dose gera grande aumento de concentração (resumo: Farmacocinética, ordem zero).", "tecnica": "Ordem zero", "slide": null}], "id": "farma-gilmar-02", "titulo": "Aula 2", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-03"] = {"subtitulo": "Etapas do desenvolvimento de fármacos: pré-clínica, fases I a IV", "pdf": "pdf/gilmar/aula-03.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 3 · Etapas do desenvolvimento de fármacos (Prof. Dr. Gilmar S. Erzinger)", "FDA; ICH E6, E8 e M3; Anvisa; Brunton e Knollmann (Goodman & Gilman), citados nos slides", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Fases clínicas (slide 29)", "colunas": ["Fase", "Participantes", "Objetivo principal", "Pergunta-chave"], "linhas": [["I", "Voluntários saudáveis e/ou pacientes", "Segurança, tolerabilidade, PK/PD", "Qual dose e exposição são toleráveis?"], ["II", "Pacientes", "Eficácia inicial, dose e segurança", "Funciona, e qual dose ou regime usar?"], ["III", "Pacientes", "Confirmar eficácia e segurança", "O benefício é consistente e clinicamente relevante?"], ["IV", "População em uso real", "Farmacovigilância e efetividade", "O que ocorre após ampla utilização?"]]}, "resumo": [{"titulo": "1. O caminho de um fármaco e o funil de risco", "pontos": [{"t": "Tempo e custo", "sub": ["Do início da descoberta à aprovação, o caminho dura de 10 a 15 anos (slide 3).", "Antes de testar em humanos, é preciso autorização da agência reguladora e aprovação ética. Antes de vender, é preciso registro sanitário (slide 3).", "Custo estimado, incluindo os fracassos: US$ 1 a 2,6 bilhões por fármaco aprovado. As estimativas variam entre estudos, como PhRMA e DiMasi et al. (2016) (slide 4)."]}, {"t": "O funil", "sub": ["Entre 5.000 e 10.000 compostos avaliados na descoberta, cerca de 250 entram na pré-clínica. Cerca de 5 chegam aos ensaios clínicos, e 1 é aprovado para uso (slide 4).", "Por isso a taxa de fracasso é a regra. A aula mostra o funil para ensinar que a maioria das moléculas não chega ao paciente (slide 4)."]}]}, {"titulo": "2. Descoberta e pré-clínica", "pontos": [{"t": "Da descoberta ao candidato", "sub": ["Alvo terapêutico: identificar e validar a proteína, o receptor ou a via envolvida na doença (slide 7).", "Triagem: triagem de alto rendimento (HTS) e modelagem in silico encontram os hits. In silico significa simular por computador antes de experimentos em animais ou humanos (slide 7).", "Composto-líder e otimização: seleção dos hits mais promissores em potência, seletividade e perfil químico, com ajustes estruturais até o candidato (slides 6 e 7)."]}, {"t": "O que a pré-clínica avalia", "sub": ["Farmacodinâmica: mecanismo e eficácia em células, tecidos e animais. Farmacocinética (ADME): absorção, distribuição, metabolismo e excreção. Toxicologia: aguda, repetida, genotoxicidade e reprodutiva. Formulação e produção: forma, estabilidade e lote para estudos clínicos (slide 8).", "Os estudos seguem Boas Práticas de Laboratório (BPL), em geral em duas espécies, roedor e não roedor, sob os 3Rs: substituir, reduzir e refinar o uso de animais (slide 8).", "A pré-clínica responde se o fármaco produz o efeito esperado, qual é a relação dose-exposição-efeito, quais órgãos podem ser afetados, qual é a margem de segurança e qual dose inicial é aceitável para humanos (slide 10)."]}]}, {"titulo": "3. A ponte para os humanos", "pontos": [{"t": "Autorização e ética", "sub": ["No Brasil, a Anvisa analisa o dossiê de desenvolvimento clínico (DDCM). Nos EUA, a FDA analisa o pedido de IND (slide 12).", "No Brasil, o sistema CEP/Conep avalia riscos e benefícios e aprova o Termo de Consentimento Livre e Esclarecido (TCLE) (slide 12).", "As Boas Práticas Clínicas (BPC, ICH E6) são o padrão internacional que rege todos os ensaios (slide 12)."]}, {"t": "Princípios", "sub": ["Consentimento informado, avaliação risco-benefício, proteção dos participantes e qualidade dos dados (slide 11).", "Sucesso pré-clínico não garante eficácia clínica. A aula repete esse alerta (slide 11)."]}]}, {"titulo": "4. Fase I: segurança e farmacocinética", "pontos": [{"t": "Desenho e objetivos", "sub": ["20 a 100 participantes, em geral voluntários sadios, por meses a 1 ano. Cerca de 70% avançam para a fase II (slide 14).", "Objetivos: segurança e tolerabilidade, PK (ADME) e efeitos farmacodinâmicos, faixa de dose segura e dose máxima tolerada (slide 14).", "Desenhos SAD (doses únicas crescentes) e MAD (doses repetidas crescentes). Exceção: em oncologia e fármacos muito tóxicos, a fase I é feita direto em pacientes (slide 14)."]}, {"t": "Conceitos da fase I", "sub": ["FIH (first-in-human) é a primeira administração em seres humanos. Food effect avalia a influência da alimentação na exposição. Interações medicamentosas podem ser avaliadas quando relevantes (slide 16)."]}]}, {"titulo": "5. Fase II: o fármaco parece funcionar?", "pontos": [{"t": "Desenho e objetivos", "sub": ["100 a 300 pacientes com a doença-alvo, por até 2 anos. Cerca de 33% avançam para a fase III (slide 17).", "Objetivos: primeira evidência de eficácia (prova de conceito), relação dose-resposta, esquema posológico e segurança de curto prazo (slide 17).", "IIa costuma explorar prova de conceito e dose-resposta. IIb costuma definir a dose para os estudos confirmatórios. É a fase com maior taxa de fracasso (slide 17)."]}, {"t": "Randomização e controle", "sub": ["Estudo randomizado: a distribuição aleatória reduz a chance de que diferenças entre grupos expliquem o resultado. Estudo controlado: o grupo de comparação recebe placebo, tratamento padrão ou outra dose (slide 18).", "Exemplo da aula: 200 hipertensos randomizados, 100 com 20 mg do novo fármaco e 100 com placebo. A diferença de redução da pressão, de −5 mmHg (8 contra 3), sugere atividade terapêutica (slides 19 e 20)."]}]}, {"titulo": "6. Fase III: confirmação em larga escala", "pontos": [{"t": "Desenho e objetivos", "sub": ["300 a mais de 3.000 pacientes, em vários centros, por 1 a 4 anos. Cerca de 25 a 30% chegam ao registro (slide 21).", "Confirma eficácia e segurança em população maior, mais diversa e mais heterogênea. Detecta reações adversas menos frequentes (slides 21 e 23).", "Estudos pivotais são randomizados, duplo-cegos e multicêntricos. Os resultados formam a base principal do pedido de registro (slides 21 e 22)."]}]}, {"titulo": "7. Registro e fase IV", "pontos": [{"t": "Registro sanitário", "sub": ["A Anvisa avalia qualidade (fabricação, controle e estabilidade), segurança (dados de todas as fases), eficácia (estudos pivotais), relação benefício-risco, bula e inspeção de Boas Práticas de Fabricação (slide 26).", "A decisão regulatória não encerra a avaliação científica. O medicamento continua sendo monitorado após a comercialização (slide 25)."]}, {"t": "Fase IV: farmacovigilância", "sub": ["Milhares a milhões de usuários na prática real, de forma contínua. Detecta reações raras ou tardias, avalia uso prolongado e populações especiais, e investiga interações e novas indicações (slide 27).", "No Brasil, a notificação de eventos é feita pelo VigiMed (slide 27).", "Exemplo citado: o rofecoxibe (Vioxx) foi retirado do mercado em 2004, após evidências de aumento do risco cardiovascular (slide 27)."]}, {"t": "Eficácia × efetividade", "sub": ["Eficácia é o desempenho em condições controladas de pesquisa. Efetividade é o desempenho na prática real. Os conceitos são relacionados, mas não são sinônimos (slide 28)."]}]}, {"titulo": "8. Resumo e para a prova", "pontos": [{"t": "Resumo das fases clínicas", "sub": ["Fase I: voluntários e/ou pacientes; pergunta-chave sobre a dose e a exposição tolerável. Fase II: pacientes; pergunta sobre funcionar e qual dose usar. Fase III: pacientes; pergunta sobre benefício consistente e clinicamente relevante. Fase IV: população em uso real; pergunta sobre o que ocorre após ampla utilização (slide 29)."]}, {"t": "Por que um programa para", "sub": ["Falta de eficácia ou benefício clínico suficiente; problemas de segurança; perfil farmacocinético inadequado; dificuldades de formulação ou produção; interações ou limitações na população-alvo. Razões comerciais também podem parar um programa, mesmo com atividade biológica (slide 30)."]}]}, {"titulo": "9. Funil de desenvolvimento, custo e fases (complemento)", "pontos": [{"t": "Funil", "sub": ["Descoberta (5.000–10.000 compostos) → pré-clínica (~250) → ensaios clínicos (~5) → 1 aprovado.", "Tempo total: 10 a 15 anos. Custo estimado: US$ 1 a 2,6 bilhões, incluindo os fracassos; explica a patente e o preço do medicamento de referência."]}, {"t": "Fases em tabela", "sub": ["Pré-clínica: in vitro e modelos animais; farmacodinâmica, farmacocinética (ADME), toxicologia, formulação. Boas Práticas de Laboratório; em geral duas espécies; princípio dos 3R; modelagem in silico reduz o uso de animais.", "Fase I: 20 a 100, em geral voluntários sadios; segurança, tolerabilidade, farmacocinética, dose máxima tolerada. Exceção: em oncologia é feita diretamente em pacientes.", "Fase II: 100 a 300 pacientes; primeira evidência de eficácia (prova de conceito) e relação dose-resposta; maior taxa de fracasso, é onde a maioria dos candidatos cai.", "Fase III: 300 a 3.000 ou mais, multicêntrico; confirma eficácia e segurança em população ampla e detecta reações menos frequentes; randomizado e duplo-cego; base do registro.", "Fase IV: uso real; farmacovigilância de reações raras ou tardias, uso prolongado e populações especiais. Exemplo clássico: retirada do rofecoxibe em 2004 por risco cardiovascular."]}]}, {"titulo": "10. Eficácia × efetividade e tipos de medicamento", "pontos": [{"t": "Conceitos", "sub": ["Eficácia: desempenho em condições controladas de pesquisa. Efetividade: desempenho em condições reais de uso. Não são sinônimos: um fármaco eficaz pode ter baixa efetividade por má adesão, interações ou custo.", "Referência: o inovador, com eficácia comprovada no registro.", "Genérico: identificado pelo princípio ativo; precisa comprovar bioequivalência (parâmetros dentro de 80–125% do referência).", "Similar: marca própria; hoje também deve comprovar equivalência."]}]}], "glossario": [{"termo": "Fase I", "tecnica": "Ensaio clínico", "definicao": "Primeiros estudos em humanos, para segurança, tolerabilidade e farmacocinética.", "slide": 14}, {"termo": "SAD e MAD", "tecnica": "Fase I", "definicao": "Single Ascending Dose (dose única crescente) e Multiple Ascending Dose (doses repetidas crescentes).", "slide": 16}, {"termo": "FIH", "tecnica": "Fase I", "definicao": "First-in-human: primeira administração do candidato em seres humanos.", "slide": 16}, {"termo": "Estudo pivotal", "tecnica": "Fase III", "definicao": "Estudo randomizado, duplo-cego e multicêntrico, base do pedido de registro.", "slide": 21}, {"termo": "Randomização", "tecnica": "Desenho do ensaio", "definicao": "Distribuição aleatória dos participantes para os grupos, reduzindo vieses.", "slide": 18}, {"termo": "Farmacovigilância", "tecnica": "Fase IV", "definicao": "Monitoramento de reações adversas após a comercialização; no Brasil, notificação pelo VigiMed.", "slide": 27}, {"termo": "BPL", "tecnica": "Pré-clínica", "definicao": "Boas Práticas de Laboratório, padrão dos estudos não clínicos.", "slide": 8}, {"termo": "Farmacologia clínica", "tecnica": "Desenvolvimento", "definicao": "Estudo de fármacos em seres humanos, em fases progressivas.", "slide": 3}, {"termo": "First-in-human (FIH)", "tecnica": "Fase I", "definicao": "Primeira administração do candidato em seres humanos.", "slide": 16}, {"termo": "Food effect", "tecnica": "Fase I", "definicao": "Avaliação da influência da alimentação na exposição ao fármaco.", "slide": 16}, {"termo": "Fase IIa e IIb", "tecnica": "Fase II", "definicao": "IIa explora prova de conceito e relação dose-resposta. IIb define dose e regime para estudos confirmatórios.", "slide": 17}, {"termo": "Estudo controlado", "tecnica": "Desenho", "definicao": "Estudo com grupo de comparação: placebo, tratamento padrão ou outra dose.", "slide": 18}, {"termo": "Estudo duplo-cego", "tecnica": "Desenho", "definicao": "Nem o participante nem o pesquisador sabem qual grupo recebeu o fármaco.", "slide": 21}, {"termo": "ANVISA (Agência Nacional de Vigilância Sanitária)", "tecnica": "Regulação", "definicao": "Agência brasileira que analisa o dossiê clínico e concede o registro sanitário.", "slide": 12}, {"termo": "DDCM (dossiê de desenvolvimento clínico)", "tecnica": "Regulação", "definicao": "Documento analisado pela Anvisa antes da primeira dose em humanos.", "slide": 12}, {"termo": "FDA e IND", "tecnica": "Regulação", "definicao": "Agência reguladora dos EUA. O IND é o pedido para iniciar estudos em humanos.", "slide": 12}, {"termo": "EMA", "tecnica": "Regulação", "definicao": "Agência reguladora da União Europeia.", "slide": 26}, {"termo": "CEP e Conep", "tecnica": "Ética", "definicao": "Comitês de ética em pesquisa, que avaliam riscos e benefícios e aprovam o TCLE.", "slide": 12}, {"termo": "TCLE (Termo de Consentimento Livre e Esclarecido)", "tecnica": "Ética", "definicao": "Documento de consentimento do participante, aprovado pelo comitê de ética.", "slide": 12}, {"termo": "ICH E6 (Boas Práticas Clínicas)", "tecnica": "Padrão internacional", "definicao": "Padrão que rege todos os ensaios clínicos, do International Council for Harmonisation.", "slide": 12}, {"termo": "Boas Práticas de Laboratório (BPL)", "tecnica": "Pré-clínica", "definicao": "Normas que orientam os estudos pré-clínicos em laboratório.", "slide": 8}, {"termo": "Os 3Rs (substituir, reduzir e refinar)", "tecnica": "Pré-clínica", "definicao": "Princípios do uso de animais em pesquisa: substituir por métodos alternativos, reduzir o número e refinar o procedimento.", "slide": 8}, {"termo": "Modelagem in silico", "tecnica": "Descoberta", "definicao": "Simulação por computador para estudar fenômenos biológicos antes de experimentos.", "slide": 7}, {"termo": "Triagem de alto rendimento (HTS)", "tecnica": "Descoberta", "definicao": "Triagem automatizada de grandes bibliotecas de compostos, que encontra os hits.", "slide": 7}, {"termo": "Composto-líder (lead)", "tecnica": "Descoberta", "definicao": "Hit mais promissor em potência, seletividade e perfil químico.", "slide": 7}, {"termo": "Descoberta do candidato", "tecnica": "Descoberta", "definicao": "Identificação de alvo, triagem, composto-líder e otimização até o candidato a fármaco.", "slide": 6}, {"termo": "VigiMed", "tecnica": "Notificação", "definicao": "Sistema brasileiro de notificação de eventos adversos a medicamentos.", "slide": 27}, {"termo": "Rofecoxibe (Vioxx)", "tecnica": "Exemplo", "definicao": "Medicamento retirado do mercado em 2004, após aumento do risco cardiovascular detectado em uso real.", "slide": 27}, {"termo": "Eficácia", "tecnica": "Conceito", "definicao": "Desempenho do tratamento em condições controladas de pesquisa clínica.", "slide": 28}, {"termo": "Efetividade", "tecnica": "Conceito", "definicao": "Desempenho do tratamento em condições da prática real.", "slide": 28}, {"termo": "Registro sanitário", "tecnica": "Regulação", "definicao": "Autorização de comercialização após avaliação de qualidade, segurança e eficácia.", "slide": 26}, {"termo": "Boas Práticas de Fabricação", "tecnica": "Regulação", "definicao": "Normas de fabricação, inspecionadas antes do registro.", "slide": 26}, {"termo": "Custo de desenvolvimento (PhRMA e DiMasi)", "tecnica": "Dado", "definicao": "Estimativa de US$ 1 a 2,6 bilhões por fármaco aprovado, incluindo fracassos.", "slide": 4}], "caso": {"titulo": "Caso: novo fármaco para insuficiência cardíaca", "perfil": "Decisões em cada etapa do desenvolvimento.", "etapas": [{"titulo": "Etapa 1: onde estamos", "texto": "Uma empresa tem uma molécula para insuficiência cardíaca. Os estudos mostram atividade em modelos animais, mas ainda não há dados em humanos. A equipe precisa decidir o próximo passo.", "perguntas": [{"pergunta": "Qual é o próximo passo adequado, segundo a aula?", "alts": ["Obter autorização da agência e aprovação ética antes da primeira dose em humanos", "Lançar o produto no mercado, com a fase IV como único estudo", "Iniciar a fase III com milhares de pacientes sem fase I", "Dispensar a farmacocinética, pois a atividade já foi mostrada", "Testar em voluntários sem qualquer protocolo ou consentimento"], "erradas": ["Registro sanitário vem depois de todas as fases clínicas.", "Fase III sem fase I e II não é o caminho descrito.", "A farmacocinética é exigida antes da dose em humanos.", "Consentimento e protocolo são obrigatórios antes da inclusão de participantes."], "justificativa": "Antes de testar em humanos é preciso autorização da agência reguladora e aprovação ética (slides 3 e 12)."}]}, {"titulo": "Etapa 2: fase II", "texto": "Em um estudo de fase II com 200 pacientes, o grupo do novo fármaco reduz a pressão arterial em média 8 mmHg, e o grupo placebo, 3 mmHg.", "perguntas": [{"pergunta": "Qual é a interpretação mais adequada, segundo a aula?", "alts": ["Diferença de 5 mmHg sugere atividade terapêutica preliminar", "Prova definitiva de eficácia, dispensando a fase III", "Redução de 8 mmHg prova ausência de efeito placebo", "Diferença sem relevância, pois fase II não compara grupos", "Evidência de toxicidade, pelo efeito de 8 mmHg"], "erradas": ["Fase II não confirma eficácia; a fase III é que confirma.", "Uma redução de 8 mmHg não prova ausência de efeito placebo, que o grupo controle mede.", "Fase II compara grupos randomizados, por definição.", "A redução de pressão é o efeito desejado, e não toxicidade."], "justificativa": "Na fase II, a diferença entre grupos sugere atividade; a fase III confirma a eficácia (slides 19, 20 e 21)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um laboratório afirma que um composto que passou pela pré-clínica já tem alta chance de aprovação. Qual é a crítica mais precisa, segundo o funil de desenvolvimento?", "alternativas": ["A pré-clínica já aprova o fármaco, e os ensaios clínicos servem apenas para cobrar o preço de mercado do produto", "Dos cerca de 250 compostos que chegam à clínica, poucos são aprovados; a maioria cai nos ensaios", "A pré-clínica elimina a necessidade de fase I, porque a farmacocinética em animais é idêntica à humana", "A pré-clínica é o último estágio antes do registro, e a fase III é apenas um formalismo administrativo do órgão", "A pré-clínica define a bioequivalência, o que dispensa qualquer ensaio clínico em pacientes com a doença"], "gabarito": "B", "justificativa": "O funil tem 5.000 a 10.000 compostos na descoberta, cerca de 250 na pré-clínica, cerca de 5 em ensaios clínicos e 1 aprovado. A maioria cai nos ensaios (resumo: Desenvolvimento de fármacos).", "tecnica": "Funil de desenvolvimento", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Por que o princípio dos 3R e a modelagem in silico são incentivados na pré-clínica?", "alternativas": ["Para aumentar o número de animais por experimento, o que garante estatística mais robusta para a aprovação", "Para substituir a farmacocinética por cálculos matemáticos, dispensando qualquer teste de toxicologia", "Para que os animais sejam testados diretamente em pacientes, acelerando a passagem para a fase I", "Para eliminar a necessidade de Boas Práticas de Laboratório, que são exigidas apenas em fase III", "Para reduzir o uso de animais em experimentos, sem comprometer a avaliação de farmacocinética e toxicidade"], "gabarito": "E", "justificativa": "Os 3R (replacement, reduction, refinement) reduzem o uso de animais. A modelagem in silico também diminui esse uso, sem dispensar avaliação de ADME e toxicidade (resumo: Desenvolvimento de fármacos, pré-clínica).", "tecnica": "Pré-clínica e 3R", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um fármaco é testado em oncologia. Por que a fase I é diferente nesse caso em relação às demais áreas?", "alternativas": ["É realizada diretamente em pacientes com a doença, e não em voluntários sadios", "É realizada apenas com animais, porque pacientes oncológicos não podem participar de nenhum ensaio", "É realizada com mais de 300 voluntários sadios, porque o tumor exige estatística de grande porte", "É realizada somente após a fase III, como estudo de fase IV em pacientes com câncer avançado", "É realizada sem avaliação de segurança, porque a doença tem prognóstico muito ruim em qualquer caso"], "gabarito": "A", "justificativa": "Em regra, a fase I é feita em voluntários sadios. Em oncologia ela é feita diretamente em pacientes, por causa da toxicidade do tratamento (resumo: Desenvolvimento de fármacos, fase I).", "tecnica": "Fase I em oncologia", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um fármaco aprovado é usado por milhões de pessoas e, após dois anos, surge um efeito adverso raro. Qual fase permite detectar esse tipo de evento, e por que ele não apareceu antes?", "alternativas": ["Fase IV; os estudos anteriores tinham número de participantes insuficiente para detectar eventos raros", "Fase I; o evento era inexistente nos voluntários sadios, que não têm a doença de base do paciente", "Fase II; a dose-resposta não foi ajustada, o que causa eventos raros em pacientes com insuficiência renal", "Pré-clínica; os animais não apresentam o evento porque têm metabolismo diferente do humano", "Fase III; o duplo-cego impediu que os participantes relatassem o evento raro durante o estudo"], "gabarito": "A", "justificativa": "A fase IV, de farmacovigilância em uso real, detecta eventos raros ou tardios. Os ensaios anteriores, com centenas a milhares de participantes, não têm poder para eventos muito raros (resumo: Desenvolvimento de fármacos, fase IV).", "tecnica": "Fase IV e eventos raros", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Por que a fase III é multicêntrica e tem muitos participantes, em comparação com a fase II?", "alternativas": ["Para descobrir o mecanismo de ação, que só pode ser estudado em grandes populações de pacientes", "Para medir a biodisponibilidade oral, que exige amostras de sangue de centenas de voluntários", "Para testar a dose máxima tolerada, que só é possível com participantes saudáveis em número alto", "Para definir a bioequivalência com o genérico, que exige comparação com centenas de pacientes", "Para confirmar eficácia e segurança em população ampla e detectar reações menos frequentes"], "gabarito": "E", "justificativa": "A fase III tem 300 a 3.000 ou mais pacientes, em vários centros, para confirmar eficácia e segurança e detectar reações menos frequentes. É randomizada e duplo-cega (resumo: Desenvolvimento de fármacos, fase III).", "tecnica": "Fase III", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um estudo de fase II mostra resultado promissor, mas o efeito é pequeno e a dose-resposta não é clara. Qual decisão é a mais coerente com o papel da fase II?", "alternativas": ["Avançar direto para a fase IV, porque o efeito pequeno já indica segurança suficiente para o uso amplo", "Registrar o fármaco com base na fase I, porque a dose-resposta só é importante após a aprovação regulatória", "Abandonar a pesquisa em pacientes e retornar à pré-clínica, porque a fase II só mede farmacocinética em animais", "Ajustar dose e população antes de avançar, pois a fase II mostra dose-resposta", "Substituir o placebo por um genérico, porque a fase II exige comparação com um medicamento já registrado"], "gabarito": "D", "justificativa": "Fase II dá a primeira evidência de eficácia e a relação dose-resposta. Um resultado pequeno e sem dose-resposta clara leva a ajustes de dose e de população antes de avançar (resumo: Desenvolvimento de fármacos, fase II).", "tecnica": "Fase II e decisão", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Por que o registro de um medicamento depende de fase III, e não apenas de fase I?", "alternativas": ["Porque a fase III tem desenho randomizado e duplo-cego, com população ampla, base para comprovar eficácia", "Porque a fase I tem apenas doses únicas, e o registro exige pelo menos vinte doses em esquema contínuo", "Porque a fase I é realizada em animais, e o registro só aceita dados de estudos com pacientes humanos", "Porque a fase I não mede segurança, e o registro exige que a segurança seja medida somente após a fase III", "Porque a fase I é a farmacovigilância, que só pode ser feita após a aprovação do fármaco pelo órgão regulador"], "gabarito": "A", "justificativa": "O registro se apoia na fase III, randomizada e duplo-cega, em população ampla, que confirma eficácia e segurança. A fase I, em voluntários sadios, avalia sobretudo segurança e farmacocinética (resumo: Desenvolvimento de fármacos).", "tecnica": "Base do registro", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um fármaco é retirado do mercado após estudos de farmacovigilância. Por que essa fase é contínua, e não termina com a aprovação?", "alternativas": ["Porque o fármaco perde a patente após a aprovação, e a farmacovigilância é uma exigência do mercado de genéricos", "Porque a fase IV substitui a fase III, que é anulada pelo órgão regulador após cinco anos de comercialização", "Porque reações raras, uso prolongado e populações especiais só aparecem em uso real, em larga escala", "Porque o fármaco só pode ser vendido por um ano, e a farmacovigilância avalia a renovação do registro", "Porque a fase IV é feita em animais, que continuam recebendo o fármaco durante toda a vida comercial"], "gabarito": "C", "justificativa": "A fase IV é contínua. Detecta reações raras ou tardias, efeitos de uso prolongado e de populações especiais. Exemplo clássico: retirada do rofecoxibe em 2004 (resumo: Desenvolvimento de fármacos, fase IV).", "tecnica": "Farmacovigilância contínua", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um fármaco tem eficácia comprovada em ensaio controlado. Por que a efetividade real pode ser menor, mesmo com o mesmo princípio ativo?", "alternativas": ["Porque a efetividade depende da cor da cápsula, que influencia a percepção do paciente sobre o tratamento", "Porque a efetividade é medida apenas em animais, e os resultados em humanos sempre são inferiores", "Porque o ensaio controlado usa placebo ativo, que aumenta a eficácia observada em comparação ao uso real", "Por adesão irregular, interações com outros fármacos e custo, que não existem em condições controladas", "Porque o ensaio controlado usa dose única, e o uso real sempre exige doses menores para evitar toxicidade"], "gabarito": "D", "justificativa": "Eficácia é o desempenho em condições controladas; efetividade é o desempenho em condições reais, afetado por adesão, interações e custo. Não são sinônimos (resumo: Desenvolvimento de fármacos, eficácia × efetividade).", "tecnica": "Eficácia × efetividade", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um genérico é aprovado com parâmetros de bioequivalência entre 80% e 125% do referência. Qual é o significado desse intervalo?", "alternativas": ["O genérico pode ter eficácia de até 125% do referência, o que o torna mais potente sem comprovação clínica", "O genérico deve custar entre 80% e 125% do preço do referência, por determinação do órgão regulador", "O genérico deve ter o mesmo excipiente do referência, em proporção entre 80% e 125% da massa total", "Os parâmetros farmacocinéticos do genérico devem ficar dentro desse intervalo em relação ao referência", "O genérico deve ter meia-vida de 80% a 125% do referência, o que o torna clinicamente idêntico ao original"], "gabarito": "D", "justificativa": "Genérico é identificado pelo princípio ativo e precisa comprovar bioequivalência, com parâmetros dentro de 80 a 125% do referência (resumo: Desenvolvimento de fármacos, referência × genérico × similar).", "tecnica": "Bioequivalência", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Qual é a diferença entre um genérico e um similar, segundo a aula?", "alternativas": ["O genérico tem marca própria e dispensa comprovação; o similar é identificado apenas pelo princípio ativo", "O genérico é sempre mais caro que o referência; o similar é sempre mais barato e não precisa de registro", "O genérico é produzido sem princípio ativo; o similar contém princípio ativo diferente do referência", "O genérico é o inovador com patente vigente; o similar é o fármaco que expirou a patente e perdeu eficácia", "Genérico: pelo princípio ativo; similar: marca própria; ambos comprovam equivalência"], "gabarito": "E", "justificativa": "O genérico é identificado pelo princípio ativo e precisa comprovar bioequivalência. O similar tem marca própria; hoje também deve comprovar equivalência (resumo: Desenvolvimento de fármacos, tipos de medicamento).", "tecnica": "Genérico × similar", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Por que o medicamento de referência tem preço elevado mesmo após ser superado por genéricos, segundo a lógica do custo de desenvolvimento?", "alternativas": ["Porque o genérico é fabricado com princípio ativo mais caro, o que eleva o preço do referência por consequência", "Porque o custo de desenvolvimento, incluindo os fracassos, é recuperado pela patente e pelo preço do inovador", "Porque o órgão regulador fixa o preço do referência em 125% do genérico, por determinação legal", "Porque a fase IV exige que o referência seja vendido por um preço fixo durante toda a vida comercial", "Porque o referência contém dois princípios ativos, e o custo de cada um é cobrado separadamente do paciente"], "gabarito": "B", "justificativa": "O custo estimado de desenvolvimento é de US$ 1 a 2,6 bilhões, incluindo os fracassos. A patente e o preço do referência buscam recuperar esse investimento (resumo: Desenvolvimento de fármacos, custo).", "tecnica": "Custo e patente", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um estudo de fase I avalia doses únicas e múltiplas crescentes em voluntários sadios. Qual é o objetivo principal dessa etapa?", "alternativas": ["Confirmar eficácia em pacientes com a doença, com comparação randomizada contra placebo", "Avaliar segurança, tolerabilidade e farmacocinética, com a dose máxima tolerada", "Medir a efetividade em uso real, com registro de adesão e de custo do tratamento", "Descobrir o mecanismo de ação do fármaco, que é estudado apenas em modelo animal", "Comparar a bioequivalência com o genérico, por meio de amostras de urina de voluntários"], "gabarito": "B", "justificativa": "Fase I, com 20 a 100 voluntários sadios, avalia segurança, tolerabilidade, farmacocinética e dose máxima tolerada, com doses únicas e múltiplas crescentes (resumo: Desenvolvimento de fármacos, fase I).", "tecnica": "Fase I", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que o desenho da fase III exige randomização e duplo-cego, e não apenas um grupo tratado?", "alternativas": ["Para que o custo do estudo seja menor, já que o duplo-cego dispensa o uso de placebo", "Para que a dose máxima tolerada seja determinada com precisão em pacientes com a doença", "Para que os grupos sejam comparáveis e para que expectativas não influenciem o resultado", "Para que o fármaco seja aprovado mais rápido, com a fase III substituindo a fase II inteira", "Para que a farmacovigilância seja dispensada, porque a randomização elimina reações adversas"], "gabarito": "C", "justificativa": "Randomização torna os grupos comparáveis; duplo-cego impede que participante e pesquisador saibam quem recebeu o ativo. Juntos, evitam que expectativas influenciem o resultado (resumo: Desenvolvimento de fármacos, fase III).", "tecnica": "Desenho da fase III", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Na pré-clínica, por que se usam em geral duas espécies animais diferentes?", "alternativas": ["Para aumentar o número de animais e reduzir o custo, já que a segunda espécie substitui o grupo controle", "Para que a segunda espécie seja usada na fase I, dispensando a avaliação de segurança em voluntários sadios", "Para comparar farmacocinética e toxicidade em modelos distintos, reduzindo o risco de extrapolação falha", "Para testar o fármaco em uma espécie protegida, exigência legal para todos os medicamentos já registrados", "Para que a bioequivalência com o genérico seja calculada por comparação entre espécies diferentes de laboratório"], "gabarito": "C", "justificativa": "Em geral, a pré-clínica usa duas espécies, para comparar farmacocinética e toxicidade e reduzir o risco de extrapolação falha para humanos (resumo: Desenvolvimento de fármacos, pré-clínica).", "tecnica": "Pré-clínica", "slide": null}], "id": "farma-gilmar-03", "titulo": "Aula 3", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-04"] = {"subtitulo": "Colinérgicos e anticolinérgicos, anticolinesterásicos e nicotínicos", "pdf": "pdf/gilmar/aula-04.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 4 · Colinérgicos e Anticolinérgicos (Prof. Dr. Gilmar S. Erzinger)", "Brunton e Knollmann (Goodman & Gilman); Katzung (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Receptores colinérgicos (slide 8)", "colunas": ["Tipo", "Localização principal", "Mecanismo", "Efeito da ativação"], "linhas": [["M1", "SNC, gânglios, células parietais", "Gq → IP3/DAG, ↑Ca²⁺", "Cognição, ↑ secreção gástrica"], ["M2", "Coração (nós SA e AV)", "Gi → ↓AMPc, abre canais K⁺", "↓ frequência cardíaca, ↓ condução AV"], ["M3", "Músculo liso, glândulas, endotélio", "Gq → IP3/DAG, ↑Ca²⁺", "Contração, secreção, vasodilatação via NO"], ["M4 / M5", "SNC", "Gi / Gq", "Modulação central"], ["NN", "Gânglios, medula adrenal, SNC", "Canal iônico (Na⁺/K⁺)", "Despolarização ganglionar, liberação de catecolaminas"], ["NM", "Placa motora", "Canal iônico (Na⁺/K⁺)", "Contração do músculo esquelético"]]}, "resumo": [{"titulo": "1. Acetilcolina no sistema nervoso autônomo", "pontos": [{"t": "Parassimpático e simpático", "sub": ["Parassimpático: origem craniossacral (NC III, VII, IX e X, e S2 a S4). Gânglios próximos ou dentro do órgão-alvo. Pré-ganglionar libera ACh em receptor nicotínico (NN). Pós-ganglionar libera ACh em receptor muscarínico. Função: repouso e digestão (slide 3).", "Simpático: origem toracolombar (T1 a L2). Gânglios paravertebrais e pré-vertebrais. Pré-ganglionar libera ACh em NN. Pós-ganglionar libera noradrenalina em receptores α e β. Exceções: glândulas sudoríparas (ACh em M3) e medula adrenal, que libera adrenalina (slide 3)."]}]}, {"titulo": "2. O ciclo da acetilcolina", "pontos": [{"t": "Cinco etapas, cada uma um alvo", "sub": ["Captação de colina pelo transportador CHT, dependente de Na⁺. É a etapa limitante, bloqueada pelo hemicolínio (slide 5).", "Síntese: a colina acetiltransferase (ChAT) une acetil-CoA e colina, formando ACh (slides 5 e 6).", "Armazenamento: o VAChT leva a ACh para as vesículas, bloqueado pelo vesamicol (slide 5).", "Liberação: a entrada de Ca²⁺ e as proteínas SNARE liberam a ACh na fenda. A toxina botulínica impede essa liberação (slides 5 e 6).", "Término: a acetilcolinesterase (AChE) hidrolisa a ACh em colina e acetato, em microssegundos. A colina é recaptada e reutilizada (slides 5 e 7)."]}]}, {"titulo": "3. Receptores muscarínicos e nicotínicos", "pontos": [{"t": "Muscarínicos (proteína G)", "sub": ["M1: SNC, gânglios e células parietais; via Gq, IP₃/DAG e ↑Ca²⁺; aumenta a secreção gástrica (slide 8).", "M2: coração (nós SA e AV); via Gi, com ↓AMPc e abertura de canais de K⁺. Reduz a frequência cardíaca e a condução AV (slides 8 e 11).", "M3: músculo liso, glândulas e endotélio; via Gq. Causa contração e secreção, e vasodilatação via NO no endotélio (slides 8, 13 e 15).", "M4 e M5: SNC, com via Gi ou Gq, para modulação central (slide 8).", "Mnemônico da aula: receptores ímpares (M1, M3, M5) são Gq; pares (M2, M4) são Gi (slide 8)."]}, {"t": "Nicotínicos (canal iônico)", "sub": ["NN: gânglios autonômicos, medula adrenal e SNC, com despolarização ganglionar e liberação de catecolaminas. NM: placa motora, com contração do músculo esquelético (slide 8).", "A resposta nicotínica é rápida, porque o próprio receptor é um canal de Na⁺/K⁺. A resposta muscarínica é mais lenta, porque passa por proteína G (slide 17)."]}, {"t": "Catecolaminas", "sub": ["Dopamina controla movimentos, motivação e recompensa. Noradrenalina atua na atenção e na resposta simpática. Adrenalina prepara o organismo para o estresse (slide 14)."]}]}, {"titulo": "4. Efeitos da estimulação muscarínica", "pontos": [{"t": "Órgão por órgão", "sub": ["Olho: miose, acomodação para perto e redução da pressão intraocular (slide 18).", "Coração: bradicardia e menor condução AV, por M2. Vasos: vasodilatação via NO endotelial, por M3, com queda da pressão (slide 18).", "Brônquios: broncoconstrição e aumento da secreção brônquica. Trato GI: aumento da motilidade e das secreções, com relaxamento de esfíncteres. Bexiga e glândulas: contração do detrusor, aumento de saliva, lágrima e suor (slide 18)."]}]}, {"titulo": "5. Agonistas colinérgicos", "pontos": [{"t": "Diretos", "sub": ["Betanecol estimula a contração da bexiga e facilita a micção. Pilocarpina aumenta a secreção salivar e reduz a pressão intraocular. Carbacol atua em receptores M e N (slide 20).", "Ésteres de colina e alcaloides se diferenciam pela hidrólise pela AChE. A acetilcolina é hidrolisada muito rapidamente. Metacolina tem hidrólise lenta e é usada no teste de broncoprovocação. Carbacol e betanecol são resistentes à AChE. Pilocarpina não é substrato (slide 29).", "Usos: pilocarpina no glaucoma; betanecol na atonia vesical e gastrointestinal pós-operatória. Os efeitos sistêmicos são miose, bradicardia e aumento generalizado de secreções (slide 25)."]}, {"t": "Indiretos (anticolinesterásicos)", "sub": ["Inibem a AChE. A ACh fica mais tempo na fenda e aumenta sua ação (slide 21).", "Neostigmina aumenta a transmissão colinérgica e serve para miastenia e reversão de bloqueio neuromuscular. Piridostigmina é usada na miastenia gravis. Donepezila é usada no Alzheimer (slide 21)."]}]}, {"titulo": "6. Miastenia gravis", "pontos": [{"t": "Fisiopatologia e clínica", "sub": ["Doença autoimune. Autoanticorpos atacam o receptor nicotínico da placa motora, e a transmissão neuromuscular falha (slides 22 e 23).", "Fraqueza flutuante que piora com o esforço e melhora com o repouso. Ptose, diplopia, disfagia, fala anasalada e fraqueza de braços e pernas. Em casos graves, a musculatura respiratória (slide 24)."]}, {"t": "Tratamento", "sub": ["Sintomático: piridostigmina, várias vezes ao dia. Ela não elimina os anticorpos; mantém mais ACh na fenda para compensar a perda de receptores funcionais (slides 23 e 24).", "Modificadores: corticoide, imunossupressores e timectomia. Crise: imunoglobulina IV ou plasmaférese, além de suporte ventilatório (slide 23)."]}, {"t": "Crise miastênica × crise colinérgica", "sub": ["Crise miastênica: dose insuficiente ou piora da doença. Fraqueza progressiva, sem sinais muscarínicos. Melhora com mais anticolinesterásico.", "Crise colinérgica: excesso de anticolinesterásico. Fraqueza por bloqueio despolarizante, com miose, sialorreia, bradicardia e fasciculações. Piora com mais anticolinesterásico (slide 26)."]}]}, {"titulo": "7. Reversão de bloqueio, Alzheimer e efeito teto", "pontos": [{"t": "Reversão e demência", "sub": ["Reversão de bloqueadores neuromusculares (BNM): a neostigmina aumenta a ACh, que compete com o BNM adespolarizante. Deve-se sempre associar glicopirrolato ou atropina. Não reverte bloqueio profundo (slide 27).", "Doença de Alzheimer: déficit colinérgico cortical. O benefício é sintomático e modesto, sem alterar a progressão. Efeitos: náuseas, diarreia, bradicardia e síncope (slide 27)."]}, {"t": "Efeito teto", "sub": ["Efeito teto é o limite de eficácia: aumentar a dose não aumenta mais o efeito. No bloqueio profundo, pode não haver receptores disponíveis para recuperar a transmissão (slide 28)."]}]}, {"titulo": "8. Efeitos adversos e antídoto", "pontos": [{"t": "Excesso muscarínico e cardiorrespiratório", "sub": ["Excesso muscarínico segue o mnemônico SLUDGE: salivação, lacrimejamento, urina, diarreia, cólica e êmese. Cardiorrespiratório: bradicardia, hipotensão, broncoespasmo e broncorreia (slide 30).", "Contraindicações: asma e DPOC, úlcera péptica, obstrução urinária ou intestinal mecânica. Cautela com bradiarritmias, doença coronariana e hipertireoidismo (slide 30)."]}, {"t": "Antídoto", "sub": ["A atropina, antagonista muscarínico competitivo, reverte os efeitos muscarínicos. Não corrige os efeitos nicotínicos, como a fraqueza muscular (slide 30)."]}]}, {"titulo": "9. Antagonistas muscarínicos (anticolinérgicos)", "pontos": [{"t": "Atropina por dose", "sub": ["Cerca de 0,5 mg: boca seca, redução da sudorese e bradicardia leve. Cerca de 1 mg: taquicardia, sede e leve midríase. Cerca de 2 mg: midríase, cicloplegia e palpitações. Cerca de 5 mg: retenção urinária, redução da motilidade e pele quente e seca. Acima de 10 mg: agitação, delírio, alucinações, hipertermia e coma (slide 32)."]}, {"t": "Uso clínico", "sub": ["Atropina: bradicardia sintomática, intoxicação por organofosforados e carbamatos, e antissialagogo pré-anestésico (slides 33 e 34).", "Escopolamina: cinetose, em adesivo transdérmico. Butilescopolamina: cólicas gastrointestinais, biliares e renais, sem passar pela BHE. Ipratrópio e tiotrópio: broncodilatação na DPOC, com tiotrópio LAMA uma vez ao dia (slide 33).", "Tropicamida e ciclopentolato: midríase e cicloplegia. Oxibutinina, tolterodina e solifenacina: bexiga hiperativa. Biperideno e triexifenidil: parkinsonismo. Glicopirrolato: antissialagogo e reversão de BNM junto à neostigmina (slide 33)."]}, {"t": "Aminas terciárias × quaternárias", "sub": ["Terciárias, como atropina, escopolamina, biperideno e oxibutinina, são lipossolúveis, atravessam a BHE e causam efeitos centrais (slides 35 e 37).", "Quaternárias, como ipratrópio, tiotrópio, butilescopolamina e glicopirrolato, são carregadas, têm absorção oral pobre e não atravessam a BHE. Seus efeitos são periféricos (slides 36 e 37)."]}, {"t": "Síndrome anticolinérgica", "sub": ["Seco como osso; vermelho como pimentão; quente como fogo; cego como morcego; louco como chapeleiro. Também há taquicardia, retenção urinária e íleo (slide 38).", "Causas: atropina, plantas como a Datura (trombeteira), antidepressivos tricíclicos e anti-histamínicos de 1ª geração. Evitar em glaucoma de ângulo fechado, hiperplasia prostática, obstrução GI, taquiarritmias e idosos (critérios de Beers; slide 38)."]}]}, {"titulo": "10. Fármacos nicotínicos", "pontos": [{"t": "Agonistas e bloqueadores", "sub": ["Nicotina tem ação bifásica: estimula e depois bloqueia os gânglios. É usada na reposição para cessar o tabagismo (slide 40).", "Vareniclina é agonista parcial α4β2, que reduz a fissura e a recompensa. Efeitos: náuseas e sonhos vívidos (slide 40).", "Succinilcolina é agonista NM que causa despolarização persistente da placa motora, com paralisia temporária (slide 42).", "Bloqueadores ganglionares, como mecamilamina e trimetafano, bloqueiam simpático e parassimpático. Hoje têm uso muito restrito (slide 40)."]}, {"t": "Bloqueio ganglionar", "sub": ["Vence o tônus predominante de cada órgão: vasos (vasodilatação e hipotensão ortostática), coração (taquicardia), íris (midríase), intestino (constipação), bexiga (retenção) e glândulas (xerostomia e anidrose) (slide 43)."]}]}, {"titulo": "11. Anticolinesterásicos: mecanismo e classificação", "pontos": [{"t": "A enzima", "sub": ["AChE está na fenda, na placa motora e nas hemácias. Butirilcolinesterase é a pseudocolinesterase plasmática, sintetizada no fígado. Seus substratos incluem succinilcolina, mivacúrio e anestésicos locais do tipo éster (slide 48).", "Inibir a AChE aumenta a ACh em todas as sinapses colinérgicas: muscarínicas, ganglionares, placa motora e SNC (slide 48)."]}, {"t": "Três formas de inibição", "sub": ["Reversíveis, como o edrofônio: ligação eletrostática ao sítio aniônico, com duração de minutos (slide 50).", "Carbamatos, como neostigmina, piridostigmina, fisostigmina e rivastigmina: carbamilam a serina, com hidrólise lenta. Duração de 30 minutos a 6 horas (slide 50).", "Organofosforados, como malation, clorpirifós, sarin e VX: fosforilam a serina de modo estável. A inibição é irreversível após o envelhecimento da enzima (slide 50)."]}, {"t": "Usos clínicos", "sub": ["Edrofônio: teste diagnóstico de miastenia, de ação de 5 a 15 minutos. Neostigmina: reversão de BNM e miastenia; retenção urinária e íleo pós-operatórios. Piridostigmina: miastenia crônica (slide 51).", "Fisostigmina atravessa a BHE e é usada na intoxicação anticolinérgica com delírio. Donepezila, rivastigmina e galantamina são usadas no Alzheimer; rivastigmina também na demência da doença de Parkinson (slide 51)."]}]}, {"titulo": "12. Intoxicação por anticolinesterásicos", "pontos": [{"t": "Fontes e síndrome aguda", "sub": ["Fontes: agrotóxicos, com exposição ocupacional sem EPI e tentativas de suicídio. O chumbinho, raticida ilegal que frequentemente contém aldicarbe (carbamato), é causa comum no Brasil. Agentes de guerra como sarin, soman, VX e Novichok (slide 53).", "Síndrome muscarínica: miose, sialorreia, sudorese, broncorreia, broncoespasmo, bradicardia, vômitos e diarreia. Síndrome nicotínica: fasciculações, fraqueza, paralisia do diafragma e taquicardia. SNC: ansiedade, convulsões, depressão respiratória e coma (slide 54)."]}, {"t": "Tratamento", "sub": ["1) Descontaminar: remover roupas e lavar a pele, com EPI da equipe. 2) Via aérea: oxigênio e intubação se necessário, evitando succinilcolina. 3) Atropina: 1 a 2 mg IV, dobrando a cada 5 minutos até secar as secreções brônquicas. 4) Pralidoxima: reativa a AChE antes do envelhecimento e atua nos efeitos nicotínicos. 5) Convulsões: diazepam ou midazolam IV (slide 55).", "Diagnóstico clínico, confirmado por colinesterase eritrocitária ou plasmática. A síndrome intermediária ocorre de 24 a 96 horas após a crise. A neuropatia tardia, de 1 a 3 semanas, é polineuropatia distal (slide 56).", "Tempo é enzima: a oxima só reativa a AChE antes do envelhecimento. Para o soman, isso ocorre em minutos; para inseticidas, em horas. Carbamatos têm quadro mais curto e não envelhecem a enzima (slide 56)."]}]}, {"titulo": "13. Ciclo da acetilcolina e alvos farmacológicos", "pontos": [{"t": "Etapas e bloqueadores", "sub": ["Captação de colina: etapa limitante; bloqueada pelo hemicolínio.", "Síntese pela colina acetiltransferase.", "Estocagem na vesícula pelo VAChT; bloqueada pelo vesamicol.", "Liberação por influxo de Ca²⁺ e proteínas SNARE; bloqueada pela toxina botulínica.", "Ação no receptor; degradação pela acetilcolinesterase em microssegundos; colina recaptada e reutilizada."]}]}, {"titulo": "14. Receptores colinérgicos em tabela", "pontos": [{"t": "M1 a M5 e nicotínicos", "sub": ["M1 (SNC, gânglios, células parietais gástricas): Gq → IP₃/DAG → ↑Ca²⁺; cognição e ↑ secreção gástrica.", "M2 (coração, nós SA e AV): Gi → ↓AMPc e abre canais de K⁺; ↓ frequência e ↓ condução AV.", "M3 (músculo liso, glândulas, endotélio): Gq → ↑Ca²⁺; contração do liso, ↑ secreções, vasodilatação via NO endotelial.", "M4 e M5 (SNC): Gi e Gq; modulação central.", "NN (gânglios autonômicos, medula adrenal): canal Na⁺/K⁺; despolarização ganglionar e liberação de catecolaminas.", "NM (placa motora): canal iônico; contração do músculo esquelético."]}, {"t": "Mnemônico", "sub": ["Muscarínicos ímpares (M1, M3, M5) → Gq; pares (M2, M4) → Gi.", "Muscarínicos são acoplados à proteína G (resposta mais lenta, em órgãos efetores); nicotínicos são canais iônicos (resposta rápida, em gânglios e placa motora)."]}]}, {"titulo": "15. Efeitos muscarínicos por órgão e agonistas", "pontos": [{"t": "Órgãos", "sub": ["Olho: miose, acomodação para perto, ↓ pressão intraocular.", "Coração: bradicardia e ↓ condução AV (M2).", "Vasos: vasodilatação via NO endotelial (M3) e queda da pressão.", "Brônquios: broncoconstrição e ↑ secreção.", "Trato gastrintestinal: ↑ motilidade e secreções; relaxamento de esfíncteres.", "Bexiga: contração do detrusor (favorece a micção).", "Glândulas: ↑ saliva, lágrima e suor."]}, {"t": "Agonistas", "sub": ["Diretos: betanecol (contrai detrusor; retenção urinária não obstrutiva, atonia intestinal); pilocarpina (glaucoma, xerostomia); carbacol; metacolina (teste de broncoprovocação).", "Indiretos (anticolinesterásicos): neostigmina (reversão de bloqueio neuromuscular, íleo e retenção pós-operatórios); piridostigmina (miastenia gravis); donepezila e rivastigmina (Alzheimer); fisostigmina (antídoto da intoxicação anticolinérgica; terciária, passa a barreira hematoencefálica)."]}]}, {"titulo": "16. Miastenia gravis: a ponte com imunologia", "pontos": [{"t": "Três matérias ao mesmo tempo", "sub": ["Imunologia: autoanticorpo contra o receptor nicotínico da placa motora é hipersensibilidade tipo II por bloqueio funcional.", "Clínica: fraqueza flutuante que piora com esforço, ptose e diplopia.", "Farmacologia: piridostigmina aumenta a acetilcolina na fenda e compensa o número reduzido de receptores funcionais; não elimina os autoanticorpos. Tratamento modificador: corticoide, imunossupressor ou timectomia."]}, {"t": "Crise miastênica × crise colinérgica", "sub": ["Crise miastênica: causa dose insuficiente ou piora da doença; transmissão inadequada; sinais muscarínicos ausentes; melhora com mais anticolinesterásico.", "Crise colinérgica: causa excesso de anticolinesterásico; bloqueio despolarizante por excesso de ACh; sinais muscarínicos presentes (miose, sialorreia, bradicardia, fasciculações); piora com mais anticolinesterásico."]}]}, {"titulo": "17. Antagonistas muscarínicos e síndrome anticolinérgica", "pontos": [{"t": "Atropina e a ordem de sensibilidade", "sub": ["Doses baixas secam secreções; doses crescentes causam taquicardia, midríase e cicloplegia, retenção urinária e redução da motilidade intestinal; doses altas causam agitação, delírio, alucinações e hipertermia.", "Usos: bradicardia sintomática, intoxicação por organofosforado, antissialagogo pré-anestésico.", "Outros: escopolamina (cinetose, efeitos centrais marcantes); butilescopolamina (cólicas; não atravessa a barreira hematoencefálica); ipratrópio e tiotrópio (broncodilatação na DPOC); tropicamida (midríase para exame); oxibutinina (bexiga hiperativa); biperideno (parkinsonismo)."]}, {"t": "Terciárias × quaternárias", "sub": ["Terciárias (atropina, escopolamina, biperideno, oxibutinina, fisostigmina): lipossolúveis, boa absorção oral, atravessam a barreira hematoencefálica e a placentária → efeitos centrais; cuidado na gestação.", "Quaternárias (butilescopolamina, ipratrópio, tiotrópio, neostigmina, piridostigmina, glicopirrolato): carga positiva permanente, absorção oral pobre, não atravessam → efeitos periféricos."]}, {"t": "Síndrome anticolinérgica × colinérgica", "sub": ["Anticolinérgica (bloqueio muscarínico): seco como osso (pele e mucosas secas, anidrose); vermelho como pimentão (rubor); quente como fogo (hipertermia); cego como morcego (midríase, visão turva); louco como chapeleiro (agitação, delírio). Mais taquicardia, retenção urinária e íleo. Causas: atropina, Datura (trombeteira), antidepressivos tricíclicos, anti-histamínicos de 1.ª geração. Antídoto: fisostigmina.", "Colinérgica (excesso de ACh): muscarínicos: miose, sialorreia, lacrimejamento, sudorese, broncorreia e broncoespasmo, bradicardia, vômitos, diarreia, incontinência. Nicotínicos: fasciculações, cãibras, fraqueza e paralisia (diafragma); taquicardia e hipertensão (ganglionares). Central: ansiedade, confusão, convulsões, depressão respiratória, coma. Causas: organofosforados (agrotóxicos), carbamatos (\"chumbinho\"), agentes de guerra.", "Diferencial rápido: colinérgica = miose e tudo molhado; anticolinérgica = midríase e tudo seco."]}]}, {"titulo": "18. Intoxicação por organofosforado: conduta", "pontos": [{"t": "Passos", "sub": ["Mecanismo: inibem a AChE → acúmulo de acetilcolina em todas as sinapses colinérgicas.", "(1) Descontaminar: retirar roupas, lavar a pele, equipe com EPI. (2) Via aérea e oxigênio.", "(3) Atropina, dobrando a dose até secar as secreções brônquicas; o alvo da titulação é a secreção, não a frequência cardíaca.", "(4) Pralidoxima: reativa a AChE e atua também nos efeitos nicotínicos, mas só antes do \"envelhecimento\" da enzima; por isso deve ser precoce.", "(5) Benzodiazepínico para convulsões. Carbamatos dão quadro mais curto e não envelhecem a enzima."]}]}, {"titulo": "19. Pontes com outras aulas", "pontos": [{"t": "Miastenia e o receptor", "sub": ["Piridostigmina na miastenia e a tabela de receptores (aula 5) seguem a mesma lógica: estimular ou bloquear o receptor certo."]}]}], "glossario": [{"termo": "Efeito teto", "tecnica": "Reversão de bloqueio neuromuscular", "definicao": "Limite de eficácia: aumentar a dose não aumenta o efeito, em bloqueio profundo.", "slide": 28}, {"termo": "Crise colinérgica", "tecnica": "Excesso de anticolinesterásico", "definicao": "Miose, sialorreia, bradicardia e fasciculações; piora com mais anticolinesterásico.", "slide": 26}, {"termo": "Envelhecimento da AChE", "tecnica": "Organofosforados", "definicao": "Fosforilação estável da serina; a oxima só reativa a enzima antes desse processo.", "slide": 56}, {"termo": "Síndrome anticolinérgica", "tecnica": "Toxicidade", "definicao": "Quadro de pele seca e quente, midríase, taquicardia, retenção urinária e delírio.", "slide": 38}, {"termo": "Aminas quaternárias", "tecnica": "Farmacocinética", "definicao": "Carga positiva permanente; absorção oral pobre e não atravessam a BHE.", "slide": 37}, {"termo": "Pralidoxima", "tecnica": "Antídoto", "definicao": "Oxima que reativa a AChE inibida por organofosforados, nos efeitos nicotínicos.", "slide": 55}, {"termo": "Síndrome de Sjögren (epônimo: Sjögren)", "tecnica": "Colinérgicos", "definicao": "Causa de xerostomia; a aula cita pilocarpina e cevimelina para o quadro.", "slide": 29}, {"termo": "Critérios de Beers (epônimo: Beers)", "tecnica": "Antimuscarínicos", "definicao": "Critérios que alertam contra anticolinérgicos em idosos; a aula cita a síndrome anticolinérgica.", "slide": 38}, {"termo": "Acetilcolina (ACh)", "tecnica": "Neurotransmissor", "definicao": "Neurotransmissor do parassimpático, do simpático pré-ganglionar e da placa motora. Hidrolisada pela AChE.", "slide": 5}, {"termo": "Colina acetiltransferase (ChAT)", "tecnica": "Síntese", "definicao": "Enzima que une acetil-CoA e colina para formar ACh no neurônio.", "slide": 5}, {"termo": "Transportador de colina (CHT)", "tecnica": "Captação", "definicao": "Transportador Na⁺-dependente que capta colina. Etapa limitante, bloqueada pelo hemicolínio.", "slide": 5}, {"termo": "Hemicolínio", "tecnica": "Fármaco", "definicao": "Bloqueia a captação de colina, a etapa limitante da síntese de ACh.", "slide": 5}, {"termo": "VAChT e vesamicol", "tecnica": "Armazenamento", "definicao": "VAChT leva a ACh para as vesículas. Vesamicol bloqueia esse transportador.", "slide": 5}, {"termo": "SNARE e toxina botulínica", "tecnica": "Liberação", "definicao": "Proteínas que fazem a vesícula se fundir à membrana. A toxina botulínica impede essa liberação.", "slide": 5}, {"termo": "Acetilcolinesterase (AChE)", "tecnica": "Degradação", "definicao": "Enzima que hidrolisa a ACh em colina e acetato em microssegundos. Alvo dos anticolinesterásicos.", "slide": 5}, {"termo": "Receptor muscarínico M1", "tecnica": "Receptor (Gq)", "definicao": "No SNC, gânglios e células parietais. Via Gq, com IP₃, DAG e aumento de Ca²⁺. Aumenta a secreção gástrica.", "slide": 8}, {"termo": "Receptor muscarínico M2", "tecnica": "Receptor (Gi)", "definicao": "No coração (nós SA e AV). Via Gi, com queda de AMPc e abertura de canais de K⁺. Reduz a frequência cardíaca e a condução AV.", "slide": 8}, {"termo": "Receptor muscarínico M3", "tecnica": "Receptor (Gq)", "definicao": "Em músculo liso, glândulas e endotélio. Causa contração, secreção e vasodilatação via NO.", "slide": 8}, {"termo": "Receptores M4 e M5", "tecnica": "Receptor (Gi/Gq)", "definicao": "No SNC, para modulação central. M4 é Gi; M5 é Gq.", "slide": 8}, {"termo": "Receptor nicotínico NN", "tecnica": "Receptor (canal)", "definicao": "Nos gânglios autonômicos, medula adrenal e SNC. Canal de Na⁺/K⁺ que despolariza o gânglio e libera catecolaminas.", "slide": 8}, {"termo": "Receptor nicotínico NM", "tecnica": "Receptor (canal)", "definicao": "Na placa motora do músculo esquelético. Canal que causa contração.", "slide": 8}, {"termo": "Gq, IP₃ e DAG", "tecnica": "Via de sinalização", "definicao": "Via dos receptores ímpares. IP₃ libera Ca²⁺ do retículo; DAG ativa a PKC.", "slide": 9}, {"termo": "Gi e canais de K⁺ (GIRK)", "tecnica": "Via de sinalização", "definicao": "Via dos receptores pares. Inibe a adenilato ciclase e abre canais de K⁺, causando hiperpolarização.", "slide": 11}, {"termo": "Óxido nítrico (NO)", "tecnica": "Mediador", "definicao": "Produzido pelo endotélio. Ativa a guanilato ciclase, aumenta o GMPc e causa vasodilatação.", "slide": 13}, {"termo": "Catecolaminas (dopamina, noradrenalina e adrenalina)", "tecnica": "Neurotransmissores", "definicao": "Atuam como neurotransmissores e hormônios. Dopamina: movimento e recompensa. Noradrenalina: atenção e alerta. Adrenalina: estresse.", "slide": 14}, {"termo": "Miastenia gravis", "tecnica": "Doença", "definicao": "Doença autoimune com autoanticorpos contra o receptor nicotínico da placa motora. Fraqueza que piora com esforço.", "slide": 23}, {"termo": "Piridostigmina", "tecnica": "Anticolinesterásico", "definicao": "Inibe a AChE e aumenta a ACh na junção neuromuscular. Tratamento sintomático da miastenia.", "slide": 23}, {"termo": "Neostigmina", "tecnica": "Anticolinesterásico", "definicao": "Carbamato que aumenta a ACh. Usado na reversão de bloqueadores neuromusculares e na miastenia.", "slide": 21}, {"termo": "Donepezila, galantamina e rivastigmina", "tecnica": "Anticolinesterásico", "definicao": "Inibidores da AChE usados no Alzheimer. Rivastigmina também na demência da doença de Parkinson.", "slide": 21}, {"termo": "Pilocarpina", "tecnica": "Agonista muscarínico", "definicao": "Agonista direto de M. Aumenta a secreção salivar e reduz a pressão intraocular. Usada no glaucoma e na xerostomia.", "slide": 20}, {"termo": "Betanecol", "tecnica": "Agonista muscarínico", "definicao": "Agonista muscarínico resistente à AChE. Estimula a bexiga e o intestino. Usado na atonia vesical e gastrointestinal.", "slide": 20}, {"termo": "Carbacol", "tecnica": "Agonista muscarínico", "definicao": "Agonista de receptores M e N. Resistente à AChE. Usado na miose cirúrgica e no glaucoma.", "slide": 20}, {"termo": "Metacolina", "tecnica": "Agonista muscarínico", "definicao": "Agonista M com hidrólise lenta. Usada no teste de broncoprovocação para diagnóstico de asma.", "slide": 29}, {"termo": "Cevimelina", "tecnica": "Agonista muscarínico", "definicao": "Agonista M1/M3, usado na xerostomia da síndrome de Sjögren.", "slide": 29}, {"termo": "Atropina", "tecnica": "Antagonista muscarínico", "definicao": "Antagonista muscarínico competitivo. Reverte os efeitos muscarínicos, mas não os nicotínicos. Antídoto de organofosforados e carbamatos.", "slide": 30}, {"termo": "Escopolamina", "tecnica": "Antagonista muscarínico", "definicao": "Amina terciária que atravessa a BHE. Usada na cinetose, em adesivo transdérmico.", "slide": 33}, {"termo": "Butilescopolamina (butilbrometo)", "tecnica": "Antagonista muscarínico", "definicao": "Amina quaternária que não atravessa a BHE. Usada em cólicas gastrointestinais, biliares e renais.", "slide": 33}, {"termo": "Ipratrópio e tiotrópio", "tecnica": "Antagonista muscarínico", "definicao": "Quaternários broncodilatadores. Tiotrópio é LAMA de uso diário, na DPOC.", "slide": 33}, {"termo": "Tropicamida e ciclopentolato", "tecnica": "Antagonista muscarínico", "definicao": "Usados para midríase e cicloplegia no exame oftalmológico.", "slide": 33}, {"termo": "Oxibutinina, tolterodina e solifenacina", "tecnica": "Antagonista muscarínico", "definicao": "Usados na bexiga hiperativa, com incontinência de urgência.", "slide": 33}, {"termo": "Biperideno e triexifenidil", "tecnica": "Antagonista muscarínico", "definicao": "Usados no parkinsonismo induzido por antipsicóticos e no tremor da doença de Parkinson.", "slide": 33}, {"termo": "Glicopirrolato", "tecnica": "Antagonista muscarínico", "definicao": "Quaternário antissialagogo. Associado à neostigmina para reverter bloqueadores neuromusculares.", "slide": 33}, {"termo": "Aminas terciárias e quaternárias", "tecnica": "Farmacocinética", "definicao": "Terciárias são lipossolúveis e atravessam a BHE. Quaternárias são carregadas e atuam na periferia.", "slide": 37}, {"termo": "Datura (trombeteira)", "tecnica": "Planta", "definicao": "Planta com atropina e escopolamina, causa de síndrome anticolinérgica.", "slide": 44}, {"termo": "Nicotina", "tecnica": "Agonista nicotínico", "definicao": "Ação bifásica: estimula e depois bloqueia os gânglios. Usada na reposição para cessar o tabagismo.", "slide": 40}, {"termo": "Vareniclina", "tecnica": "Agonista nicotínico", "definicao": "Agonista parcial α4β2 que reduz a fissura e a recompensa. Usada na cessação do tabagismo.", "slide": 40}, {"termo": "Succinilcolina", "tecnica": "Agonista nicotínico", "definicao": "Agonista NM que causa despolarização persistente da placa motora, com paralisia temporária.", "slide": 42}, {"termo": "Mecamilamina e trimetafano", "tecnica": "Bloqueador ganglionar", "definicao": "Bloqueiam os gânglios do simpático e do parassimpático. Uso muito restrito.", "slide": 40}, {"termo": "Butirilcolinesterase (pseudocolinesterase)", "tecnica": "Enzima", "definicao": "Enzima plasmática sintetizada no fígado. Hidrolisa succinilcolina, mivacúrio e anestésicos do tipo éster.", "slide": 48}, {"termo": "Edrofônio", "tecnica": "Anticolinesterásico", "definicao": "Inibidor reversível de ação curta (5 a 15 min). Teste diagnóstico de miastenia, no passado.", "slide": 50}, {"termo": "Fisostigmina", "tecnica": "Anticolinesterásico", "definicao": "Carbamato terciário que atravessa a BHE. Usado na intoxicação anticolinérgica com delírio.", "slide": 51}, {"termo": "Organofosforados (malation, clorpirifós, sarin, VX)", "tecnica": "Anticolinesterásico", "definicao": "Fosforilam a AChE de modo estável. Inibição irreversível após o envelhecimento da enzima.", "slide": 50}, {"termo": "Carbamatos (aldicarbe e outros)", "tecnica": "Anticolinesterásico", "definicao": "Carbamilam a AChE, com inibição de 30 min a 6 h. Aldicarbe está no chumbinho.", "slide": 50}, {"termo": "Chumbinho", "tecnica": "Exposição", "definicao": "Raticida ilegal que frequentemente contém aldicarbe. Causa comum de intoxicação no Brasil.", "slide": 53}, {"termo": "Envelhecimento da enzima (organofosforados)", "tecnica": "Conceito", "definicao": "Perda da reativação da AChE por oximas, após a fosforilação estável. Tempo é enzima.", "slide": 56}, {"termo": "Síndrome intermediária", "tecnica": "Complicação", "definicao": "Fraqueza proximal, de pares cranianos e respiratória, de 24 a 96 horas após a crise colinérgica.", "slide": 56}, {"termo": "Neuropatia tardia por organofosforado", "tecnica": "Complicação", "definicao": "Polineuropatia sensitivo-motora distal, de 1 a 3 semanas, pela esterase neurotóxica.", "slide": 56}, {"termo": "SLUDGE", "tecnica": "Mnemônico", "definicao": "Excesso muscarínico: salivação, lacrimejamento, urina, diarreia, cólica e êmese.", "slide": 30}, {"termo": "Gq e Gi (mnemônico dos receptores)", "tecnica": "Mnemônico", "definicao": "Receptores ímpares (M1, M3, M5) são Gq. Pares (M2, M4) são Gi.", "slide": 8}], "caso": {"titulo": "Caso: chá de trombeteira", "perfil": "Síndrome anticolinérgica por Datura.", "etapas": [{"titulo": "Etapa 1: síndrome", "texto": "Jovem de 22 anos, após festa e chá de trombeteira, agitado e confuso, com alucinações visuais. Pele quente, seca e avermelhada; pupilas midriáticas e pouco reativas; FC 132 bpm; temperatura 38,9 °C; bexiga palpável; ruídos hidroaéreos diminuídos.", "perguntas": [{"pergunta": "Qual é a síndrome tóxica, segundo a aula?", "alts": ["Síndrome anticolinérgica", "Síndrome colinérgica por organofosforado", "Síndrome simpatomimética por anfetamina", "Síndrome da crise miastênica", "Síndrome serotoninérgica por inibidor da MAO"], "erradas": ["Síndrome colinérgica tem miose, sialorreia e bradicardia, o oposto do quadro.", "Simpatomimético causa midríase, mas com sudorese e taquicardia típicas.", "Crise miastênica é fraqueza sem sinais muscarínicos.", "Serotoninérgica não é a síndrome descrita para trombeteira."], "justificativa": "Seco como osso, vermelho, quente, cego e louco: síndrome anticolinérgica, causada por plantas como a Datura (slide 38)."}]}, {"titulo": "Etapa 2: mecanismo e conduta", "texto": "A equipe pergunta qual é o mecanismo do quadro e qual o papel da atropina nesse caso.", "perguntas": [{"pergunta": "Qual é o mecanismo mais adequado para o quadro?", "alts": ["Bloqueio dos receptores muscarínicos pela escopolamina e atropina da planta", "Inibição da acetilcolinesterase, com excesso de ACh na sinapse", "Ativação de receptores nicotínicos, com fasciculações generalizadas", "Bloqueio de receptores beta, com bradicardia intensa", "Inibição da MAO, com acúmulo de serotonina no SNC"], "erradas": ["Inibição da AChE é o mecanismo do organofosforado, não da trombeteira.", "Ativação nicotínica causa fasciculações, que não são o quadro descrito.", "Bloqueio beta causa bradicardia, e não taquicardia com pele quente.", "Inibição da MAO não é o mecanismo da síndrome anticolinérgica."], "justificativa": "Os alcaloides da planta bloqueiam os receptores muscarínicos, como a atropina (slides 34 e 38)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um fármaco bloqueia a captação de colina na terminação colinérgica. Qual etapa do ciclo da acetilcolina fica comprometida, e por que ela é a mais importante para a síntese?", "alternativas": ["A degradação pela acetilcolinesterase, que ocorre em microssegundos e libera colina para a recaptação", "A estocagem vesicular pelo VAChT, que depende de influxo de Ca²⁺ e de proteínas SNARE na terminação", "A liberação por exocitose, que é bloqueada pela toxina botulínica e depende do potencial de ação", "A captação de colina, que é a etapa limitante da síntese de acetilcolina", "A ação no receptor muscarínico, que se torna irreversível após o bloqueio da captação de colina"], "gabarito": "D", "justificativa": "A captação de colina é a etapa limitante do ciclo, e é bloqueada pelo hemicolínio. Sem colina suficiente, a síntese de acetilcolina cai (resumo: Colinérgicos, ciclo da acetilcolina).", "tecnica": "Ciclo da acetilcolina", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um receptor colinérgico acoplado a Gi reduz a frequência cardíaca. Qual é o subtipo e o mecanismo de sinalização?", "alternativas": ["M2; Gi inibe a adenilil ciclase, reduz AMPc e abre canais de K⁺", "M3; Gq ativa a fosfolipase C, eleva IP₃ e aumenta o Ca²⁺ intracelular no miocárdio", "NN; canal iônico de Na⁺ e K⁺ que despolariza o gânglio e libera catecolaminas", "M1; Gq eleva o Ca²⁺ intracelular e aumenta a secreção gástrica de ácido clorídrico", "NM; canal iônico da placa motora que promove a contração do músculo esquelético"], "gabarito": "A", "justificativa": "M2 está no coração (nós SA e AV) e é acoplado a Gi: reduz AMPc e abre canais de K⁺, com bradicardia e menor condução AV (resumo: Colinérgicos, receptores).", "tecnica": "Receptor M2", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Por que os muscarínicos ímpares (M1, M3 e M5) se acoplam a Gq, enquanto os pares (M2 e M4) se acoplam a Gi?", "alternativas": ["Porque os ímpares são canais iônicos e os pares são receptores acoplados a proteína G, com resposta rápida", "Porque os ímpares estão apenas no SNC e os pares estão apenas nos gânglios autonômicos e na placa motora", "Porque os ímpares ativam a adenilil ciclase, e os pares inibem a fosfolipase C em todos os tecidos", "Pela regra mnemônica da aula: ímpares são Gq e pares são Gi, com resposta mais lenta em órgãos efetores", "Porque os ímpares são receptores nicotínicos, e os pares são receptores muscarínicos de resposta rápida"], "gabarito": "D", "justificativa": "Ímpares (M1, M3, M5) → Gq; pares (M2, M4) → Gi. Muscarínicos são acoplados à proteína G, com resposta mais lenta; nicotínicos são canais iônicos, com resposta rápida (resumo: Colinérgicos, mnemônico).", "tecnica": "Mnemônico muscarínico", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um paciente com glaucoma recebe pilocarpina. Qual é o efeito pupilar e por que ele reduz a pressão intraocular?", "alternativas": ["Midríase e relaxamento do músculo ciliar, o que aumenta a produção de humor aquoso no olho", "Midríase por bloqueio do esfíncter da pupila, o que retém o humor aquoso na câmara anterior", "Miose e contração do músculo ciliar, o que facilita a drenagem do humor aquoso", "Miose e aumento da produção de humor aquoso, o que eleva a pressão intraocular nos pacientes", "Nenhum efeito pupilar, porque a pilocarpina atua somente sobre a retina e não sobre o cristalino"], "gabarito": "C", "justificativa": "Pilocarpina é agonista muscarínico direto. Causa miose e contração do músculo ciliar, o que facilita a drenagem do humor aquoso e reduz a pressão intraocular (resumo: Colinérgicos, agonistas diretos).", "tecnica": "Pilocarpina e glaucoma", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente com íleo pós-operatório recebe neostigmina. Qual é o mecanismo e por que o efeito é potencializado em toda sinapse colinérgica?", "alternativas": ["Ativa o receptor muscarínico diretamente, e a acetilcolina é liberada em maior quantidade pelo neurônio", "Inibe a acetilcolinesterase, e a acetilcolina permanece mais tempo na fenda sináptica", "Bloqueia o receptor nicotínico da placa motora, o que impede a degradação da acetilcolina na fenda", "Estimula a captação de colina na terminação, o que aumenta a síntese de acetilcolina no neurônio", "Bloqueia a liberação de acetilcolina pelo neurônio, o que reduz a atividade do intestino em todas as sinapses"], "gabarito": "B", "justificativa": "Neostigmina é anticolinesterásico indireto: inibe a AChE, a acetilcolina permanece na fenda e potencializa todas as sinapses colinérgicas (resumo: Colinérgicos, agonistas indiretos).", "tecnica": "Anticolinesterásicos", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com Alzheimer recebe donepezila. Qual é o mecanismo de ação e por que o efeito é esperado no SNC?", "alternativas": ["Ativa o receptor nicotínico da placa motora, o que melhora a memória por contração muscular", "Inibe a acetilcolinesterase no SNC, aumentando a acetilcolina disponível nas sinapses", "Bloqueia o receptor muscarínico M1 no SNC, o que reduz a produção de acetilcolina pelo neurônio", "Bloqueia a liberação de dopamina no estriado, o que reduz a rigidez muscular e a bradicinesia", "Inibe a calcineurina nos neurônios colinérgicos, o que impede a degradação do receptor muscarínico"], "gabarito": "B", "justificativa": "Donepezila é anticolinesterásico que inibe a AChE no SNC, aumentando a acetilcolina disponível. Esse é o mecanismo esperado no Alzheimer (resumo: Colinérgicos, agonistas indiretos).", "tecnica": "Donepezila e Alzheimer", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um paciente com intoxicação por organofosforado tem miose, sialorreia, bradicardia e fasciculações. Qual é o diagnóstico e qual o antídoto específico?", "alternativas": ["Síndrome colinérgica; atropina para o efeito muscarínico e pralidoxima para reativar a AChE", "Síndrome anticolinérgica; fisostigmina para reverter o bloqueio muscarínico no SNC e na periferia", "Crise miastênica; piridostigmina em dose maior, para aumentar a acetilcolina na placa motora", "Síndrome anticolinérgica; atropina em dose alta, para secar as secreções e reverter a miose", "Crise colinérgica da miastenia; corticoide em dose alta, para inibir a produção de anticorpos"], "gabarito": "A", "justificativa": "Miose, sialorreia, bradicardia e fasciculações indicam síndrome colinérgica. Atropina trata o efeito muscarínico; pralidoxima reativa a AChE, se precoce (resumo: Colinérgicos, intoxicação por organofosforado).", "tecnica": "Organofosforado", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Na intoxicação por organofosforado, por que a pralidoxima precisa ser administrada precocemente?", "alternativas": ["Porque a pralidoxima perde a eficácia após algumas horas, mesmo que a AChE ainda esteja ativa no sangue", "Porque o organofosforado é metabolizado pelo fígado em poucas horas e a pralidoxima precisa agir antes", "Porque a pralidoxima só atua sobre o receptor muscarínico, que se dessensibiliza após algumas horas", "Porque a AChE envelhece e a reativação só funciona antes desse momento", "Porque a pralidoxima é um anticolinérgico que só é eficaz antes da síntese de acetilcolina no neurônio"], "gabarito": "D", "justificativa": "Pralidoxima reativa a AChE, mas só antes do envelhecimento da enzima. Por isso deve ser precoce. Carbamatos não envelhecem a enzima e dão quadro mais curto (resumo: Colinérgicos, intoxicação).", "tecnica": "Pralidoxima", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Na intoxicação por organofosforado, a atropina é titulada até um alvo específico. Qual é esse alvo?", "alternativas": ["Frequência cardíaca acima de 100 batimentos por minuto, que indica reversão do quadro bradicárdico", "Pupila em midríase máxima, que indica bloqueio completo dos receptores muscarínicos no olho", "Secreções brônquicas secas; a frequência cardíaca não é o alvo da titulação", "Pressão arterial sistólica acima de 140 mmHg, que indica reversão da hipotensão causada pela intoxicação", "Concentração plasmática de acetilcolina abaixo de 1 mmol/L, que indica remoção do organofosforado"], "gabarito": "C", "justificativa": "Atropina é dobrada até secar as secreções brônquicas, e esse é o alvo da titulação, não a frequência cardíaca (resumo: Colinérgicos, intoxicação por organofosforado).", "tecnica": "Titulação da atropina", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um paciente recebe atropina e apresenta boca seca, pele quente e vermelha, midríase e delírio. Qual é a síndrome e qual antídoto é indicado?", "alternativas": ["Síndrome colinérgica; atropina em dose maior, para bloquear o excesso de acetilcolina no SNC", "Crise miastênica; piridostigmina, que é quaternária e não atravessa a barreira hematoencefálica", "Síndrome anticolinérgica; fisostigmina, que é terciária e atravessa a barreira hematoencefálica", "Síndrome anticolinérgica; pralidoxima, que reativa a AChE e reverte o bloqueio muscarínico periférico", "Síndrome colinérgica; neostigmina, que é quaternária e reverte a midríase sem efeito central algum"], "gabarito": "C", "justificativa": "Seco como osso, vermelho como pimentão, quente como fogo, cego como morcego e louco como chapeleiro: síndrome anticolinérgica. Antídoto: fisostigmina, terciária que atravessa a barreira hematoencefálica (resumo: Colinérgicos, síndrome anticolinérgica).", "tecnica": "Síndrome anticolinérgica", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Por que a butilescopolamina é usada em cólicas abdominais sem causar delírio, enquanto a atropina pode causar confusão?", "alternativas": ["Porque é terciária e atravessa a barreira hematoencefálica; a atropina é quaternária e fica restrita ao intestino", "Porque é quaternária e não atravessa a barreira hematoencefálica; a atropina é terciária e atravessa", "Porque bloqueia o receptor nicotínico do gânglio, sem afetar o receptor muscarínico central em nenhum caso", "Porque atua apenas na placa motora, e a atropina atua somente no sistema nervoso autônomo simpático", "Porque é agonista muscarínico, e a atropina é antagonista nicotínico com efeito central acentuado"], "gabarito": "B", "justificativa": "Aminas quaternárias (butilescopolamina, ipratrópio, tiotrópio) têm carga permanente e não atravessam a barreira hematoencefálica. Aminas terciárias (atropina, escopolamina) atravessam (resumo: Colinérgicos, terciárias × quaternárias).", "tecnica": "Terciárias × quaternárias", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um paciente com miastenia gravis piora após aumento da dose de piridostigmina, com sialorreia, miose e fasciculações. O que está acontecendo?", "alternativas": ["Crise miastênica, por dose insuficiente de piridostigmina, com piora da fraqueza muscular", "Crise anticolinérgica, por bloqueio de receptores muscarínicos pelo excesso de piridostigmina", "Remissão da miastenia, porque a sialorreia e a miose indicam recuperação da junção neuromuscular", "Infecção do sistema nervoso central, causada pela própria piridostigmina em dose alta de ataque", "Crise colinérgica, por excesso de anticolinesterásico e acetilcolina em excesso"], "gabarito": "E", "justificativa": "Excesso de anticolinesterásico causa crise colinérgica: sinais muscarínicos presentes e piora com mais fármaco. Na crise miastênica, a causa é dose insuficiente, e os sinais muscarínicos estão ausentes (resumo: Colinérgicos, crises).", "tecnica": "Crise colinérgica × miastênica", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Por que a piridostigmina melhora a fraqueza da miastenia gravis, mas não elimina o autoanticorpo que causa a doença?", "alternativas": ["Porque destrói o autoanticorpo no sangue, mas precisa ser combinada com a toxina botulínica para a cura", "Porque bloqueia a produção de autoanticorpos pelos plasmócitos, sendo um tratamento modificador da doença", "Porque ativa o complemento na junção neuromuscular, o que destrói os receptores nicotínicos bloqueados", "Porque inibe a calcineurina nos linfócitos B, eliminando permanentemente a fonte do autoanticorpo circulante", "Porque aumenta a acetilcolina na fenda, compensando receptores funcionais, mas não remove o autoanticorpo"], "gabarito": "E", "justificativa": "Piridostigmina aumenta a acetilcolina e compensa o número reduzido de receptores. Não elimina o autoanticorpo; o tratamento modificador é corticoide, imunossupressor ou timectomia (resumo: Colinérgicos, miastenia gravis).", "tecnica": "Miastenia e tratamento", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um fármaco é descrito como agonista muscarínico direto usado para contrair o detrusor. Qual é o nome e a indicação?", "alternativas": ["Atropina; retenção urinária por bloqueio do detrusor e relaxamento da bexiga", "Neostigmina; miastenia gravis por bloqueio da acetilcolinesterase na placa motora", "Ipratrópio; broncodilatação na DPOC por bloqueio dos receptores nicotínicos", "Fisostigmina; antídoto de intoxicação por fármacos com efeito anticolinérgico sistêmico", "Betanecol; retenção urinária não obstrutiva e atonia intestinal"], "gabarito": "E", "justificativa": "Betanecol é agonista muscarínico direto que contrai o detrusor. Indicação: retenção urinária não obstrutiva e atonia gastrintestinal (resumo: Colinérgicos, agonistas diretos).", "tecnica": "Betanecol", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um paciente com cinetose recebe escopolamina. Por que esse fármaco tem efeito central marcante, e qual classe ele representa?", "alternativas": ["Amina terciária, lipossolúvel, atravessa a barreira hematoencefálica; antagonista muscarínico", "Porque é amina quaternária, que se concentra no SNC; é agonista muscarínico de ação central", "Porque é anticolinesterásico, que aumenta a acetilcolina no SNC e reduz a náusea por ação central", "Porque é antagonista nicotínico ganglionar, que bloqueia a transmissão no gânglio vestibular", "Porque é agonista β2 adrenérgico, que reduz a náusea por ação no vestíbulo e no centro do vômito"], "gabarito": "A", "justificativa": "Escopolamina é amina terciária, lipossolúvel, que atravessa a barreira hematoencefálica e tem efeito central marcante. É antagonista muscarínico (resumo: Colinérgicos, antagonistas muscarínicos).", "tecnica": "Escopolamina", "slide": null}], "id": "farma-gilmar-04", "titulo": "Aula 4", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-05"] = {"subtitulo": "Adrenérgicos e antiadrenérgicos: agonistas, bloqueadores e receptores", "pdf": "pdf/gilmar/aula-05.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 5 · Adrenérgicos e Antiadrenérgicos (Prof. Dr. Gilmar S. Erzinger)", "Brunton, Chabner e Knollmann (Goodman & Gilman, 12ª ed.); Aula 07 de Farmacologia Veterinária (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Efeitos dos agonistas por órgão (slide 29)", "colunas": ["Órgão / tecido", "Receptor", "Efeito da estimulação"], "linhas": [["Coração (nós SA/AV, miocárdio)", "β1", "↑ automatismo, ↑ condução, ↑ contratilidade"], ["Músculo liso vascular", "α1 / β2", "Vasoconstrição (α1); vasodilatação no músculo esquelético (β2)"], ["Brônquios", "β2", "Broncodilatação"], ["Trato gastrintestinal", "α2 / β2", "↓ motilidade; contração dos esfíncteres"], ["Bexiga", "β2-3 / α1", "Relaxa o detrusor; contrai o esfíncter (retenção)"], ["Rim", "β1", "↑ liberação de renina"], ["Fígado e músculo esquelético", "β2 / α1", "Glicogenólise, gliconeogênese, captação de K⁺, tremor"], ["Tecido adiposo", "β3", "Lipólise"], ["Útero", "β2", "Relaxamento (varia com espécie e fase gestacional)"], ["Olho (músculo radial da íris)", "α1", "Midríase"]]}, "resumo": [{"titulo": "1. Bases do sistema adrenérgico", "pontos": [{"t": "O que os agonistas imitam", "sub": ["Agonistas adrenérgicos produzem ação semelhante à estimulação simpática, a resposta de luta ou fuga. Olho: α1 causa midríase. Brônquios: β2 causa broncodilatação. Coração: β1 aumenta frequência e força. Fígado: β2 e α1 causam glicogenólise e gliconeogênese. Rim: β1 libera renina. Glândulas salivares: α1 inibe a secreção aquosa (slide 4)."]}, {"t": "Via simpática e medula adrenal", "sub": ["A fibra pré-ganglionar libera ACh em receptor nicotínico. A pós-ganglionar libera NA no órgão-alvo. A medula adrenal lança adrenalina e NA direto no sangue. Por isso o efeito simpático é amplo e sistêmico (slide 5)."]}, {"t": "Síntese, liberação e destino da NA", "sub": ["Síntese: tirosina → DOPA → dopamina. A dopamina entra na vesícula pelo VMAT e vira NA. A reserpina bloqueia o VMAT (slide 6).", "Liberação por influxo de Ca²⁺ e exocitose. A NA age nos receptores pós-sinápticos e nos pré-sinápticos α2. A recaptação pelo NET é bloqueada pela cocaína. A degradação é feita por MAO e COMT (slide 6)."]}, {"t": "Receptores e vias de sinalização", "sub": ["α1: Gq, com PLC e IP₃/DAG, que eleva o Ca²⁺. Potência NA ≥ adrenalina. Está na maioria dos tecidos-alvo simpáticos, como músculo liso de vasos, esfíncteres e íris (slides 7 e 10).", "α2: Gi, que inibe a adenilil ciclase e reduz o AMPc. Está nas terminações pré-sinápticas, SNC, TGI, pâncreas e plaquetas (slide 7).", "β1, β2 e β3: Gs, que ativa a adenilil ciclase e eleva o AMPc. β1 está no coração e rim; β2 no músculo liso brônquico e vascular; β3 no tecido adiposo e na bexiga (slide 7).", "D1: Gs, que eleva o AMPc e causa vasodilatação renal, mesentérica e coronária (slide 7)."]}]}, {"titulo": "2. Classificação dos fármacos adrenérgicos", "pontos": [{"t": "Agonistas: ação direta, indireta e mista", "sub": ["Ação direta: atuam no receptor. Exemplos: fenilefrina (α1), clonidina e xilazina (α2), dobutamina (β1), terbutalina (β2). Não seletivos: adrenalina, NA e isoproterenol (slide 13).", "Ação indireta: aumentam a NA na fenda. Liberação: anfetamina e tiramina. Bloqueio da captação: cocaína. Inibidor da MAO: selegilina. Inibidor da COMT: entacapona (slide 13).", "Ação mista: liberam NA e ativam receptores diretamente, como efedrina e pseudoefedrina (slides 13 e 17)."]}, {"t": "Catecolaminas × não catecólicas", "sub": ["Catecolaminas (adrenalina, NA, dopamina, dobutamina, isoproterenol): início rápido e duração curta. São inativadas no TGI e no fígado, por isso são dadas IV em emergências (slide 16).", "Não catecólicas (fenilefrina, efedrina, anfetamina, salbutamol, terbutalina): são maus substratos da COMT e de muitas MAO, com duração maior. Podem ser dadas por via oral ou inalatória (slide 16)."]}, {"t": "Antagonistas", "sub": ["α-bloqueadores: não seletivos (fenoxibenzamina, fentolamina), α1-seletivos (prazosina, terazosina, doxazosina, tansulosina) e α2-seletivos (atipamezol, ioimbina). Fenoxibenzamina é a exceção, com ligação covalente e irreversível (slides 37 e 38).", "β-bloqueadores: 1ª geração não seletiva (propranolol, nadolol, timolol); 2ª geração β1-seletiva (atenolol, metoprolol, esmolol); 3ª geração vasodilatadora (carvedilol e labetalol, com bloqueio α1 extra; nebivolol, via NO) (slide 37).", "Depletor de NA: reserpina, que age no neurônio e não no receptor (slide 13)."]}]}, {"titulo": "3. Ação indireta e mista: anfetamina, cocaína e efedrina", "pontos": [{"t": "Mecanismos", "sub": ["Anfetamina entra pelo NET e desloca a NA das vesículas. O NET passa a funcionar ao contrário, e a NA sai para a fenda. Causa aumento da PAS e efeitos centrais, como euforia e insônia. A resposta é abolida pela reserpina (slide 18).", "Cocaína bloqueia o NET, e a NA liberada fica mais tempo na fenda. Também é anestésico local (slide 18).", "Efedrina libera NA e inibe a recaptação. Em doses altas ativa α e β diretamente. Tem broncodilatação menos potente e mais lenta que a da adrenalina. Usada na incontinência urinária em cães (slide 18)."]}]}, {"titulo": "4. Agonistas de uso clínico", "pontos": [{"t": "Adrenalina", "sub": ["Efeitos: inotrópica e cronotrópica positiva (β1), vasopressor potente por vasoconstrição (α1), vasodilatação na musculatura esquelética (β2) e broncodilatação (β2) (slide 21).", "Usos: anafilaxia e reações alérgicas graves, como fármaco de escolha; parada cardiorrespiratória; prolonga a ação de anestésicos locais; hemostático tópico (slide 21).", "Efeitos adversos: taquicardia, arritmias, fibrilação ventricular, aumento do consumo de O₂ pelo miocárdio e crise hipertensiva (slide 21)."]}, {"t": "Noradrenalina e isoproterenol", "sub": ["Noradrenalina: vasoconstrição intensa, com aumento da PAS e PAD. Causa bradicardia reflexa. Usada em hipotensão grave e choque vasodilatador, após reposição volêmica. Vasoconstrição renal e necrose se extravasar (slide 22).", "Isoproterenol: agonista β não seletivo. Causa taquicardia e vasodilatação β2. Usado em bradicardia severa e bloqueio AV, incluindo crises de Adams-Stokes, e na broncodilatação (slide 22)."]}, {"t": "Dopamina e dobutamina", "sub": ["Dopamina muda de efeito com a dose. Abaixo de 2 µg/kg/min: D1, com vasodilatação renal e aumento da filtração glomerular. De 2 a 10 µg/kg/min: β1, com inotropismo positivo. Acima de 10 µg/kg/min: α1, com vasoconstrição e perda do benefício renal (slide 24).", "Dobutamina: β1, com inotropismo de curto prazo e pouco efeito cronotrópico. Faixa usual de 2,5 a 10 µg/kg/min. Usada em choque e ICC descompensada. É ineficaz após betabloqueio e tem tolerância em infusões longas (slide 25)."]}, {"t": "Agonistas β2 e α1", "sub": ["Salbutamol, terbutalina, salmeterol, formoterol e clembuterol são broncodilatadores. Inibem a liberação de histamina e leucotrienos pelos mastócitos. Usos: asma felina, bronquite crônica e ORVA equina. Tocólise: terbutalina, ritodrina e clembuterol. Efeitos: tremor e taquicardia (slide 26).", "Fenilefrina: vasoconstrição sem estimular o coração. Não é inativada pela COMT, então o efeito dura mais. Causa bradicardia reflexa. Imidazolinas tópicas (nafazolina, oximetazolina, xilometazolina) causam congestão de rebote com uso crônico (slide 27)."]}, {"t": "Agonistas α2 e contenção", "sub": ["Atuam centralmente, com sedação, analgesia e relaxamento muscular. Reduzem o tônus simpático, com bradicardia e hipotensão. Uso veterinário: xilazina, detomidina, romifidina, medetomidina e dexmedetomidina. Clonidina e metildopa são usadas em hipertensão humana (slide 28).", "Xilazina é emética em gatos. Os efeitos são reversíveis com antagonistas α2: ioimbina, tolazolina e atipamezol (slide 28)."]}]}, {"titulo": "5. Efeitos por órgão", "pontos": [{"t": "Quem responde a cada receptor", "sub": ["Coração: β1 aumenta automatismo, condução e contratilidade. Músculo liso vascular: α1 vasoconstrição; β2 vasodilatação no músculo esquelético (slide 29).", "Brônquios: β2 broncodilatação. TGI: α2 e β2 diminuem a motilidade e contraem esfíncteres. Bexiga: β2-3 relaxam o detrusor e α1 contrai o esfíncter, causando retenção (slide 29).", "Rim: β1 libera renina. Fígado e músculo esquelético: β2 e α1 causam glicogenólise e tremor. Tecido adiposo: β3 causa lipólise. Útero: β2 relaxa, com variação por espécie. Íris: α1 causa midríase (slide 29)."]}]}, {"titulo": "6. Efeitos adversos e usos", "pontos": [{"t": "Riscos da classe", "sub": ["Taquicardia excessiva pode levar a fibrilação ventricular. Crises hipertensivas, e isquemia ou necrose miocárdica (slide 34).", "Efeitos característicos: adrenalina causa tremor, ansiedade, cefaleia pulsátil e palidez. Dopamina causa náuseas, vômitos e arritmias. Isoproterenol causa taquicardia e rubor. Anfetamina causa agitação, insônia e surtos psicóticos. Clonidina causa sedação e boca seca (slide 34)."]}, {"t": "Usos terapêuticos", "sub": ["Parada cardíaca: adrenalina. Choque: noradrenalina, dopamina, dobutamina e fenilefrina. ICC: dobutamina e dopamina. Anafilaxia: adrenalina. Asma: salbutamol, terbutalina e clembuterol. Contenção: xilazina, detomidina e medetomidina. Descongestão e oftalmologia: imidazolinas e fenilefrina (slide 31)."]}]}, {"titulo": "7. Antagonistas adrenérgicos", "pontos": [{"t": "α-bloqueadores", "sub": ["Bloqueio α1 nos vasos reduz o tônus simpático vascular, a resistência periférica e a PA. Causa taquicardia reflexa e hipotensão postural. A intensidade depende do tônus simpático no momento da administração (slide 40).", "Reversão da adrenalina: após α-bloqueio, a adrenalina passa a baixar a PA, porque sobra só a vasodilatação β2 (slide 40).", "Usos: feocromocitoma, vasoespasmo, hipertensão e isquemia visceral no choque. Em animais, prazosina e fenoxibenzamina relaxam o esfíncter uretral em obstruções funcionais de cães e gatos (slide 40)."]}, {"t": "Antagonistas α2 e reversão", "sub": ["Atipamezol é o antagonista α2 mais seletivo, com cerca de 8.500:1 para α2 sobre α1. Reverte medetomidina e dexmedetomidina. Ioimbina reverte xilazina. Tolazolina reverte xilazina em ruminantes e equinos e também bloqueia α1 (slide 41).", "Ao reverter, retira-se também a analgesia. Por isso, planeje analgesia alternativa antes da reversão (slide 41)."]}, {"t": "β-bloqueadores", "sub": ["Todos são antagonistas competitivos. Não seletivos bloqueiam β1 e β2; cardiosseletivos bloqueiam β1. Pindolol e acebutolol são agonistas parciais (ASI). Nomes terminam em -olol, exceto labetalol e carvedilol (slide 42).", "Efeitos: reduzem FC, contratilidade e condução AV, e a renina. Não causam hipotensão postural, porque os receptores α seguem funcionais. Reduzem a produção de humor aquoso (slide 42).", "Cuidados: asma e doença obstrutiva (preferir β1-seletivos); ICC descompensada, bradicardia e bloqueio AV; mascaram hipoglicemia em diabéticos; não suspender de forma abrupta, pelo efeito rebote (slide 42)."]}, {"t": "Betabloqueadores na clínica", "sub": ["Propranolol: hipertensão, arritmias, hipertireoidismo e angina. Timolol: glaucoma tópico e hipertensão. Atenolol e metoprolol: hipertensão, angina, infarto e ICC. Esmolol: arritmias agudas IV, de ação ultracurta, porque é um éster hidrolisado no sangue (slides 43 e 46).", "Na veterinária: atenolol e propranolol em gatos com cardiomiopatia hipertrófica; controle da taquicardia no hipertireoidismo felino; taquiarritmias em cães e gatos; timolol tópico no glaucoma canino (slide 43)."]}, {"t": "β-bloqueadores vasodilatadores e uso oftálmico", "sub": ["Carvedilol e labetalol: bloqueio α1 adicional. Nebivolol: aumenta o NO. Carvedilol também é antioxidante (slide 48).", "No glaucoma: timolol reduz a produção de humor aquoso. Brimonidina (α2 tópico) reduz a produção e aumenta a drenagem. A absorção sistêmica pode causar bradicardia e broncoespasmo (slide 49)."]}, {"t": "Reserpina", "sub": ["Bloqueia o VMAT. NA, dopamina e serotonina ficam no citoplasma e são degradadas pela MAO. Causa depleção de aminas e função simpática bloqueada. Início lento, efeito longo, persistindo dias após a suspensão. Foi substituída na hipertensão por fármacos com menos efeitos adversos (slide 50)."]}]}, {"titulo": "8. Posologia veterinária dos antagonistas (slide 51)", "pontos": [{"t": "Doses citadas", "sub": ["Fenoxibenzamina em gatos: 2,5 mg, aumentando até 10 mg VO a cada 24 h. Prazosina em cães e gatos: 0,5 a 2,0 mg VO a cada 8 a 12 h.", "Ioimbina IV: cães 0,11 mg/kg; gatos 0,5 mg/kg; cavalos 0,1 mg/kg. Tolazolina em gatos: 2 mg/kg IV.", "Propranolol VO: cães 0,2 a 1,0 mg/kg a cada 8 h; gatos 0,4 a 1,2 mg/kg a cada 8 a 12 h. Ergotamina em cães e gatos: 0,02 mg/kg IM ou VO a cada 8 h. Ergonovina: 1 a 3 mg em vacas; 0,4 a 1,0 mg em ovelhas, cabras e porcas."]}]}, {"titulo": "9. Síntese e pontos-chave", "pontos": [{"t": "Para levar da aula", "sub": ["O receptor define o efeito: α1 contrai músculo liso; β1 acelera e fortalece o coração; β2 relaxa; α2 inibe a liberação de NA e causa sedação (slide 54).", "Catecolaminas agem rápido e por pouco tempo, dadas IV. Não catecólicas duram mais e funcionam por via oral ou inalatória (slide 54).", "A dopamina muda de efeito com a dose: D1, depois β1, depois α1 (slide 54).", "Na veterinária, agonistas α2 e seus antagonistas formam o par de sedação e reversão mais usado (slide 54).", "Betabloqueadores reduzem FC sem hipotensão postural. Evitar em broncopatas e na ICC descompensada (slide 54)."]}]}, {"titulo": "10. Receptores adrenérgicos em tabela (slide marcado como prova)", "pontos": [{"t": "Receptores", "sub": ["α1: Gq → PLC → ↑IP₃ e DAG → ↑Ca²⁺; músculo liso vascular, esfíncteres, íris (músculo radial); NA ≥ A.", "α2: Gi → ↓adenilil ciclase → ↓AMPc; terminações pré-sinápticas (autorreceptor), SNC, TGI, plaquetas; A > NA.", "β1: Gs → ↑AMPc → PKA; coração, rim (renina), adipócitos; NA = A.", "β2: Gs → ↑AMPc → PKA; músculo liso brônquico, vascular do músculo esquelético, uterino, fígado; A > NA.", "β3: Gs → ↑AMPc; tecido adiposo (lipólise), detrusor; NA = A.", "D1: Gs → ↑AMPc; vasos renais, mesentéricos e coronários; dopamina."]}, {"t": "Tabela reproduzida (slide marcado como prova)", "sub": ["Coração (nós SA/AV, miocárdio): β1 → ↑ automatismo, ↑ condução, ↑ contratilidade.", "Músculo liso vascular: α1 / β2 → vasoconstrição (α1); vasodilatação no músculo esquelético (β2).", "Brônquios: β2 → broncodilatação.", "Trato gastrintestinal: α2 / β2 → ↓ motilidade; contração dos esfíncteres.", "Bexiga: β2-3 / α1 → relaxa o detrusor; contrai o esfíncter (retenção).", "Rim: β1 → ↑ liberação de renina.", "Fígado e músculo esquelético: β2 / α1 → glicogenólise, gliconeogênese, captação de K⁺, tremor.", "Tecido adiposo: β3 → lipólise.", "Útero: β2 → relaxamento.", "Olho (músculo radial da íris): α1 → midríase."]}, {"t": "Como memorizar sem decorar", "sub": ["α1 contrai músculo liso (vaso, esfíncter, íris), exceto o TGI, que relaxa.", "β1 é o coração e a renina no rim (\"β1 = 1 coração, 1 rim\").", "β2 relaxa músculo liso (brônquio, útero, vaso do esquelético) e mobiliza energia (glicogenólise, tremor).", "α2 é o freio pré-sináptico: inibe a própria liberação de noradrenalina. β3 é o adipócito.", "Comparação com colinérgicos: onde o simpático relaxa, o parassimpático contrai (brônquio, TGI, detrusor, pupila)."]}]}, {"titulo": "11. Agonistas diretos, indiretos e mistos", "pontos": [{"t": "Modo de ação", "sub": ["Diretos: fenilefrina (α1), clonidina (α2), dobutamina (β1), salbutamol (β2); não seletivos: adrenalina, noradrenalina, isoproterenol.", "Indiretos (↑ noradrenalina na fenda): anfetamina (entra pelo NET, desloca a NA das vesículas e inverte o transportador); cocaína (bloqueia a recaptação pelo NET); inibidores de MAO e de COMT.", "Mistos (liberam NA e ativam receptores): efedrina, pseudoefedrina."]}, {"t": "Catecolaminas × não catecólicas", "sub": ["Catecolaminas (adrenalina, noradrenalina, dopamina, dobutamina, isoproterenol): início rápido, duração curta, degradadas por MAO e COMT, não funcionam por via oral, penetram pouco no SNC → infusão IV em emergências.", "Não catecólicas (fenilefrina, efedrina, salbutamol, anfetamina): maus substratos das enzimas, duram mais, podem ser orais ou inalatórias, algumas atingem o SNC."]}]}, {"titulo": "12. Agonistas de uso clínico: efeitos e pegadinhas", "pontos": [{"t": "Adrenalina e noradrenalina", "sub": ["Adrenalina (α1, α2, β1, β2): inotrópica e cronotrópica positiva; vasoconstrição; broncodilatação potente. Uso: anafilaxia (fármaco de escolha) e parada cardiorrespiratória.", "Noradrenalina (α1, α2, β1): vasoconstrição intensa; bradicardia reflexa à elevação da PA. Uso: choque vasodilatador (séptico), após reposição volêmica."]}, {"t": "Dopamina e dobutamina", "sub": ["Dopamina dose-dependente: D1 em dose baixa (vasodilatação renal) → β1 em dose intermediária (inotropismo) → α1 em dose alta (vasoconstrição). Uso: insuficiência cardíaca grave, choque.", "Dobutamina (β1): ↑ força de contração com pouco efeito cronotrópico. Uso: choque cardiogênico e ICC descompensada."]}, {"t": "Agonistas β2 e fenilefrina", "sub": ["Agonistas β2: broncodilatação e tocólise. Adversos: tremor, taquicardia, hipocalemia. Curta: salbutamol, terbutalina. Longa: salmeterol, formoterol.", "Fenilefrina (α1): vasoconstrição sem estimular o coração; bradicardia reflexa. Uso: hipotensão, descongestionante, midriático."]}, {"t": "Pegadinhas", "sub": ["A dopamina muda de receptor conforme a dose (D1 → β1 → α1); em dose alta perde-se o benefício renal.", "Fenilefrina causa bradicardia reflexa: não age no coração; a queda da frequência é resposta barorreflexa ao aumento da pressão. Confundir efeito direto com reflexo é distrator clássico.", "Uso contínuo de descongestionante tópico leva a congestão de rebote por dessensibilização dos receptores.", "Clonidina e metildopa (α2 central): ↓ tônus simpático → ↓ PA; sedação, boca seca. Uso: hipertensão."]}]}, {"titulo": "13. Antagonistas adrenérgicos: classes em detalhe", "pontos": [{"t": "Classes", "sub": ["α não seletivos: fenoxibenzamina (irreversível, ligação covalente) e fentolamina. Uso: feocromocitoma, vasoespasmo. Reversão da adrenalina: após α-bloqueio, a adrenalina passa a baixar a PA, porque resta só a vasodilatação β2.", "α1 seletivos (terminam em \"-zosina\"): prazosina, doxazosina, terazosina; tansulosina na hiperplasia prostática. ↓ resistência periférica → ↓ PA; taquicardia reflexa e hipotensão postural.", "β de 1.ª geração não seletivos: propranolol, nadolol, timolol, pindolol, sotalol. Bloqueiam β1 e β2 → risco de broncoconstrição. Timolol tópico no glaucoma (↓ produção de humor aquoso).", "β de 2.ª geração β1 seletivos: atenolol, metoprolol, esmolol (ultracurto), bisoprolol. Poupam os brônquios; preferíveis em asma e DPOC.", "β de 3.ª geração vasodilatadores: carvedilol e labetalol (bloqueio α1 adicional); nebivolol (via NO). Nomes em \"-olol\", exceto labetalol e carvedilol.", "Depletor de noradrenalina: reserpina bloqueia o VMAT → a NA não entra na vesícula e é degradada pela MAO. Age no neurônio, não no receptor; abole a resposta a simpatomiméticos indiretos."]}, {"t": "Atenção para a prova: betabloqueadores", "sub": ["Efeitos: ↓ frequência, ↓ contratilidade, ↓ condução AV, ↓ renina → ↓ PA. Não causam hipotensão postural, porque os receptores α continuam funcionais.", "Cuidados: asma e DPOC (preferir β1 seletivos); ICC descompensada; bradicardia e bloqueio AV; mascaram os sinais adrenérgicos da hipoglicemia no diabético.", "Nunca suspender abruptamente: o efeito rebote decorre da hipersensibilidade dos receptores regulados para cima."]}]}, {"titulo": "14. Pontes com Imunologia e Microbiologia", "pontos": [{"t": "Anafilaxia e choque séptico", "sub": ["Adrenalina como antagonista fisiológico na anafilaxia (aula 7 de Imunologia): vasoconstrição α1 e broncodilatação β2.", "Noradrenalina no choque séptico: a endotoxina (LPS) de Gram-negativas ativa TNF, IL-1 e IL-6 e leva a vasodilatação; ver aula 6 e Microbiologia."]}]}], "glossario": [{"termo": "Gq / Gs / Gi", "tecnica": "Vias de sinalização", "definicao": "Proteínas G que ativam fosfolipase C (Gq), ativam adenilil ciclase (Gs) ou inibem a adenilil ciclase (Gi).", "slide": 10}, {"termo": "Dopamina em dose baixa (D1)", "tecnica": "Dose-dependência", "definicao": "Vasodilatação renal, mesentérica e coronária, com aumento de fluxo e natriurese.", "slide": 24}, {"termo": "Catecolaminas", "tecnica": "Classificação", "definicao": "Adrenalina, noradrenalina, dopamina, dobutamina e isoproterenol; polares, de ação rápida e curta.", "slide": 16}, {"termo": "Efedrina", "tecnica": "Ação mista", "definicao": "Libera NA, inibe sua recaptação e ativa α e β diretamente em doses altas; não é catecol.", "slide": 18}, {"termo": "NET", "tecnica": "Recaptação", "definicao": "Transportador de noradrenalina; alvo da cocaína, que mantém a NA na fenda.", "slide": 18}, {"termo": "VMAT", "tecnica": "Armazenamento", "definicao": "Transportador vesicular; alvo da reserpina, que deixa a NA no citoplasma.", "slide": 50}, {"termo": "Crise de Adams-Stokes (epônimo: Adams-Stokes)", "tecnica": "Isoproterenol", "definicao": "Crise de bradicardia severa ou bloqueio cardíaco; o isoproterenol é citado como suporte temporário.", "slide": 22}, {"termo": "α1 (alfa-1)", "tecnica": "Receptor (Gq)", "definicao": "Maioria dos tecidos-alvo simpáticos. Via Gq e PLC, com IP₃ e DAG. Causa contração de músculo liso de vasos, esfíncteres e íris.", "slide": 7}, {"termo": "α2 (alfa-2)", "tecnica": "Receptor (Gi)", "definicao": "Terminações pré-sinápticas, SNC, TGI, pâncreas e plaquetas. Via Gi, com queda de AMPc. Inibe a liberação de NA e causa sedação.", "slide": 7}, {"termo": "β1 (beta-1)", "tecnica": "Receptor (Gs)", "definicao": "Coração e rim. Via Gs e AMPc. Aumenta frequência e contratilidade e libera renina.", "slide": 7}, {"termo": "β2 (beta-2)", "tecnica": "Receptor (Gs)", "definicao": "Músculo liso brônquico e vascular, útero e fígado. Relaxa e dilata vias aéreas e vasos.", "slide": 7}, {"termo": "β3 (beta-3)", "tecnica": "Receptor (Gs)", "definicao": "Tecido adiposo (lipólise) e bexiga (relaxa o detrusor).", "slide": 7}, {"termo": "Fosfolipase C (PLC)", "tecnica": "Via de sinalização", "definicao": "Enzima ativada por α1, que converte PIP2 em IP₃ e DAG.", "slide": 10}, {"termo": "Adenilil ciclase (AC)", "tecnica": "Via de sinalização", "definicao": "Enzima que converte ATP em AMPc. Ativada por Gs e inibida por Gi.", "slide": 10}, {"termo": "MAO e COMT", "tecnica": "Degradação", "definicao": "Enzimas que degradam as catecolaminas. Alvos de selegilina (MAO) e entacapona (COMT).", "slide": 6}, {"termo": "Reserpina", "tecnica": "Depletor de NA", "definicao": "Alcaloide que bloqueia o VMAT. Esgota a NA e age no neurônio, não no receptor.", "slide": 50}, {"termo": "Cocaína", "tecnica": "Inibidor da captação", "definicao": "Bloqueia o NET, o que mantém a NA na fenda por mais tempo.", "slide": 18}, {"termo": "Anfetamina", "tecnica": "Liberador de NA", "definicao": "Desloca a NA das vesículas e a libera pelo NET invertido. Efeitos centrais marcantes.", "slide": 18}, {"termo": "Efedrina e pseudoefedrina", "tecnica": "Ação mista", "definicao": "Liberam NA e ativam receptores diretamente. Usadas na incontinência urinária em cães e na descongestão.", "slide": 18}, {"termo": "Tiramina", "tecnica": "Liberador de NA", "definicao": "Amina que libera NA da terminação, com ação indireta.", "slide": 13}, {"termo": "Selegilina e entacapona", "tecnica": "Ação indireta", "definicao": "Selegilina inibe a MAO. Entacapona inibe a COMT. Ambas aumentam a NA disponível.", "slide": 13}, {"termo": "Fenilefrina", "tecnica": "Agonista α1", "definicao": "Vasoconstritor de ação sistêmica ou tópica. Não é inativada pela COMT, por isso dura mais.", "slide": 27}, {"termo": "Imidazolinas tópicas (nafazolina, oximetazolina, xilometazolina)", "tecnica": "Agonista α1", "definicao": "Descongestionantes nasais e colírios. Causam congestão de rebote com uso crônico.", "slide": 27}, {"termo": "Clonidina e metildopa", "tecnica": "Agonista α2", "definicao": "Anti-hipertensivos de uso humano. Agem no SNC para reduzir o tônus simpático.", "slide": 28}, {"termo": "Xilazina", "tecnica": "Agonista α2", "definicao": "Sedativo e analgésico veterinário. É emética em gatos. Revertida pela ioimbina.", "slide": 28}, {"termo": "Detomidina e romifidina", "tecnica": "Agonista α2", "definicao": "Sedativos e analgésicos veterinários de ação central, usados em contenção química.", "slide": 28}, {"termo": "Medetomidina e dexmedetomidina", "tecnica": "Agonista α2", "definicao": "Sedativos e analgésicos veterinários de ação central. Revertidos pelo atipamezol.", "slide": 28}, {"termo": "Atipamezol", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 mais seletivo, cerca de 8.500:1. Reverte medetomidina e dexmedetomidina.", "slide": 41}, {"termo": "Ioimbina", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 que reverte a xilazina em cães, gatos, equinos e cervídeos.", "slide": 41}, {"termo": "Tolazolina", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 que reverte a xilazina em ruminantes e equinos. Também bloqueia α1.", "slide": 41}, {"termo": "Idazoxana", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 experimental.", "slide": 41}, {"termo": "Adrenalina (epinefrina)", "tecnica": "Catecolamina", "definicao": "Agonista não seletivo. Usada em anafilaxia e parada cardiorrespiratória. Causa taquicardia e crise hipertensiva.", "slide": 21}, {"termo": "Noradrenalina (norepinefrina)", "tecnica": "Catecolamina", "definicao": "Vasoconstritor intenso, com reflexo de bradicardia. Usada em hipotensão grave e choque séptico.", "slide": 22}, {"termo": "Isoproterenol", "tecnica": "Catecolamina", "definicao": "Agonista β não seletivo, sem efeito α. Usado em bradicardia severa e bloqueio AV.", "slide": 22}, {"termo": "Dobutamina", "tecnica": "Agonista β1", "definicao": "Inotrópico de curto prazo. Faixa usual de 2,5 a 10 µg/kg/min. Ineficaz após betabloqueio.", "slide": 25}, {"termo": "Salbutamol, salmeterol, formoterol e terbutalina", "tecnica": "Agonista β2", "definicao": "Broncodilatadores. Salbutamol e terbutalina são de ação curta; salmeterol e formoterol são de ação longa.", "slide": 26}, {"termo": "Clembuterol", "tecnica": "Agonista β2", "definicao": "Broncodilatador e tocolítico, usado em equinos e bovinos. Causa tremor e taquicardia.", "slide": 26}, {"termo": "Ritodrina", "tecnica": "Agonista β2", "definicao": "Tocolítico para retardar o trabalho de parto.", "slide": 26}, {"termo": "Propranolol", "tecnica": "Betabloqueador", "definicao": "Não seletivo, β1 e β2. Usado em hipertensão, arritmias, hipertireoidismo e angina. Causa broncoconstrição.", "slide": 43}, {"termo": "Timolol", "tecnica": "Betabloqueador", "definicao": "Não seletivo. Usado topicamente no glaucoma, por reduzir a produção de humor aquoso.", "slide": 43}, {"termo": "Atenolol e metoprolol", "tecnica": "Betabloqueador", "definicao": "β1-seletivos. Usados em hipertensão, angina, infarto e ICC.", "slide": 43}, {"termo": "Esmolol", "tecnica": "Betabloqueador", "definicao": "β1-seletivo de ação ultracurta, éster hidrolisado no sangue. Usado em arritmias agudas por via IV.", "slide": 46}, {"termo": "Nebivolol", "tecnica": "Betabloqueador", "definicao": "Betabloqueador de 3ª geração que aumenta o NO, com efeito vasodilatador.", "slide": 48}, {"termo": "Carvedilol e labetalol", "tecnica": "Betabloqueador", "definicao": "Betabloqueadores de 3ª geração com bloqueio α1 adicional.", "slide": 48}, {"termo": "Pindolol e acebutolol", "tecnica": "Betabloqueador", "definicao": "Agonistas parciais (ASI), que mantêm alguma atividade simpática.", "slide": 42}, {"termo": "Fenoxibenzamina", "tecnica": "Alfabloqueador", "definicao": "Antagonista α não seletivo e irreversível, com ligação covalente.", "slide": 37}, {"termo": "Prazosina, terazosina e doxazosina", "tecnica": "Alfabloqueador", "definicao": "α1-seletivos. Usados na hipertensão e na obstrução funcional do esfíncter uretral.", "slide": 37}, {"termo": "Tansulosina", "tecnica": "Alfabloqueador", "definicao": "α1-seletivo usado na hiperplasia prostática.", "slide": 37}, {"termo": "Brimonidina", "tecnica": "Agonista α2 tópico", "definicao": "Reduz a produção de humor aquoso e aumenta a drenagem no glaucoma.", "slide": 49}, {"termo": "Feocromocitoma", "tecnica": "Doença", "definicao": "Tumor que produz catecolaminas. Uma das indicações citadas para alfabloqueadores.", "slide": 40}], "caso": {"titulo": "Caso: anafilaxia em paciente asmático com betabloqueador", "perfil": "Escolha do fármaco e efeitos de betabloqueio.", "etapas": [{"titulo": "Etapa 1: anafilaxia", "texto": "Homem de 35 anos tem anafilaxia após picada de inseto: hipotensão, edema de laringe e broncoespasmo. Chega ao pronto-socorro com pressão de 70 por 40 mmHg.", "perguntas": [{"pergunta": "Qual é o fármaco de escolha, segundo a aula?", "alts": ["Adrenalina, pelos efeitos α1, β1 e β2", "Propranolol, para reduzir a frequência cardíaca", "Dobutamina, pelo efeito inotrópico apenas", "Fenoxibenzamina, pelo bloqueio alfa irreversível", "Clonidina, pela ação central sedativa"], "erradas": ["Propranolol bloqueia β e pioraria o broncoespasmo e a hipotensão.", "Dobutamina atua em β1 e não resolve o broncoespasmo nem a vasoconstrição.", "Fenoxibenzamina bloqueia α e reduziria a pressão, o oposto do necessário.", "Clonidina causa sedação e hipotensão, sem indicação na anafilaxia."], "justificativa": "A adrenalina é o fármaco de escolha na anafilaxia, por efeitos α1, β1 e β2 (slide 21)."}]}, {"titulo": "Etapa 2: asmático em betabloqueador", "texto": "Outro paciente, asmático, usa propranolol para hipertensão. Tem broncoespasmo e precisa de broncodilatação.", "perguntas": [{"pergunta": "Por que o propranolol agrava o quadro, e qual classe de betabloqueador é preferível?", "alts": ["Bloqueia β2 brônquico; preferir β1-seletivos, que poupam os brônquios", "Ativa α1 brônquico; preferir α2-seletivos, sem efeito pulmonar", "Induz tolerância β2; preferir dopamina em dose baixa", "Libera histamina; preferir anti-histamínicos de primeira geração", "Inibe COX-2 brônquica; preferir coxibes"], "erradas": ["Propranolol não ativa α1 no brônquio; o problema é o bloqueio de β2.", "Dopamina em dose baixa atua em D1 renal e não é a escolha para broncoespasmo.", "A histamina não é o mecanismo do efeito do propranolol.", "Coxibes são anti-inflamatórios e não tratam o broncoespasmo beta."], "justificativa": "Betabloqueadores não seletivos causam broncoconstrição; β1-seletivos poupam os brônquios (slides 42 e 44)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um agonista que aumenta a força de contração do coração, com pouco efeito sobre a frequência, é indicado em choque cardiogênico. Qual é o fármaco e o receptor envolvido?", "alternativas": ["Adrenalina, agonista α1 com efeito cronotrópico negativo e vasoconstrição intensa", "Fenilefrina, agonista α1 que aumenta a frequência por reflexo barorreceptor", "Salbutamol, agonista β2 que aumenta a força de contração sem efeito sobre a frequência", "Noradrenalina, agonista α2 com inotropismo negativo e bradicardia direta no miocárdio", "Dobutamina, agonista β1 com pouco efeito cronotrópico"], "gabarito": "E", "justificativa": "Dobutamina é agonista β1: aumenta a força de contração com pouco efeito cronotrópico. Uso: choque cardiogênico e ICC descompensada (resumo: Adrenérgicos, agonistas de uso clínico).", "tecnica": "Dobutamina", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um paciente em choque séptico recebe noradrenalina e apresenta bradicardia. Por que a bradicardia ocorre, se a noradrenalina é inotrópica?", "alternativas": ["Porque a noradrenalina bloqueia os receptores β1 do coração, o que reduz diretamente a frequência cardíaca", "Porque a vasoconstrição eleva a pressão arterial, e o barorreflexo reduz a frequência cardíaca", "Porque a noradrenalina ativa diretamente os receptores muscarínicos M2, o que reduz a frequência do nó sinusal", "Porque a noradrenalina é metabolizada em adenosina no miocárdio, o que causa bradicardia por efeito direto", "Porque a noradrenalina causa hipocalemia grave, que reduz a condução no nó atrioventricular de forma imediata"], "gabarito": "B", "justificativa": "Noradrenalina causa vasoconstrição intensa, com aumento da PA. A bradicardia é reflexa, por barorreflexo ao aumento da pressão (resumo: Adrenérgicos, agonistas de uso clínico).", "tecnica": "Bradicardia reflexa", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "A dopamina tem efeito dose-dependente. Qual é a sequência de receptores e de efeitos conforme a dose aumenta?", "alternativas": ["α1 com vasoconstrição, depois β1 com inotropismo e, por fim, D1 com vasodilatação renal", "β2 com broncodilatação, depois α1 com vasoconstrição e, por fim, D1 com diurese osmótica", "D1 com vasodilatação renal, depois β1 com inotropismo e, por fim, α1 com vasoconstrição", "β1 com inotropismo, depois D1 com vasodilatação renal e, por fim, α2 com sedação central", "α2 com redução de noradrenalina, depois β2 com tremor e, por fim, α1 com midríase"], "gabarito": "C", "justificativa": "Dopamina muda de receptor conforme a dose: D1 em dose baixa (vasodilatação renal), β1 em dose intermediária (inotropismo), α1 em dose alta (vasoconstrição) (resumo: Adrenérgicos, agonistas).", "tecnica": "Dopamina dose-dependente", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um paciente em uso contínuo de descongestionante nasal tópico tem congestão ainda pior após alguns dias. Qual é o mecanismo?", "alternativas": ["Congestão por aumento da IgE nasal, que ativa mastócitos após a suspensão do descongestionante", "Congestão por bloqueio dos receptores β2 nasais, que reduz a dilatação dos vasos nasais", "Congestão por liberação de histamina pelos eosinófilos, que aumentam a permeabilidade vascular", "Congestão de rebote por dessensibilização dos receptores α1 da mucosa nasal", "Congestão por inibição da acetilcolinesterase nasal, que aumenta a secreção de muco nas vias aéreas"], "gabarito": "D", "justificativa": "O uso contínuo de descongestionante tópico leva a dessensibilização dos receptores e congestão de rebote. É distrator clássico confundir o efeito direto com o reflexo (resumo: Adrenérgicos, pegadinhas).", "tecnica": "Congestão de rebote", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente com feocromocitoma recebe fenoxibenzamina. Por que a adrenalina passa a baixar a pressão após esse tratamento?", "alternativas": ["Porque a fenoxibenzamina ativa os receptores β1, que aumentam a frequência cardíaca e reduzem a pressão", "Porque o α-bloqueio deixa a vasodilatação β2 sem oposição, e a PA cai", "Porque a fenoxibenzamina é agonista α1, e a adrenalina passa a agir apenas sobre receptores muscarínicos", "Porque a adrenalina é metabolizada pela MAO em poucos segundos, o que reduz a concentração plasmática", "Porque a fenoxibenzamina bloqueia a degranulação de mastócitos, que liberam adrenalina no feocromocitoma"], "gabarito": "B", "justificativa": "Fenoxibenzamina é α não seletivo irreversível. Após o α-bloqueio, a adrenalina passa a agir só sobre β2, com vasodilatação e queda da PA (resumo: Adrenérgicos, antagonistas α não seletivos).", "tecnica": "Reversão da adrenalina", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente asmático com DPOC precisa de betabloqueador para hipertensão. Qual classe é a mais adequada e por quê?", "alternativas": ["β não seletivo de primeira geração, como propranolol, que bloqueia β1 e β2 com igual intensidade", "Timolol tópico, que bloqueia β2 nos brônquios e reduz a produção de humor aquoso no olho", "β1 seletivo, como atenolol ou metoprolol, que poupa os receptores β2 dos brônquios", "Labetalol, que bloqueia β2 nos brônquios e a α1 nos vasos, com broncoconstrição garantida", "Esmolol, que é ultracurto e bloqueia β2 nos brônquios, sem seletividade para β1 cardíaco"], "gabarito": "C", "justificativa": "Betabloqueadores β1 seletivos (atenolol, metoprolol, bisoprolol) poupam os brônquios e são preferíveis em asma e DPOC (resumo: Adrenérgicos, antagonistas β).", "tecnica": "Betabloqueador em asma", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um diabético em uso de betabloqueador não percebe sinais de hipoglicemia. Por que isso ocorre, e o que é necessário?", "alternativas": ["O betabloqueador aumenta a glicemia por bloqueio β2 no fígado, e não há risco de hipoglicemia", "O bloqueio β mascara taquicardia e tremor; é preciso orientar o paciente quanto a esse risco", "O betabloqueador ativa a insulina endógena, que aumenta o risco de hipoglicemia sem sinal de alerta", "O betabloqueador causa diurese osmótica, e a hipoglicemia é percebida apenas pela queda de peso", "O betabloqueador impede a absorção de glicose intestinal, e a hipoglicemia só ocorre na fase de jejum"], "gabarito": "B", "justificativa": "Betabloqueadores mascaram os sinais adrenérgicos da hipoglicemia, como taquicardia e tremor. Por isso o paciente diabético precisa de orientação específica (resumo: Adrenérgicos, atenção para a prova).", "tecnica": "Betabloqueador e diabetes", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente em uso prolongado de propranolol para hipertensão suspende o fármaco de forma abrupta e tem taquicardia e crise hipertensiva. Qual é a explicação?", "alternativas": ["Reação de hipersensibilidade tipo I, com IgE contra o propranolol e degranulação de mastócitos", "Efeito de primeira passagem, que é maior após a suspensão do fármaco de uso crônico", "Intoxicação por acúmulo do metabólito ativo, que é eliminado de forma abrupta pela urina", "Efeito de indução enzimática pelo CYP3A4, que acelera a degradação do fármaco após a suspensão", "Efeito rebote por hipersensibilidade dos receptores regulados para cima"], "gabarito": "E", "justificativa": "Suspensão abrupta de betabloqueador causa rebote: os receptores, regulados para cima, respondem de forma exagerada. Por isso a suspensão deve ser gradual (resumo: Adrenérgicos, atenção para a prova).", "tecnica": "Rebote de betabloqueador", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Por que a adrenalina é o fármaco de escolha na anafilaxia, mesmo sendo um agonista e não um bloqueador de histamina?", "alternativas": ["Porque causa vasoconstrição por α1 e broncodilatação por β2, efeitos opostos aos da histamina", "Porque bloqueia o receptor H1 com alta afinidade, impedindo a histamina de causar edema nos tecidos", "Porque estabiliza o mastócito e impede a liberação de triptase, o que previne a degranulação tardia", "Porque bloqueia a IgE circulante, impedindo a reexposição ao alérgeno e a degranulação de mastócitos", "Porque inibe a COX-2 e reduz a síntese de prostaglandinas, que são as principais causas do choque"], "gabarito": "A", "justificativa": "Adrenalina produz vasoconstrição α1 e broncodilatação β2, efeitos opostos aos da histamina, sem bloquear o receptor. É antagonista fisiológico (resumo: Adrenérgicos, anafilaxia; Imunologia, tipo I).", "tecnica": "Adrenalina na anafilaxia", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um paciente recebe clonidina para hipertensão e apresenta sedação e boca seca. Qual é o mecanismo central desse efeito?", "alternativas": ["Agonismo α2 central, que reduz o tônus simpático e a pressão arterial", "Bloqueio α1 periférico, que reduz a resistência vascular e causa hipotensão postural", "Bloqueio β1 cardíaco, que reduz a frequência e a contratilidade do miocárdio", "Ativação de D1 renal, que aumenta a diurese e reduz o volume plasmático do paciente", "Inibição da COX, que reduz a produção de prostaglandinas e causa sedação por efeito direto"], "gabarito": "A", "justificativa": "Clonidina é agonista α2 central: reduz o tônus simpático e a PA. Causa sedação e boca seca (resumo: Adrenérgicos, agonistas α2).", "tecnica": "Clonidina", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um paciente em uso de reserpina para hipertensão não responde a anfetamina. Por que o fármaco é ineficaz?", "alternativas": ["A reserpina bloqueia o receptor α1, e a anfetamina depende desse receptor para agir no coração", "A reserpina ativa a MAO, que degrada a anfetamina antes de ela alcançar a fenda sináptica", "Reserpina bloqueia o VMAT; a noradrenalina não é estocada nas vesículas", "A reserpina aumenta a recaptação pelo NET, o que impede a anfetamina de entrar no neurônio", "A reserpina inibe a COMT, o que aumenta a noradrenalina e torna a anfetamina desnecessária"], "gabarito": "C", "justificativa": "Reserpina bloqueia o VMAT: a noradrenalina não entra na vesícula e é degradada pela MAO. Como a anfetamina depende de estoque vesicular para agir, o efeito é abolido (resumo: Adrenérgicos, depletor de NA).", "tecnica": "Reserpina e anfetamina", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Por que as catecolaminas são usadas por infusão intravenosa nas emergências, e não por via oral?", "alternativas": ["Têm longa duração e são bem absorvidas por via oral, mas causam hipotensão grave quando aplicadas por veia", "São bloqueadoras de receptores, o que exige infusão contínua para manter o bloqueio da fenda sináptica", "São anticolinérgicas, e a via intravenosa é necessária para evitar a degradação pela acetilcolinesterase", "Têm início rápido e duração curta, são degradadas por MAO e COMT e não funcionam por via oral", "São inibidoras da COX, o que exige administração intravenosa para evitar a lesão gástrica sistêmica"], "gabarito": "D", "justificativa": "Catecolaminas (adrenalina, noradrenalina, dopamina) têm início rápido e duração curta, são degradadas por MAO e COMT e penetram pouco no SNC. Por isso são usadas em infusão IV (resumo: Adrenérgicos, catecolaminas).", "tecnica": "Catecolaminas", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Uma anfetamina e uma cocaína têm efeito simpaticomimético indireto. Qual é a diferença de mecanismo entre elas?", "alternativas": ["A anfetamina entra pelo NET e desloca a noradrenalina das vesículas; a cocaína bloqueia a recaptação pelo NET", "A anfetamina bloqueia a recaptação pelo NET; a cocaína entra pelo NET e desloca a noradrenalina das vesículas", "A anfetamina ativa diretamente o receptor α1; a cocaína ativa diretamente o receptor β2 no músculo liso", "A anfetamina inibe a MAO; a cocaína inibe a COMT, e ambas aumentam a degradação da noradrenalina", "A anfetamina é agonista muscarínico; a cocaína é antagonista muscarínico, e ambas atuam sobre a acetilcolina"], "gabarito": "A", "justificativa": "Anfetamina entra pelo NET, desloca a noradrenalina das vesículas e inverte o transportador. Cocaína bloqueia a recaptação pelo NET. Ambas aumentam a noradrenalina na fenda (resumo: Adrenérgicos, agonistas indiretos).", "tecnica": "Anfetamina × cocaína", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um paciente recebe efedrina para hipotensão durante anestesia. Por que a efedrina tem ação mista, e qual é a diferença em relação à fenilefrina?", "alternativas": ["A efedrina atua apenas como agonista α1; a fenilefrina libera noradrenalina e ativa receptores β1 indiretamente", "A efedrina é inibidora da MAO; a fenilefrina é inibidora da COMT, e ambas aumentam a noradrenalina", "A efedrina bloqueia a recaptação pelo NET; a fenilefrina bloqueia a degradação da acetilcolina na fenda", "A efedrina é anticolinérgica; a fenilefrina é colinérgica, e ambas aumentam a frequência cardíaca", "Efedrina libera noradrenalina e ativa receptores; fenilefrina é α1 direto"], "gabarito": "E", "justificativa": "Efedrina é mista: libera noradrenalina e também ativa receptores diretamente. Fenilefrina é agonista α1 direto, sem liberar noradrenalina (resumo: Adrenérgicos, agonistas diretos, indiretos e mistos).", "tecnica": "Efedrina e fenilefrina", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um receptor α2 localizado na terminação pré-sináptica é ativado. Qual é o efeito sobre a liberação de noradrenalina?", "alternativas": ["Aumenta a liberação de noradrenalina, por ativação de Gs que eleva o AMPc na terminação", "Aumenta a liberação de adrenalina, por ativação de Gq que eleva o IP₃ na terminação", "Não altera a liberação, porque o α2 atua apenas no músculo liso dos vasos e no coração, sem efeito na terminação", "Reduz a liberação de noradrenalina, por ser um autorreceptor inibitório acoplado a Gi", "Bloqueia a recaptação de noradrenalina pelo NET, prolongando sua ação na fenda sináptica de forma intensa"], "gabarito": "D", "justificativa": "α2 é o freio pré-sináptico: acoplado a Gi, reduz AMPc e inibe a própria liberação de noradrenalina (resumo: Adrenérgicos, receptores e memorização).", "tecnica": "Receptor α2", "slide": null}], "id": "farma-gilmar-05", "titulo": "Aula 5", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-06"] = {"subtitulo": "Autacoides: histamina, serotonina, eicosanoides, PAF, cininas e AINEs", "pdf": "pdf/gilmar/aula-06.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 6 · Autacoides (Prof. Gilmar S. Erzinger)", "Brunton, Chabner e Knollmann (Goodman & Gilman); Nature Reviews Drug Discovery (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Prostanoides: produção e ação (slide 33)", "colunas": ["Sigla", "Prostanoide", "Produção", "Ação"], "linhas": [["PGD2", "Prostaglandina D2", "Mastócitos", "Vasodilatação, inibição da agregação plaquetária, relaxamento do TGI e útero"], ["PGF2α", "Prostaglandina F2α", "Miométrio", "Contração do miométrio, luteólise e broncoconstrição"], ["PGI2", "Prostaciclina", "Endotélio", "Vasodilatação, hiperalgesia, inibição da agregação, renina e natriurese"], ["PGE2", "Prostaglandina E2", "Pulmão, macrófago", "Vasodilatação, hiperalgesia, febre, proliferação celular"], ["TXA2", "Tromboxano A2", "Plaquetas", "Agregação plaquetária, vasoconstrição e broncoconstrição"]]}, "resumo": [{"titulo": "1. Inflamação e autacoides", "pontos": [{"t": "Sinais cardinais e papel da inflamação", "sub": ["A inflamação é a reação a infecção ou lesão de tecidos. Sinais cardinais: calor, rubor, edema (tumor), dor e perda de função (slide 3).", "Em algumas doenças, a resposta é exagerada e persistente, sem benefício aparente. Por isso o tratamento anti-inflamatório tem alvo nos mediadores (slide 3)."]}, {"t": "Autacoides", "sub": ["Autacoides vêm do grego autos (próprio) e akos (remédio). São substâncias naturais produzidas rapidamente em resposta a estímulos, com estruturas e ações variadas (slide 6).", "Mediadores inflamatórios citados: histamina, serotonina, eicosanoides e PAF (derivados de lipídeos), peptídeos (cininas, neuropeptídeos) e citocinas (slide 6)."]}]}, {"titulo": "2. Histamina e anti-histamínicos", "pontos": [{"t": "Origem e ações", "sub": ["A histamina é uma amina biogênica vasodilatadora, derivada da histidina. Liberada sobretudo por mastócitos e basófilos, participa da alergia com extravasamento de plasma, edema e prurido (slide 8).", "Ações: broncoconstrição, dilatação de vênulas e eritema, contração endotelial com edema e pápula, prurido e dor. Esses efeitos são H1. Aumento da secreção ácida gástrica é H2. Neurotransmissão central e vigília são H3 (slide 9)."]}, {"t": "Receptores", "sub": ["H1: Gq/11, com IP₃, DAG, Ca²⁺ e ativação do NF-κB. Está no músculo liso, endotélio e cérebro (slide 10).", "H2: Gs, com aumento do cAMP. Está nas células parietais gástricas, no músculo cardíaco, nos mastócitos e no cérebro (slide 10).", "H3: Gi/o, com queda do cAMP. Está no SNC e em alguns nervos periféricos. H4: Gi/o, com queda do cAMP e aumento do Ca²⁺, em células hematopoiéticas (slide 10)."]}, {"t": "Três estratégias para anular a histamina", "sub": ["Agonistas inversos dos receptores H1, como a difenidramina, para alergia (slides 11 e 12).", "Estabilização de mastócitos, impedindo a desgranulação induzida pelo complexo IgE/FcεR. Cromolina e nedocromil são usados na asma (slides 11 e 12).", "Antagonismo fisiológico, com adrenalina, que neutraliza funcionalmente os efeitos da histamina na anafilaxia (slides 11 e 12)."]}, {"t": "H1 de 1ª e 2ª gerações e H2", "sub": ["Bovet e Staub descobriram os primeiros anti-histamínicos H1, em 1937. Eles aliviam rinite, conjuntivite, urticária e prurido (slide 13).", "H1 bloqueiam o aumento de permeabilidade que forma edema e pápula. Têm efeito anti-inflamatório pela supressão da via NF-κB nas células imunes (slide 14).", "H1 de 1ª e 2ª gerações são igualmente eficazes na alergia. Não são efetivos contra vasculite urticariforme ou angioedema hereditário. A 1ª geração é mais lipofílica e causa mais sedação (slide 15).", "Cimetidina e ranitidina são antagonistas H2 e reduzem o ácido gástrico. Indicações: pirose (doença de refluxo) e doença ulcerosa péptica (slide 16)."]}]}, {"titulo": "3. Serotonina e triptanos", "pontos": [{"t": "Síntese, distribuição e degradação", "sub": ["A serotonina (5-HT) é neurotransmissor no cérebro e hormônio local na periferia. Síntese: triptofano, pela triptofano hidroxilase e depois dopa descarboxilase. Degradação: sobretudo pela MAO, formando 5-HIAA na urina (slide 19).", "Maior concentração: SNC (regiões do mesencéfalo); intestino, onde mais de 90% está nas células enterocromafins; plaquetas, que acumulam 5-HT por transporte ativo e liberam na agregação (slide 20)."]}, {"t": "Receptores e efeitos", "sub": ["5-HT1A: inibe AC, no autorreceptor da rafe. 5-HT1B e 5-HT1D: inibem AC e causam vasoconstrição em vasos cranianos (slide 21).", "5-HT2A: ativa PLC, em plaquetas, músculo liso e córtex. 5-HT2B: contração no estômago. 5-HT3: canal iônico, em nervos periféricos e área postrema. 5-HT4: ativa AC, no TGI e hipocampo (slide 22).", "Efeitos principais: motilidade GI, contração de brônquios e útero, vasoconstrição e vasodilatação endotélio-dependente, agregação plaquetária e ativação de nociceptores periféricos (slide 23)."]}, {"t": "Fármacos", "sub": ["Triptanos (sumatriptano, rizatriptano, zolmitriptano e outros) são agonistas 5-HT1B e 5-HT1D. Causam vasoconstrição de vasos cerebrais e meníngeos, o que reduz a enxaqueca (slide 24).", "Ondansetrona é antagonista 5-HT3, usada em náuseas e vômitos de quimioterapia, radioterapia e pós-operatório. Tegaserode e prucaloprida são agonistas parciais 5-HT4 para constipação crônica e síndrome do cólon irritável (slide 25)."]}]}, {"titulo": "4. Eicosanoides, COX e PAF", "pontos": [{"t": "Origem e cascata", "sub": ["Eicosanoides são derivados de ácidos graxos com 20 carbonos: prostaglandinas, prostaciclinas, tromboxanos e leucotrienos. O PAF é um fosfolipídeo modificado (slide 27).", "A PLA2, ativada por Ca²⁺ e fosforilação, libera o ácido araquidônico dos fosfolipídeos de membrana. Receptores 5-HT2, mGLUR1 e interferons estimulam essa ativação (slide 28).", "Via da COX: prostaglandinas e tromboxanos. Via da LOX: leucotrienos, HETE, HPETE e lipoxinas (slide 29)."]}, {"t": "COX-1 e COX-2", "sub": ["COX-1 é constitutiva: estômago, rim, plaquetas, útero e SNC. Protege a mucosa gástrica (PGE2), regula a agregação (TxA2 e PGI2) e contrai o útero (PGF2α) (slides 30 e 31).", "COX-2 é induzida em macrófagos, linfócitos, PMN e endotélio, e atua na dor e inflamação. Também é constitutiva no rim e no SNC, com função renal e transmissão nervosa (slides 30 e 31)."]}, {"t": "Prostanoides", "sub": ["PGD2 (mastócitos): vasodilatação e inibição da agregação. PGF2α (miométrio): contração, luteólise e broncoconstrição. PGI2 (endotélio): vasodilatação, hiperalgesia, natriurese. PGE2 (pulmão e macrófago): vasodilatação, hiperalgesia e febre. TXA2 (plaquetas): agregação, vasoconstrição e broncoconstrição (slide 33)."]}, {"t": "PAF", "sub": ["Fosfolipídeo mediador que aumenta a adesão celular e ativa o endotélio. A PLA2 libera o ácido graxo da fosfatidilcolina, formando liso-PC. A LPCAT adiciona um grupo acetil e forma o PAF (slide 35).", "É de 100 a 1.000 vezes mais potente que a histamina (slide 36)."]}]}, {"titulo": "5. Cininas e citocinas", "pontos": [{"t": "Cininas", "sub": ["Bradicinina e calidina são peptídeos formados por calicreínas sobre os cininogênios (slide 38).", "B1: agonista preferencial calidina, induzível; antagonista Des-Arg-Hoe 140. B2: agonista preferencial bradicinina, constitutivo; antagonista Hoe 140 (slide 39).", "Ações: vasodilatação endotélio-dependente (NO), aumento da permeabilidade das vênulas, sensibilização de terminações sensoriais e contração do músculo liso intestinal e uterino (slide 39).", "Exemplo de sinergia: a bradicinina aplicada após PGE2 aumenta a amplitude do sinal de dor em nervo ciático de rato. Isoladas, nenhuma das duas aumenta (slide 50)."]}, {"t": "Citocinas", "sub": ["São proteínas regulatórias, parácrinas e autócrinas, que controlam a resposta imune e a inflamação (slides 41 e 43).", "Interleucinas IL-1, IL-6, IL-8, IL-10 e IL-13 ativam células inflamatórias. Fatores como GM-CSF e M-CSF ativam macrófagos e células NK. Quimiocinas atraem leucócitos. Interferons: IFNα e IFNβ são antivirais; IFNγ ativa leucócitos (slide 42).", "TNFα é pró-inflamatória: causa febre, anorexia, choque e citotoxicidade, e induz outras citocinas (slide 42)."]}]}, {"titulo": "6. AINEs: mecanismo e efeitos", "pontos": [{"t": "Mecanismo", "sub": ["O principal mecanismo é a inibição das cicloxigenases, que reduz a conversão do ácido araquidônico em prostaglandinas (slide 58).", "Anti-inflamatório: diminui PGE2 e prostaciclina no tecido lesado, reduzindo vasodilatação e edema. Não trata a fonte da lesão (slide 58).", "Analgésico: reduz a sensibilização das terminações por PGE2, bradicinina e 5-HT. A cefaleia alivia por menor vasodilatação (slide 58).", "Antipirético: a IL-1 aumenta a PGE2 no hipotálamo, elevando o ponto de controle da temperatura. O AINE reduz a PGE2 no SNC (slide 58)."]}, {"t": "Efeitos colaterais", "sub": ["TGI: inibição da COX-1 suprime prostaglandinas gastroprotetoras. Pode causar dispepsia, náuseas, vômitos, lesão e hemorragia (potencialmente fatal) (slide 67).", "Renal: PGE2 e PGI2 mantêm a perfusão renal. Em insuficiência renal, pode haver piora reversível. Uso crônico em altas doses pode causar nefropatia associada a analgésicos, frequentemente irreversível (slide 68).", "Cardiovascular: uso prolongado, sobretudo de coxibes, pode causar hipertensão e predispor a AVC e infarto, pelo aumento da agregação plaquetária (slide 69).", "Outros: reações cutâneas, broncoespasmo em asmáticos sensíveis à aspirina, distúrbios hepáticos e depressão da medula óssea (slide 70)."]}]}, {"titulo": "7. Classes de AINEs", "pontos": [{"t": "Aspirina (AAS)", "sub": ["Inativa a COX-1 e a COX-2 de modo irreversível, por acetilação. Inibe a agregação plaquetária. É usada em doenças cardiovasculares. Cerca de 75% é metabolizada no fígado, com meia-vida de 4 horas (slide 60)."]}, {"t": "Paracetamol", "sub": ["Forte analgésico e antipirético, com pouca ação anti-inflamatória. Atua no SNC, em um subtipo chamado COX-3. Meia-vida de 2 a 4 horas. Em dose tóxica, causa náuseas, vômitos e lesão hepática, potencialmente fatal após 24 a 48 horas (slide 61)."]}, {"t": "Propiônicos, oxicans e coxibes", "sub": ["Propiônicos: analgésicos, antipiréticos e anti-inflamatórios. Usados na artrite gotosa aguda e na dismenorreia primária (slide 62).", "Oxicans: quase todos inibem as duas COX. O meloxicam tem leve preferência pela COX-2, cerca de 10:1, em baixas doses. Menos efeito gástrico que o AAS. Usados na artrite reumatoide e na osteoartrite (slide 63).", "Coxibes (celecoxibe, rofecoxibe): inibidores seletivos da COX-2, com menos efeito gástrico. Contraindicados em hipertensão, insuficiência cardíaca e distúrbios de coagulação. Usados em tratamentos curtos e no pós-operatório (slide 64).", "Risco cardiovascular dos coxibes: a COX-2 bloqueada deixa de inibir a agregação, e a COX-1 favorece a formação de trombos (slides 65 e 69)."]}]}, {"titulo": "8. Histamina em tabela e as três estratégias", "pontos": [{"t": "Receptores de histamina", "sub": ["H1 (Gq → ↑IP₃/DAG/Ca²⁺): músculo liso, endotélio vascular, nervos periféricos. Broncoconstrição; dilatação de vênulas pós-capilares; separação das células endoteliais → edema e pápula; prurido e dor.", "H2 (Gs → ↑AMPc): células parietais gástricas e miocárdio. ↑ secreção de ácido gástrico.", "H3 (Gi → ↓AMPc): SNC; neurotransmissor do ritmo circadiano e da vigília.", "H4 (Gi → ↓AMPc): células hematopoéticas; quimiotaxia."]}, {"t": "Três estratégias contra a histamina", "sub": ["(1) Bloquear o receptor: anti-H1 (difenidramina, loratadina), agonistas inversos; impedem a ação da histamina, não sua liberação. Os de 1.ª geração são lipofílicos e sedam; os de 2.ª geração têm eficácia equivalente sem sedação.", "(2) Impedir a degranulação: cromoglicato e nedocromil estabilizam o mastócito; usados na profilaxia da asma.", "(3) Antagonismo fisiológico: adrenalina na anafilaxia não bloqueia receptor de histamina, mas produz efeitos opostos (vasoconstrição e broncodilatação)."]}]}, {"titulo": "9. Serotonina: triptanos, antieméticos e procinéticos", "pontos": [{"t": "Receptores", "sub": ["Mais de 90% do conteúdo corporal está nas células enterocromafins do intestino; o restante distribui-se entre plaquetas e SNC.", "5-HT1B/1D em vasos cranianos e meníngeos: vasoconstrição mediada por eles é o mecanismo dos triptanos na enxaqueca.", "5-HT3 (canal iônico, zona de gatilho quimiorreceptora): alvo da ondansetrona, antiemético usado em quimioterapia e pós-operatório.", "5-HT4: estimula a motilidade gastrintestinal; alvo de agonistas parciais na constipação crônica."]}]}, {"titulo": "10. Eicosanoides, COX e prostanoides", "pontos": [{"t": "Cascata do ácido araquidônico", "sub": ["Fosfolipídeo de membrana → fosfolipase A₂ (ativada por fosforilação e ↑Ca²⁺; inibida pelos corticosteroides) → ácido araquidônico → via COX (prostaglandinas e tromboxanos) ou via LOX (leucotrienos, lipoxinas).", "Corticoide bloqueia a cascata inteira (inibe a PLA₂); AINE bloqueia só a via COX. Por isso leucotrienos continuam sendo produzidos sob AINE, o que ajuda a explicar broncoespasmo em asmáticos sensíveis ao AAS."]}, {"t": "Prostanoides", "sub": ["PGE₂ (pulmão, macrófago): vasodilatação, hiperalgesia, febre; citoproteção gástrica.", "PGI₂ (endotélio): vasodilatação, inibe a agregação plaquetária, liberação de renina.", "TXA₂ (plaquetas): agregação plaquetária, vasoconstrição, broncoconstrição.", "PGD₂ (mastócitos): vasodilatação, relaxamento do músculo liso.", "PGF₂α (miométrio): contração uterina, broncoconstrição."]}, {"t": "COX-1 × COX-2", "sub": ["COX-1, constitutiva: estômago, rim, plaquetas, útero, SNC. Citoproteção gástrica (↑ muco, ↓ ácido), agregação plaquetária (TXA₂), função renal, contração uterina.", "COX-2, induzida (e constitutiva em rim e SNC): macrófago, linfócito, neutrófilo, endotélio. Dor e inflamação; função renal e transmissão nervosa."]}]}, {"titulo": "11. AINEs: efeitos, grupos e adversos", "pontos": [{"t": "Três efeitos, um mecanismo", "sub": ["Mecanismo único: inibir a ciclo-oxigenase.", "Anti-inflamatória: ↓ PGE₂ e PGI₂ no local da lesão → menos vasodilatação e edema.", "Analgésica: ↓ sensibilização das terminações nociceptivas por PGE₂, em sinergia com bradicinina e serotonina.", "Antipirética: a IL-1 eleva a PGE₂ hipotalâmica e o ponto de ajuste térmico; o AINE reduz essa PGE₂ central."]}, {"t": "Grupos", "sub": ["AAS: inibição irreversível por acetilação de COX-1 e COX-2. Como a plaqueta não sintetiza proteína nova, a dose baixa antiagrega por toda a vida da plaqueta.", "Paracetamol: analgésico e antipirético potente, pouco anti-inflamatório. Em dose tóxica gera NAPQI (metabólito de fase I) → lesão hepática potencialmente fatal em 24–48 h.", "Oxicans: em geral não seletivos; meloxicam tem leve preferência por COX-2 em dose baixa. Uso: artrite reumatoide, osteoartrite.", "Coxibes: seletivos para COX-2. Menos lesão gástrica, mais risco cardiovascular."]}, {"t": "Adversos por sistema", "sub": ["Gastrintestinais: inibição da COX-1 constitutiva suprime prostaglandinas gastroprotetoras → dispepsia, úlcera, hemorragia.", "Renais: PGE₂ e PGI₂ mantêm vasodilatação compensatória contra noradrenalina e angiotensina II. Em idosos, insuficiência cardíaca ou hipovolemia, o AINE precipita insuficiência renal; uso crônico em dose alta causa nefropatia analgésica.", "Cardiovasculares: hipertensão e risco trombótico. Também reações cutâneas, broncoespasmo e distúrbios hepáticos."]}, {"t": "Pegadinha: por que o coxibe é protrombótico", "sub": ["PGI₂ endotelial (produzida pela COX-2) é antiagregante; TXA₂ plaquetário (produzido pela COX-1) é pró-agregante.", "O coxibe inibe a COX-2 e poupa a COX-1: suprime o antiagregante e deixa o pró-agregante intacto → desequilíbrio a favor da trombose. É o inverso do raciocínio do AAS em dose baixa."]}]}, {"titulo": "12. Correção científica: paracetamol e COX-3", "pontos": [{"t": "Matiz sobre o mecanismo", "sub": ["O slide atribui o perfil do paracetamol a uma \"COX-3\". A COX-3 foi descrita como variante de splicing do gene da COX-1 em córtex cerebral canino (Kis, Snipes & Busija, J Pharmacol Exp Ther, 2005;315:1-7).", "Em roedores e humanos, a COX-3 codifica proteínas com sequência diferente e sem atividade de ciclo-oxigenase; uma isoforma funcional nunca foi sequenciada em humanos (Przybyła et al., Eur J Clin Pharmacol, 2021).", "Mecanismo aceito hoje é multifatorial: inibição da COX central, favorecida pelo baixo nível de peróxidos no SNC (explica a fraca ação anti-inflamatória em tecidos periféricos ricos em peróxido), e ação do metabólito AM404 sobre as vias endocanabinoide e TRPV1.", "Para a prova, responda o que está no slide, mas saiba que a COX-3 não é mais a explicação aceita."]}]}, {"titulo": "13. Pontes com Imunologia e Microbiologia", "pontos": [{"t": "Febre, LPS e PGE₂", "sub": ["LPS (Microbiologia) → TLR4 → TNF-α, IL-1 e IL-6 (Imunologia) → PGE₂ hipotalâmica causa febre → é exatamente o alvo dos AINEs.", "Mastócito e histamina: anti-H1 atua na fase imediata; corticoide, na fase tardia (aula 7 de Imunologia).", "Leucotrienos e asma: β2-agonista relaxa o músculo liso (resgate); corticoide bloqueia a PLA₂ acima de toda a cascata (manutenção)."]}]}, {"titulo": "14. Para a prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Autacoide, mediador e receptor: H1 (Gq), H2 (Gs), H3 e H4 (Gi/o) (slides 6 e 10).", "COX-1 protege a mucosa e regula plaquetas; COX-2 é a da inflamação. LOX gera leucotrienos (slides 29 a 31).", "Efeitos dos AINEs: TGI, rim, coração e pele. O paracetamol age na COX-3 do SNC e tem toxicidade hepática (slides 61 e 67 a 70)."]}]}], "glossario": [{"termo": "Autacoide", "tecnica": "Conceito", "definicao": "Substância natural produzida rapidamente em resposta a estímulos, com ação local.", "slide": 6}, {"termo": "PAF", "tecnica": "Mediador lipídico", "definicao": "Fator ativador plaquetário, mediador fosfolipídico que aumenta a adesão celular, 100 a 1.000 vezes mais potente que a histamina.", "slide": 36}, {"termo": "COX-1 e COX-2", "tecnica": "Cicloxigenases", "definicao": "COX-1 constitutiva (estômago, plaquetas, rim); COX-2 induzida na inflamação; alvo dos AINEs.", "slide": 30}, {"termo": "Coxibes", "tecnica": "AINE seletivo", "definicao": "Inibidores seletivos da COX-2, como celecoxibe e rofecoxibe, com menos efeito gástrico.", "slide": 64}, {"termo": "Nefropatia associada a analgésicos", "tecnica": "Efeito renal", "definicao": "Lesão renal por uso contínuo de altas doses de AINEs, frequentemente irreversível.", "slide": 68}, {"termo": "5-HT3", "tecnica": "Receptor da serotonina", "definicao": "Canal iônico da zona de gatilho; alvo da ondansetrona contra náuseas.", "slide": 22}, {"termo": "Primeiros anti-histamínicos H1 (epônimo: Bovet e Staub)", "tecnica": "Anti-histamínicos H1", "definicao": "Bovet e Staub descreveram os primeiros anti-histamínicos H1, em 1937.", "slide": 13}, {"termo": "Histamina", "tecnica": "Mediador", "definicao": "Amina biogênica vasodilatadora, derivada da histidina. Liberada por mastócitos e basófilos.", "slide": 8}, {"termo": "Receptor H1", "tecnica": "Receptor (Gq)", "definicao": "Broncoconstrição, eritema, edema, prurido e dor. Via Gq e NF-κB.", "slide": 10}, {"termo": "Receptor H2", "tecnica": "Receptor (Gs)", "definicao": "Secreção de ácido gástrico nas células parietais. Via Gs e AMPc.", "slide": 10}, {"termo": "Receptor H3", "tecnica": "Receptor (Gi/o)", "definicao": "Modula neurotransmissão no SNC e vigília. Via Gi/o.", "slide": 10}, {"termo": "Receptor H4", "tecnica": "Receptor (Gi/o)", "definicao": "Presente em células hematopoiéticas e na mucosa gástrica. Eleva Ca²⁺ intracelular.", "slide": 10}, {"termo": "Difenidramina", "tecnica": "Anti-histamínico H1", "definicao": "Agonista inverso do H1, de primeira geração, lipofílico. Causa sedação. Usado em alergia.", "slide": 11}, {"termo": "Anti-histamínicos H1 de primeira e segunda geração", "tecnica": "Anti-histamínico H1", "definicao": "Igualmente eficazes na alergia. A primeira geração é mais lipofílica e sedativa.", "slide": 15}, {"termo": "Cromolina e nedocromil", "tecnica": "Estabilizador de mastócitos", "definicao": "Impedem a desgranulação dos mastócitos. Usados na asma.", "slide": 11}, {"termo": "Cimetidina e ranitidina", "tecnica": "Antagonista H2", "definicao": "Antagonistas seletivos de H2 que reduzem a secreção ácida. Usados na pirose e na doença ulcerosa.", "slide": 16}, {"termo": "Serotonina (5-HT)", "tecnica": "Mediador", "definicao": "Neurotransmissor no cérebro e hormônio local na periferia. Sintetizada do triptofano. Degradada pela MAO.", "slide": 19}, {"termo": "Triptofano hidroxilase e dopa descarboxilase", "tecnica": "Síntese", "definicao": "Enzimas que transformam o triptofano em 5-hidroxitriptofano e depois em serotonina.", "slide": 19}, {"termo": "5-HIAA (ácido 5-hidroxi-indolacético)", "tecnica": "Metabólito", "definicao": "Principal metabólito da serotonina, eliminado na urina.", "slide": 19}, {"termo": "Receptor 5-HT1A", "tecnica": "Receptor (Gi)", "definicao": "Autorreceptor nos núcleos da rafe. Inibe a adenilato ciclase. Agonistas: buspirona e 8-OH-DPAT.", "slide": 21}, {"termo": "Receptores 5-HT1B e 5-HT1D", "tecnica": "Receptor (Gi)", "definicao": "Em vasos cerebrais e meníngeos. Causam vasoconstrição. Alvo dos triptanos.", "slide": 21}, {"termo": "Sumatriptano e triptanos", "tecnica": "Agonista 5-HT1B/1D", "definicao": "Causam vasoconstrição de vasos cerebrais e meníngeos. Usados na enxaqueca.", "slide": 24}, {"termo": "Receptor 5-HT2A", "tecnica": "Receptor (Gq)", "definicao": "Plaquetas, músculo liso e córtex. Ativa a PLC. Antagonistas: cetanserina e risperidona.", "slide": 22}, {"termo": "Receptor 5-HT3", "tecnica": "Canal iônico", "definicao": "Nervos periféricos e área postrema. Canal que excita o neurônio. Antagonista: ondansetrona.", "slide": 22}, {"termo": "Ondansetrona", "tecnica": "Antagonista 5-HT3", "definicao": "Antiemético. Atua na zona de gatilho quimiorreceptora. Usado em quimioterapia e pós-operatório.", "slide": 25}, {"termo": "Receptor 5-HT4", "tecnica": "Receptor (Gs)", "definicao": "Hipocampo e TGI. Estimula a motilidade intestinal. Agonistas: cisaprida e renzaprida.", "slide": 22}, {"termo": "Tegaserode e prucaloprida", "tecnica": "Agonista 5-HT4 parcial", "definicao": "Estimulam a motilidade intestinal. Usados na constipação crônica e na síndrome do cólon irritável.", "slide": 25}, {"termo": "Eicosanoides", "tecnica": "Mediador", "definicao": "Derivados de ácidos graxos de 20 carbonos: prostaglandinas, prostaciclinas, tromboxanos e leucotrienos.", "slide": 27}, {"termo": "Fosfolipase A2 (PLA2)", "tecnica": "Enzima", "definicao": "Libera o ácido araquidônico dos fosfolipídios de membrana. Ativada por Ca²⁺ e fosforilação.", "slide": 28}, {"termo": "Ácido araquidônico", "tecnica": "Precursor", "definicao": "Ácido graxo de 20 carbonos liberado da membrana. Origem das prostaglandinas e leucotrienos.", "slide": 28}, {"termo": "Cicloxigenase (COX)", "tecnica": "Enzima", "definicao": "Converte o ácido araquidônico em prostaglandinas e tromboxanos. Alvo dos AINEs.", "slide": 29}, {"termo": "Lipoxigenase (LOX)", "tecnica": "Enzima", "definicao": "Converte o ácido araquidônico em leucotrienos, HETE, HPETE e lipoxinas.", "slide": 29}, {"termo": "PGE2", "tecnica": "Prostanoide", "definicao": "Vasodilatação, hiperalgesia, febre e proliferação celular. Protege a mucosa gástrica.", "slide": 33}, {"termo": "PGI2 (prostaciclina)", "tecnica": "Prostanoide", "definicao": "Vasodilatação, inibe a agregação plaquetária e causa natriurese. Produzida pelo endotélio.", "slide": 33}, {"termo": "TXA2 (tromboxano A2)", "tecnica": "Prostanoide", "definicao": "Agregação plaquetária, vasoconstrição e broncoconstrição. Produzido nas plaquetas.", "slide": 33}, {"termo": "PGF2α", "tecnica": "Prostanoide", "definicao": "Contrai o miométrio, causa luteólise e broncoconstrição.", "slide": 33}, {"termo": "PGD2", "tecnica": "Prostanoide", "definicao": "Liberada pelos mastócitos. Causa vasodilatação e inibe a agregação plaquetária.", "slide": 33}, {"termo": "LPCAT (lisofosfatidilcolina aciltransferase)", "tecnica": "Enzima", "definicao": "Adiciona o grupo acetil à liso-PC e forma PAF.", "slide": 35}, {"termo": "Cininas (bradicinina e calidina)", "tecnica": "Peptídeos", "definicao": "Formadas por calicreínas a partir dos cininogênios. Causam vasodilatação, permeabilidade e dor.", "slide": 38}, {"termo": "Calicreína e cininogênio", "tecnica": "Enzima e substrato", "definicao": "Calicreína cliva os cininogênios em bradicinina e calidina.", "slide": 38}, {"termo": "Receptor B1 (cinina)", "tecnica": "Receptor", "definicao": "Induzível. Agonista preferencial é a calidina. Antagonista: Des-Arg-Hoe 140.", "slide": 39}, {"termo": "Receptor B2 (cinina)", "tecnica": "Receptor", "definicao": "Constitutivo. Agonista preferencial é a bradicinina. Antagonista: Hoe 140.", "slide": 39}, {"termo": "Hoe 140 e Des-Arg-Hoe 140", "tecnica": "Antagonista de cinina", "definicao": "Antagonistas dos receptores B2 e B1, respectivamente.", "slide": 39}, {"termo": "IL-1, IL-6, IL-8, IL-10 e IL-13", "tecnica": "Interleucinas", "definicao": "Ativam células inflamatórias. IL-1 e IL-6 têm papel pró-inflamatório. IL-10 é anti-inflamatória.", "slide": 42}, {"termo": "TNF-α", "tecnica": "Citocina pró-inflamatória", "definicao": "Causa febre, anorexia, choque e citotoxicidade, e ativa células endoteliais.", "slide": 42}, {"termo": "IFN-α, IFN-β e IFN-γ", "tecnica": "Interferons", "definicao": "Antivirais, e ativam leucócitos. IFN-γ é o principal ativador de macrófagos.", "slide": 42}, {"termo": "GM-CSF e M-CSF", "tecnica": "Fatores de crescimento", "definicao": "Ativam macrófagos e células dendríticas e NK.", "slide": 42}, {"termo": "Quimiocinas (CC, CXC, XC e CX3C)", "tecnica": "Quimiotaxinas", "definicao": "Atraem leucócitos ao local da inflamação.", "slide": 42}, {"termo": "AAS (ácido acetilsalicílico)", "tecnica": "AINE", "definicao": "Inativa COX-1 e COX-2 de modo irreversível, por acetilação. Inibe a agregação plaquetária.", "slide": 60}, {"termo": "Paracetamol", "tecnica": "Analgésico e antipirético", "definicao": "Forte analgésico e antipirético, com pouca ação anti-inflamatória. Atua no SNC, por COX-3. Hepatotóxico em dose alta.", "slide": 61}, {"termo": "Propiônicos", "tecnica": "AINE", "definicao": "Analgésicos, antipiréticos e anti-inflamatórios. Usados na artrite gotosa aguda e na dismenorreia.", "slide": 62}, {"termo": "Oxicans e meloxicam", "tecnica": "AINE", "definicao": "Inibidores quase não seletivos da COX. Meloxicam tem leve preferência pela COX-2, cerca de 10:1.", "slide": 63}, {"termo": "Broncoespasmo por sensibilidade à aspirina", "tecnica": "Efeito adverso", "definicao": "Asmáticos sensíveis à aspirina podem ter broncoespasmo com AINEs.", "slide": 70}, {"termo": "NF-κB", "tecnica": "Via de sinalização", "definicao": "Fator de transcrição que regula a inflamação. Os anti-histamínicos H1 suprimem essa via.", "slide": 14}, {"termo": "Sinais cardinais da inflamação", "tecnica": "Conceito", "definicao": "Calor, rubor, edema (tumor), dor e perda de função.", "slide": 3}], "caso": {"titulo": "Caso: asmático sensível à aspirina com dor", "perfil": "Broncoespasmo por AINE e risco de sangramento por COX-1.", "etapas": [{"titulo": "Etapa 1: broncoespasmo após AINE", "texto": "Mulher de 40 anos, asmática, toma ácido acetilsalicílico para cefaleia e evolui com broncoespasmo e sibilos minutos depois.", "perguntas": [{"pergunta": "Qual é o mecanismo mais provável do broncoespasmo, segundo a aula?", "alts": ["Inibição da COX com desvio do ácido araquidônico para leucotrienos broncoconstritores", "Ativação de receptores H2 brônquicos pela histamina liberada", "Bloqueio de receptores beta-2 pelo ácido acetilsalicílico", "Ativação de receptores 5-HT3 pulmonares pela serotonina", "Inibição da COX-2, que aumenta a produção de PGE2 brônquica"], "erradas": ["Receptores H2 não são o mecanismo do broncoespasmo descrito.", "O ácido acetilsalicílico não atua como bloqueador beta-2.", "Receptores 5-HT3 não são o mecanismo citado para a asma por AINE.", "Inibir COX-2 reduz prostaglandinas, e não aumenta PGE2."], "justificativa": "A aula cita broncoespasmo em asmáticos sensíveis à aspirina entre os efeitos dos AINEs (slide 70). O desvio para leucotrienos é um mecanismo comum da via da lipoxigenase (slide 29)."}]}, {"titulo": "Etapa 2: sangramento em idoso", "texto": "Homem de 72 anos, usando AINE não seletivo por artrose, tem melena e queda de hemoglobina. A endoscopia mostra úlcera gástrica.", "perguntas": [{"pergunta": "Qual é o mecanismo do sangramento, segundo a aula?", "alts": ["Inibição da COX-1, com perda de prostaglandinas gastroprotetoras", "Inibição da COX-2, com excesso de tromboxano na mucosa", "Ativação da histamina H1, com aumento da secreção gástrica", "Bloqueio dos receptores 5-HT4, com redução da motilidade", "Estímulo de PAF, com vasodilatação da submucosa"], "erradas": ["A inibição da COX-2 não é o mecanismo gastrointestinal central, segundo a aula.", "Excesso de tromboxano não é o mecanismo descrito para a úlcera.", "Histamina H1 não é o mecanismo de sangramento pelo AINE.", "Receptores 5-HT4 estimulam a motilidade, e não causam a lesão descrita."], "justificativa": "Os efeitos indesejados no TGI são principalmente pela inibição da COX-1 constitutiva, que suprime as prostaglandinas gastroprotetoras (slide 67)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um anti-H1 de primeira geração é prescrito para alergia, e o paciente relata sonolência intensa. Qual característica farmacológica explica esse efeito?", "alternativas": ["Lipofilia, que permite atravessar a barreira hematoencefálica", "Hidrofilia extrema, que impede a absorção e concentra o fármaco no trato gastrointestinal", "Ligação total à albumina, que impede a distribuição ao cérebro e reduz a sedação esperada", "Ação sobre H2 gástrico, que reduz a secreção ácida e causa sonolência por hipocalemia", "Ação sobre o receptor H4 da medula, que inibe a vigília por ação de Gi no tronco cerebral"], "gabarito": "A", "justificativa": "Anti-H1 de primeira geração são lipofílicos e atravessam a barreira hematoencefálica, causando sedação. Os de segunda geração têm eficácia equivalente sem sedação (resumo: Autacoides, histamina).", "tecnica": "Anti-H1 e sedação", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um paciente tem crise de urticária sustentada por citocinas, sem resposta ao anti-H1. Qual é a estratégia farmacológica mais coerente, pela lógica de aula?", "alternativas": ["Mais uma dose de anti-H1, porque a histamina é o único mediador da fase tardia da reação", "Cromoglicato em dose alta, porque ele bloqueia citocinas e a degranulação ao mesmo tempo", "Adrenalina em infusão contínua, porque ela bloqueia citocinas e os receptores de histamina H1", "Corticosteroide, que inibe a cascata de fase tardia sustentada por citocinas", "Ondansetrona, porque o receptor 5-HT3 é o principal mediador da fase tardia da urticária"], "gabarito": "D", "justificativa": "Anti-H1 resolve a fase imediata (histamina pré-formada). A crise sustentada por citocinas exige corticosteroide, que inibe a PLA2 e a cascata inteira (resumo: Autacoides, estratégias contra a histamina).", "tecnica": "Fase tardia e corticoide", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um antiemético é usado em quimioterapia e atua no receptor 5-HT3. Qual é a localização desse receptor e por que ele é alvo útil?", "alternativas": ["Canal iônico na zona de gatilho quimiorreceptora; a ondansetrona bloqueia esse canal", "Receptor acoplado a Gi nas células parietais gástricas; a ondansetrona estimula a secreção de ácido", "Receptor de histamina no endotélio; a ondansetrona aumenta a permeabilidade vascular no intestino", "Receptor adrenérgico β2 no músculo liso brônquico; a ondansetrona causa broncodilatação intensa", "Receptor muscarínico M3 no detrusor; a ondansetrona contrai a bexiga e reduz a retenção urinária"], "gabarito": "A", "justificativa": "5-HT3 é canal iônico na zona de gatilho quimiorreceptora. A ondansetrona bloqueia esse canal e é usada em quimioterapia e pós-operatório (resumo: Autacoides, serotonina).", "tecnica": "5-HT3 e ondansetrona", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um triptano é usado na enxaqueca. Qual receptor de serotonina ele ativa, e qual é o efeito que contribui para o alívio da dor?", "alternativas": ["5-HT3, com estimulação da motilidade gastrintestinal em todo o trato digestivo", "5-HT1B/1D, com vasoconstrição mediada em vasos cranianos e meníngeos", "5-HT4, com relaxamento do músculo liso brônquico por ação de Gs no pulmão", "5-HT2A, com aumento da permeabilidade vascular cerebral e formação de edema", "5-HT1A, com inibição da síntese de prostaglandinas nos vasos cerebrais"], "gabarito": "B", "justificativa": "Triptanos atuam em 5-HT1B/1D, causando vasoconstrição em vasos cranianos e meníngeos. É o mecanismo do alívio na enxaqueca (resumo: Autacoides, serotonina).", "tecnica": "Triptanos", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "A fosfolipase A2 libera ácido araquidônico, que segue para COX ou LOX. Por que o corticosteroide tem efeito anti-inflamatório mais amplo que o AINE?", "alternativas": ["Porque ativa a COX-2 de forma seletiva, o que reduz a síntese de leucotrienos na via LOX", "Porque bloqueia o receptor de leucotrieno, o que reduz a broncoconstrição mas não a inflamação", "Porque inibe a COX-1 e a COX-2 de forma reversível, sem efeito sobre a via LOX ou sobre a PLA2", "Porque reduz a produção de tromboxano, o que impede a agregação plaquetária e a inflamação tecidual", "Porque inibe a fosfolipase A2, bloqueando as vias COX e LOX; o AINE bloqueia apenas a via COX"], "gabarito": "E", "justificativa": "Corticosteroide inibe a PLA2, bloqueando toda a cascata de ácido araquidônico (COX e LOX). AINE inibe apenas a COX, por isso leucotrienos continuam sendo produzidos (resumo: Autacoides, eicosanoides).", "tecnica": "PLA2 × COX", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente asmático sensível ao AAS tem broncoespasmo ao usar um AINE. Qual é a explicação farmacológica mais coerente?", "alternativas": ["O AINE ativa diretamente o receptor β2 nos brônquios, o que causa broncoconstrição paradoxal", "O AINE aumenta a produção de IgE, que ativa mastócitos nos brônquios de forma imediata", "O AINE desvia o ácido araquidônico para a via LOX, aumentando os leucotrienos", "O AINE inibe a PLA2, o que aumenta a produção de histamina pelos mastócitos da mucosa", "O AINE bloqueia o receptor H1, o que aumenta a broncoconstrição mediada por acetilcolina"], "gabarito": "C", "justificativa": "Com a COX bloqueada, o ácido araquidônico é desviado para a via LOX, e os leucotrienos continuam sendo produzidos e causam broncoespasmo nos asmáticos sensíveis ao AAS (resumo: Autacoides, eicosanoides).", "tecnica": "Asma sensível ao AAS", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Por que o AAS em dose baixa é usado como antiagregante plaquetário por longo prazo, e não apenas por poucos dias?", "alternativas": ["A inibição é reversível e cessa em poucas horas, o que exige dose contínua para manter a antiagregação", "O AAS aumenta a síntese de PGI2 no endotélio, que se torna antiagregante por longo prazo", "O AAS ativa o receptor P2Y12, que bloqueia a agregação plaquetária de forma reversível e rápida", "O AAS inibe a COX-2 de forma seletiva, que é a principal enzima das plaquetas em repouso", "A inibição é irreversível, e a plaqueta não sintetiza nova COX-1; o efeito dura a vida da plaqueta"], "gabarito": "E", "justificativa": "O AAS inibe a COX-1 de forma irreversível, por acetilação. A plaqueta não sintetiza proteína nova, por isso a dose baixa antiagrega durante toda a vida da plaqueta (resumo: Autacoides, AINEs).", "tecnica": "AAS e irreversibilidade", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um coxibe é associado a maior risco trombótico. Qual é o equilíbrio de prostaglandinas que explica esse efeito?", "alternativas": ["PGI2 endotelial, pró-agregante e produzida pela COX-1, é preservada; TXA2 plaquetário é suprimido", "PGI2 endotelial antiagregante, produzida pela COX-2, é suprimida; TXA2 fica intacto", "PGE2 renal, antiagregante e produzida pela COX-1, é aumentada; TXA2 plaquetário é reduzido", "PGD2 mastocitária, pró-agregante e produzida pela COX-2, é aumentada; PGF2α uterina é reduzida", "PGF2α uterina, antiagregante e produzida pela COX-2, é aumentada; TXA2 é inibido pelo coxibe"], "gabarito": "B", "justificativa": "PGI2 endotelial (COX-2) é antiagregante; TXA2 plaquetário (COX-1) é pró-agregante. Coxibes inibem a COX-2 e poupam a COX-1, suprimindo o antiagregante e deixando o pró-agregante intacto (resumo: Autacoides, pegadinha do coxibe).", "tecnica": "Coxibe e trombose", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um idoso com insuficiência cardíaca toma AINE e tem piora renal. Por que o AINE piora a função renal nesse paciente?", "alternativas": ["O AINE aumenta a produção de noradrenalina no rim, o que causa vasoconstrição intensa e necrose tubular", "O AINE ativa a COX-2 no rim, que produz tromboxano em excesso e causa obstrução das arteríolas", "O AINE bloqueia a angiotensina II, o que reduz a filtração glomerular de forma imediata e irreversível", "PGE2 e PGI2 mantêm a vasodilatação compensatória contra noradrenalina e angiotensina II; o AINE as suprime", "O AINE aumenta a retenção de sódio por ativação de receptores α2, que elevam a pressão na arteríola aferente"], "gabarito": "D", "justificativa": "No rim, PGE2 e PGI2 mantêm vasodilatação compensatória. Em quem depende dessa compensação (idoso, ICC, hipovolemia), o AINE precipita insuficiência renal (resumo: Autacoides, adversos renais).", "tecnica": "AINE e rim", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Uma mulher em tratamento de artrite reumatoide com AINE tem dispepsia e sangramento digestivo. Qual é a explicação mais coerente, pela lógica de COX-1 e COX-2?", "alternativas": ["A COX-2 é ativada no estômago, e a PGI2 produzida passa a causar sangramento e lesão da mucosa", "A COX-1 constitutiva é inibida; caem as prostaglandinas gastroprotetoras", "A histamina H2 aumenta a secreção ácida, e o AINE bloqueia o receptor 5-HT3 da mucosa gástrica", "O AINE estimula a PLA2 gástrica, o que aumenta o ácido araquidônico e causa úlcera direta", "O AINE aumenta a IgE na mucosa gástrica, o que causa degranulação de mastócitos e sangramento"], "gabarito": "B", "justificativa": "A COX-1 constitutiva produz prostaglandinas gastroprotetoras (aumentam muco e reduzem ácido). Sua inibição causa dispepsia, úlcera e hemorragia (resumo: Autacoides, adversos gastrintestinais).", "tecnica": "AINE e estômago", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um estudante afirma que o paracetamol é anti-inflamatório potente, como os AINEs. Qual correção é a mais precisa?", "alternativas": ["É anti-inflamatório mais potente que os AINEs, mas não tem efeito analgésico e nem antipirético", "É anti-inflamatório e antiagregante, com efeito semelhante ao AAS em dose baixa para todos os pacientes", "É inibidor seletivo da COX-2, como os coxibes, e por isso causa trombose com maior frequência", "É imunossupressor, usado em artrite reumatoide por bloquear a ativação de linfócitos T auxiliares", "É analgésico e antipirético potente, com pouco efeito anti-inflamatório periférico"], "gabarito": "E", "justificativa": "Paracetamol é analgésico e antipirético potente, pouco anti-inflamatório. Em dose tóxica gera NAPQI, que causa lesão hepática (resumo: Autacoides, AINEs e paracetamol).", "tecnica": "Paracetamol", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Em uma intoxicação com paracetamol em dose alta, a lesão hepática tem explicação metabólica. Qual é o metabólito de fase I e por que a conjugação não o neutraliza?", "alternativas": ["Glicuronídeo; a glicuronidação é reversível e libera o paracetamol ativo na circulação sistêmica", "Sulfato de paracetamol; a sulfatação é inibida pelo CYP3A4 e o sulfato se acumula no fígado", "Acetilcolina; a fase I libera acetilcolina no fígado, que danifica os hepatócitos por excesso de estímulo", "NAPQI; a conjugação com glutationa se satura e o metabólito se acumula no hepatócito", "Histamina; a fase I converte o paracetamol em histamina, que causa necrose centrolobular do fígado"], "gabarito": "D", "justificativa": "Em dose tóxica, o paracetamol gera NAPQI na fase I. Com a glutationa esgotada, o NAPQI se acumula e lesa o hepatócito em 24 a 48 horas (resumo: Autacoides, paracetamol; Farmacocinética, metabolismo).", "tecnica": "NAPQI", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um aluno afirma que o paracetamol age pela COX-3, como indicado no slide. Qual é a correção mais precisa segundo a aula e a literatura citada?", "alternativas": ["COX-3 é variante de splicing da COX-1 em córtex canino, sem isoforma humana funcional", "COX-3 é uma isoforma humana funcional, sequenciada no fígado, e é a principal alvo dos AINEs", "COX-3 é o nome da enzima que converte histamina em prostaglandina no tecido endotelial humano", "COX-3 é o receptor de paracetamol na membrana do hepatócito, que ativa a fase II do metabolismo", "COX-3 é a enzima que converte PGE2 em tromboxano, e é inibida pelos coxibes em todos os tecidos"], "gabarito": "A", "justificativa": "A COX-3 foi descrita como variante de splicing da COX-1 em córtex canino, sem isoforma funcional sequenciada em humanos. O mecanismo aceito é multifatorial, com inibição central da COX e metabólito AM404 (resumo: Autacoides, complemento externo; Kis et al., 2005).", "tecnica": "COX-3 e paracetamol", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "A cascata de LPS descrita em aula liga Microbiologia, Imunologia e Farmacologia. Qual é o elo farmacológico dessa cascata?", "alternativas": ["Histamina pré-formada, que causa edema e é o alvo dos anti-H1 de segunda geração", "Acetilcolina na placa motora, que causa fraqueza e é o alvo da piridostigmina", "PGE2 hipotalâmica, que causa febre e é o alvo dos AINEs", "Noradrenalina no coração, que causa taquicardia e é o alvo da dobutamina de uso crônico", "Serotonina nas plaquetas, que causa agregação e é o alvo dos triptanos na enxaqueca"], "gabarito": "C", "justificativa": "LPS → TLR4 → TNF-α, IL-1 e IL-6 → PGE2 hipotalâmica, que eleva o ponto de ajuste térmico. Esse é o elo com os AINEs, que inibem a COX e reduzem a PGE2 central (resumo: Integração e pontes entre as matérias).", "tecnica": "LPS e febre", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Qual receptor de histamina é o alvo dos anti-H2, usados para reduzir a acidez gástrica?", "alternativas": ["H1, no músculo liso e no endotélio, acoplado a Gq e com aumento de IP₃ e DAG", "H3, no SNC, acoplado a Gi e com redução de AMPc, regulando o ritmo circadiano e a vigília do paciente", "H2, nas células parietais gástricas, acoplado a Gs e com aumento de AMPc", "H4, nas células hematopoéticas, acoplado a Gi, com função de quimiotaxia celular e migração de leucócitos", "H1, nas células parietais gástricas, acoplado a Gi, com redução de AMPc e secreção ácida diminuída"], "gabarito": "C", "justificativa": "H2 está nas células parietais gástricas, é acoplado a Gs e aumenta AMPc, com aumento da secreção ácida. Anti-H2 bloqueia esse efeito (resumo: Autacoides, histamina).", "tecnica": "Receptor H2", "slide": null}], "id": "farma-gilmar-06", "titulo": "Aula 6", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
