window.INDICE_AGRESSAO["gilmar"] = [{"id": "farma-gilmar-01", "titulo": "Aula 1", "subtitulo": "Introdução: vocabulário, formas farmacêuticas, áreas e nomenclatura"}, {"id": "farma-gilmar-02", "titulo": "Aula 2", "subtitulo": "Farmacocinética: ADME, biodisponibilidade, metabolismo e doses"}, {"id": "farma-gilmar-03", "titulo": "Aula 3", "subtitulo": "Etapas do desenvolvimento de fármacos: pré-clínica, fases I a IV"}, {"id": "farma-gilmar-04", "titulo": "Aula 4", "subtitulo": "Colinérgicos e anticolinérgicos, anticolinesterásicos e nicotínicos"}, {"id": "farma-gilmar-05", "titulo": "Aula 5", "subtitulo": "Adrenérgicos e antiadrenérgicos: agonistas, bloqueadores e receptores"}, {"id": "farma-gilmar-06", "titulo": "Aula 6", "subtitulo": "Autacoides: histamina, serotonina, eicosanoides, PAF, cininas e AINEs"}];
